import { Book } from "@/lib/types";

export const leviticus: Book = {
  id: "leviticus",
  name: "3. Mose",
  shortName: "3.Mose",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und der HERR rief Mose*, und er redete zu ihm aus dem Zelt der Begegnung*:", heading: "Brandopfer", footnotes: ["℘ 2Mo 3,4", "℘ 2Mo 25,22; 4Mo 1,1"] },
      { number: 2, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ein Mensch von euch dem HERRN eine Opfergabe* darbringen will, sollt ihr vom Vieh, von den Rindern und Schafen, eure Opfergabe darbringen*.", footnotes: ["hebr. korban; d. i. Geschenk; der allgemeinste Ausdruck für eine Opfergabe\n℘ 4Mo 5,15", "℘ Kap. 22,18.19; Esr 3,5"] },
      { number: 3, text: "Wenn seine Opfergabe ein Brandopfer* von den Rindern ist, soll er sie darbringen, ein männliches <Tier> ohne Fehler*. Am Eingang des Zeltes der Begegnung soll er sie darbringen, zum Wohlgefallen für ihn vor dem HERRN.", footnotes: ["℘ Kap. 6,2; 1Mo 8,20; 2Chr 29,32; 35,12; Hes 40,39", "℘ Kap. 3,1; 4,3; 5,15; 9,2; 14,10; 22,19.20; 23,12.18; 2Mo 12,5; 4Mo 19,2"] },
      { number: 4, text: "Und er soll seine Hand auf den Kopf des Brandopfers legen*, und es wird als wohlgefällig angenommen werden für ihn, um Sühnung für ihn zu erwirken*.", footnotes: ["℘ Kap. 3,2; 4,4; 16,21; 2Mo 29,10.15.19; Hebr 6,2", "℘ Hes 45,15; 1Jo 2,2"] },
      { number: 5, text: "Und er soll das junge Rind* schlachten vor dem HERRN. Und die Söhne Aarons, die Priester, sollen das Blut herzubringen und das Blut ringsherum an den Altar sprengen*, der am Eingang des Zeltes der Begegnung <steht>*.", footnotes: ["w. den Sohn des Rindes", "℘ Kap. 3,2.8; Hes 43,18; Hebr 9,22", "℘ 2Mo 40,6"] },
      { number: 6, text: "Und er soll dem Brandopfer die Haut abziehen und es in seine Stücke zerlegen." },
      { number: 7, text: "Und die Söhne Aarons, des Priesters*, sollen Feuer auf den Altar legen und Holz auf dem Feuer zurichten.", footnotes: ["Einige hebr. Handschr., SamPent und alte Üs. lesen wie in den Versen 5.8.11: die Priester"] },
      { number: 8, text: "Und die Söhne Aarons, die Priester, sollen die Stücke, den Kopf und das Fett auf dem Holz zurichten, über dem Feuer, das auf dem Altar ist*.", footnotes: ["℘ 1Kö 18,33"] },
      { number: 9, text: "Und seine Eingeweide und seine Unterschenkel soll er mit Wasser waschen. Und der Priester soll das Ganze auf dem Altar in Rauch aufgehen lassen*: ein Brandopfer <ist es>, ein Feueropfer als wohlgefälliger Geruch* für den HERRN*.", footnotes: ["℘ 1Chr 6,34", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 2,2; 3,5; 6,14.15; 8,21.28; 1Mo 8,21; 4Mo 15,3; 28,8"] },
      { number: 10, text: "Und wenn seine Opfergabe vom Kleinvieh ist, von den Schafen oder von den Ziegen, als Brandopfer, soll er sie darbringen als ein männliches <Tier> ohne Fehler*.", footnotes: ["℘ Kap. 3,1; 4,3; 5,15; 9,2; 14,10; 22,19.20; 23,12.18; 2Mo 12,5; 4Mo 19,2"] },
      { number: 11, text: "Und er soll es* schlachten an der Nordseite des Altars, vor dem HERRN; und die Söhne Aarons, die Priester, sollen sein Blut ringsherum an den Altar sprengen.", footnotes: ["w. sie; d. i. die Opfergabe"] },
      { number: 12, text: "Und er soll es in seine Stücke zerlegen mit seinem Kopf und seinem Fett. Und der Priester soll sie auf dem Holz zurichten, über dem Feuer, das auf dem Altar ist." },
      { number: 13, text: "Und die Eingeweide und die Unterschenkel soll er mit Wasser waschen*; und der Priester soll das Ganze darbringen und auf dem Altar in Rauch aufgehen lassen: ein Brandopfer ist es, ein Feueropfer als wohlgefälliger Geruch* für den HERRN*.", footnotes: ["℘ 2Chr 4,6; Hes 40,38", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 2,2; 3,5; 6,14.15; 8,21.28; 1Mo 8,21; 4Mo 15,3; 28,8"] },
      { number: 14, text: "Und wenn seine Opfergabe für den HERRN ein Brandopfer von den Vögeln ist, dann soll er von den Turteltauben oder von den jungen Tauben* seine Opfergabe darbringen.", footnotes: ["℘ Kap. 5,7; 12,8"] },
      { number: 15, text: "Und der Priester bringe sie zum Altar und kneife* ihr den Kopf ab und lasse sie auf dem Altar in Rauch aufgehen, und ihr Blut soll an die Wand des Altars ausgedrückt werden.", footnotes: ["d. h. mit dem Fingernagel, ohne den Kopf ganz abzureißen"] },
      { number: 16, text: "Und er trenne ihren Kropf mit seinem Inhalt* ab und werfe ihn neben den Altar nach Osten, an den Ort der Fettasche*.", footnotes: ["o. Unrat. — SamPent und die syr. Üs. lesen: mit ihren Flügeln", "d. i. die Asche, die sich auf dem Altar aus verbranntem Holz und den Fettstücken bildet; vgl. 1Kö 13,3.5; Jer 31,40\n℘ Kap. 6,3"] },
      { number: 17, text: "Und er soll sie an den Flügeln einreißen, er soll sie nicht zertrennen*. Und der Priester soll sie auf dem Altar in Rauch aufgehen lassen, auf dem Holz, das über dem Feuer ist: ein Brandopfer ist es, ein Feueropfer als wohlgefälliger Geruch* für den HERRN.*", footnotes: ["℘ 1Mo 15,10", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 2,2; 3,5; 6,14.15; 8,21.28; 1Mo 8,21; 4Mo 15,3; 28,8"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und wenn jemand* die Opfergabe eines Speisopfers* dem HERRN darbringen will, soll seine Opfergabe Weizengrieß sein; und er soll Öl darauf gießen und Weihrauch darauf legen.", heading: "Speisopfer", footnotes: ["o. eine Seele, o. Person", "Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.\n℘ Kap. 6,7; 4Mo 7,13; 8,8"] },
      { number: 2, text: "Und er soll es zu den Söhnen Aarons, den Priestern, bringen. Er* nehme davon seine Hand voll, von seinem Weizengrieß und von seinem Öl samt all seinem Weihrauch, und der Priester lasse die Askara* davon auf dem Altar* in Rauch aufgehen: ein Feueropfer ist es als wohlgefälliger Geruch* für den HERRN*.", footnotes: ["d. h. der Darbringende", "d. i. der zu verbrennende Teil des Speisopfers\n℘ Kap. 5,12; 24,7", "℘ 4Mo 5,26", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 1,9; Phil 4,18"] },
      { number: 3, text: "Aber das Übrige vom Speisopfer* soll für Aaron und für seine Söhne sein*: ein Hochheiliges* von den Feueropfern des HERRN.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "℘ Kap. 5,13; 6,9; 7,7.9; 10,12-15; 14,13; 4Mo 18,9; 1Sam 2,28; Hes 44,29; 46,20", "℘ Kap. 21,22"] },
      { number: 4, text: "Und wenn du als Opfergabe eines Speisopfers* ein Ofengebäck darbringen willst, soll es Weizengrieß sein, ungesäuerte Kuchen, mit Öl gemengt*, und ungesäuerte Fladen, mit Öl gesalbt*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "o. angefeuchtet; vgl. 2Mo 29,2", "℘ 2Mo 29,2"] },
      { number: 5, text: "Und wenn deine Opfergabe ein Speisopfer* in der Pfanne ist, soll es Weizengrieß sein, mit Öl gemengt*, ungesäuert*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "o. angefeuchtet; vgl. 2Mo 29,2", "℘ Kap. 7,12"] },
      { number: 6, text: "Du sollst es in Stücke zerbrechen und Öl darauf gießen: ein Speisopfer* ist es.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«."] },
      { number: 7, text: "Und wenn deine Opfergabe ein Speisopfer* im Topf ist, soll es von Weizengrieß mit Öl gemacht werden*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "℘ 1Chr 23,29"] },
      { number: 8, text: "Und du sollst das Speisopfer*, das von diesen Dingen gemacht wird, dem HERRN bringen. Man soll es dem Priester überreichen, und er soll es an den Altar tragen.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«."] },
      { number: 9, text: "Und der Priester hebe vom Speisopfer* dessen Askara* ab und lasse es auf dem Altar* in Rauch aufgehen: ein Feueropfer <ist es> als wohlgefälliger Geruch* für den HERRN*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "d. i. der zu verbrennende Teil des Speisopfers", "℘ Kap. 1,9; Phil 4,18", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 1,9; Phil 4,18"] },
      { number: 10, text: "Das übrige vom Speisopfer* aber soll für Aaron und für seine Söhne sein*: ein Hochheiliges* von den Feueropfern des HERRN.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "℘ Kap. 21,22", "℘ Kap. 21,22"] },
      { number: 11, text: "Alles Speisopfer*, das ihr dem HERRN darbringt, darf nicht aus Gesäuertem gemacht werden*; denn von allem Sauerteig und allem Honig sollt ihr für den HERRN nichts als Feueropfer in Rauch aufgehen lassen.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "℘ Kap. 6,10"] },
      { number: 12, text: "Was die Opfergabe der Erstlinge betrifft, sollt ihr sie dem HERRN darbringen*; aber auf den Altar sollen sie nicht kommen als wohlgefälliger Geruch*.", footnotes: ["℘ Kap. 23,10; 4Mo 15,20.21; 18,12.13", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 13, text: "Alle Opfergaben deines Speisopfers* sollst du mit Salz salzen und sollst das Salz des Bundes deines Gottes auf deinem Speisopfer nicht fehlen lassen; bei allen deinen Opfergaben sollst du Salz darbringen*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "℘ 2Mo 30,35; Hes 43,24; Mk 9,49"] },
      { number: 14, text: "Und wenn du dem HERRN ein Speisopfer* von den ersten Früchten darbringen willst, sollst du Ähren, am Feuer geröstet, Graupen* von Jungkorn, darbringen als Speisopfer von deinen ersten Früchten*.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«.", "o. zerstoßene Weizenkörner", "℘ 5Mo 26,2.3"] },
      { number: 15, text: "Und du sollst Öl darauf tun und Weihrauch darauf legen: ein Speisopfer* ist es.", footnotes: ["Die Grundbedeutung des hebr. Wortes ist »Geschenk, Gabe«."] },
      { number: 16, text: "Und der Priester soll die Askara* davon in Rauch aufgehen lassen, von seinen Graupen und von seinem Öl, mit all seinem Weihrauch: ein Feueropfer <ist es> für den HERRN*.", footnotes: ["d. i. der zu verbrennende Teil des Speisopfers", "℘ Kap. 1,9; Phil 4,18"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und wenn seine Opfergabe ein Heilsopfer* ist: Wenn er sie von den Rindern darbringt, es sei ein männliches oder ein weibliches <Tier>, soll er sie ohne Fehler* vor dem HERRN darbringen.", heading: "Heilsopfer", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ Kap. 7,11.29; 22,21", "℘ Kap. 1,3.10"] },
      { number: 2, text: "Und er soll seine Hand auf den Kopf seines Opfers legen* und es am Eingang des Zeltes der Begegnung schlachten*; und die Söhne Aarons, die Priester, sollen das Blut ringsherum an den Altar sprengen*.", footnotes: ["w. seiner Opfergabe stützen o. stemmen\n℘ Kap. 1,4", "℘ Kap. 17,3.4", "℘ Kap. 1,5"] },
      { number: 3, text: "Und von dem Heilsopfer* soll er dem HERRN ein Feueropfer darbringen*: das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist*,", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 7,5", "℘ V. 16.17; Kap. 4,8-10; 9,10; 16,25; 2Mo 29,13"] },
      { number: 4, text: "die beiden Nieren und das Fett, das an ihnen <und> das an den Lenden ist, und den Lappen über der Leber: bei den Nieren soll er es abtrennen." },
      { number: 5, text: "Und die Söhne Aarons sollen es auf dem Altar in Rauch aufgehen lassen*, auf* dem Brandopfer, das auf dem Holz über dem Feuer ist: ein Feueropfer <ist es> als wohlgefälliger Geruch* für den HERRN*.", footnotes: ["℘ 1Sam 2,15.16", "℘ Kap. 1,9; 4Mo 18,17", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 1,9; Phil 4,18"] },
      { number: 6, text: "Und wenn seine Opfergabe vom Kleinvieh ist, für den HERRN als Heilsopfer*, ein männliches oder ein weibliches <Tier>, soll er sie ohne Fehler darbringen.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 7, text: "Wenn er ein Schaf darbringt als seine Opfergabe, dann soll er es vor den HERRN herbeibringen;" },
      { number: 8, text: "und er soll seine Hand auf den Kopf seines Opfers* legen* und es vor dem Zelt der Begegnung schlachten; und die Söhne Aarons sollen sein Blut ringsherum an den Altar sprengen.", footnotes: ["w. seiner Opfergabe stützen o. stemmen", "℘ Kap. 1,4"] },
      { number: 9, text: "Und vom Heilsopfer* soll er sein Fett als Feueropfer dem HERRN darbringen: den ganzen Fettschwanz — dicht beim Schwanzwirbel soll er ihn abtrennen — und das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist,", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 10, text: "die beiden Nieren und das Fett, das an ihnen <und> das an den Lenden ist, und den Lappen über der Leber: bei den Nieren soll er es abtrennen." },
      { number: 11, text: "Und der Priester soll es auf dem Altar in Rauch aufgehen lassen: eine Speise* des Feueropfers für den HERRN <ist es>*. —", footnotes: ["w. ein Brot", "℘ 4Mo 28,2"] },
      { number: 12, text: "Und wenn seine Opfergabe eine Ziege ist, dann soll er sie vor den HERRN herbeibringen;" },
      { number: 13, text: "und er soll seine Hand auf ihren Kopf legen* und sie vor dem Zelt der Begegnung schlachten; und die Söhne Aarons sollen ihr Blut ringsherum an den Altar sprengen.", footnotes: ["℘ Kap. 1,4"] },
      { number: 14, text: "Und er soll davon seine Opfergabe als Feueropfer dem HERRN darbringen: das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist," },
      { number: 15, text: "und die beiden Nieren und das Fett, das an ihnen <und> das an den Lenden ist, und den Lappen über der Leber: bei den Nieren soll er es abtrennen*.", footnotes: ["℘ Kap. 4,31"] },
      { number: 16, text: "Und der Priester soll sie auf dem Altar in Rauch aufgehen lassen: eine Speise* des Feueropfers <ist es> als wohlgefälliger Geruch*. Alles Fett gehört dem HERRN*.", footnotes: ["w. ein Brot", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ 1Mo 4,4; Hes 44,15"] },
      { number: 17, text: "Eine ewige Ordnung bei euren Generationen in allen euren Wohnsitzen*: Keinerlei Fett* und keinerlei Blut dürft ihr essen*!", footnotes: ["℘ Kap. 6,15; 7,36; 10,9; 16,34; 17,7; 23,14; 24,9; 2Mo 27,21", "℘ Kap. 7,23; 2Chr 29,35", "℘ Kap. 7,26; 17,12-14; 19,26; 1Mo 9,4; 5Mo 12,16.23"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Sündopfer für unwissend begangene Sünden" },
      { number: 2, text: "Rede zu den Söhnen Israel und sage: Wenn jemand* aus Versehen sündigt gegen <irgendetwas>, was der HERR zu tun verboten hat*, und irgendeines von ihnen tut* —", footnotes: ["w. eine Seele", "w. gegen <irgendeines> von allen Geboten des HERRN, die nicht getan werden dürfen", "℘ Kap. 5,17; 4Mo 15,22-29; Ps 19,13; 1Tim 1,13"] },
      { number: 3, text: "wenn der gesalbte Priester* sündigt zur Schuld des Volkes*, dann soll er für seine Sünde, die er begangen hat, dem HERRN einen Jungstier ohne Fehler* als Sündopfer darbringen*!", footnotes: ["℘ Kap. 21,10.12", "d. h. so dass Schuld auf dem Volk liegt", "℘ Kap. 1,3.10", "℘ Kap. 6,18; 9,2; 16,3.33; Hes 40,39; 44,27; Hebr 7,27"] },
      { number: 4, text: "Und er soll den Stier an den Eingang des Zeltes der Begegnung vor den HERRN bringen und seine Hand auf den Kopf des Stieres legen* und den Stier vor dem HERRN schlachten*.", footnotes: ["℘ Kap. 1,4; 2Chr 29,23", "℘ 2Mo 29,10.11"] },
      { number: 5, text: "Und der gesalbte Priester nehme von dem Blut des Stieres und bringe es in das Zelt der Begegnung*;", footnotes: ["℘ Kap. 6,23"] },
      { number: 6, text: "und der Priester tauche seinen Finger in das Blut und sprenge von dem Blut siebenmal vor den HERRN gegen den Vorhang des Heiligtums hin*.", footnotes: ["℘ Kap. 8,11; 14,7; 16,14.15; 4Mo 19,4"] },
      { number: 7, text: "Und der Priester tue <etwas> von dem Blut an die Hörner des Altars des wohlriechenden Räucherwerks, der im Zelt der Begegnung vor dem HERRN <steht>*. Alles Blut des Stieres aber soll er an den Fuß des Brandopferaltars gießen*, der am Eingang des Zeltes der Begegnung <steht>*.", footnotes: ["℘ 2Mo 30,10", "℘ Kap. 5,9; 8,15; 9,9; 2Mo 29,12", "℘ Kap. 1,5"] },
      { number: 8, text: "Und alles Fett vom Stier des Sündopfers soll er von ihm abheben: das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist," },
      { number: 9, text: "und die beiden Nieren und das Fett, das an ihnen <und> das an den Lenden ist, und den Lappen über der Leber: bei den Nieren soll er es abtrennen," },
      { number: 10, text: "ebenso wie es vom Stier des Heilsopfers* abgehoben wird; und der Priester soll es auf dem Brandopferaltar in Rauch aufgehen lassen.", footnotes: ["o. Friedensopfers; o. Abschlussopfers; o. Gemeinschaftsopfers\n℘ Kap. 3,3"] },
      { number: 11, text: "Aber die Haut des Stieres und all sein Fleisch samt seinem Kopf und seinen Unterschenkeln und seinen Eingeweiden und seinem Mageninhalt*:", footnotes: ["o. Darminhalt"] },
      { number: 12, text: "Den ganzen Stier soll er* hinausbringen, nach draußen vor das Lager, an einen reinen Ort, an den Schutthaufen der Fettasche* und soll ihn auf Holzscheiten mit Feuer verbrennen*. Auf dem Schutthaufen der Fettasche soll er verbrannt werden.", footnotes: ["o. man", "d. i. die Asche, die sich auf dem Altar aus verbranntem Holz und den Fettstücken bildet\n℘ Kap. 6,4", "℘ Kap. 6,23; 8,17; 16,27; 2Mo 29,14; Hebr 13,11.12"] },
      { number: 13, text: "Und wenn die ganze Gemeinde Israel aus Versehen sündigt, und die Sache ist verborgen vor den Augen der Versammlung*, und sie tun irgendetwas von alledem, was der HERR zu tun verboten hat*, und werden schuldig*;", footnotes: ["℘ 4Mo 15,22-24", "w. eines von allen Geboten des HERRN, <seines Gottes,> die nicht getan werden dürfen", "℘ Kap. 5,17; 4Mo 15,22-29; Ps 19,13; 1Tim 1,13"] },
      { number: 14, text: "wird dann die Sünde erkannt, mit der sie sich dagegen versündigt haben, dann soll die Versammlung einen Jungstier als Sündopfer darbringen, und sie sollen ihn vor das Zelt der Begegnung bringen." },
      { number: 15, text: "Und die Ältesten der Gemeinde sollen vor dem HERRN ihre Hände auf den Kopf des Stieres legen, und man soll den Stier vor dem HERRN schlachten." },
      { number: 16, text: "Und der gesalbte Priester bringe <etwas> von dem Blut des Stieres in das Zelt der Begegnung," },
      { number: 17, text: "und der Priester tauche seinen Finger in das Blut und sprenge vor dem HERRN siebenmal gegen den Vorhang hin*.", footnotes: ["℘ Kap. 8,11; 14,7; 16,14.15; 4Mo 19,4"] },
      { number: 18, text: "Und von dem Blut tue er <etwas> an die Hörner des Altars*, der vor dem HERRN, also im Zelt* der Begegnung, <steht>*. Alles Blut soll er an den Fuß des Brandopferaltars gießen*, der am Eingang des Zeltes der Begegnung <steht>.", footnotes: ["℘ 2Chr 29,22", "w. der im Zelt", "℘ Kap. 5,9; 8,15; 9,9; 2Mo 29,12", "℘ Kap. 5,9; 8,15; 9,9; 2Mo 29,12"] },
      { number: 19, text: "All sein Fett aber soll er von ihm abheben und auf dem Altar in Rauch aufgehen lassen." },
      { number: 20, text: "Und er soll mit dem Stier tun, wie er mit dem Stier des Sündopfers getan hat; ebenso soll er damit tun. Und so erwirke der Priester Sühnung für sie, und es wird ihnen vergeben werden*.", footnotes: ["℘ Kap. 5,10; 14,18; 19,22; 4Mo 15,25.26.28; 1Jo 1,9"] },
      { number: 21, text: "Und er* soll den Stier hinausbringen, nach draußen vor das Lager, und ihn verbrennen*, ebenso wie er* den ersten Stier verbrannt hat: ein Sündopfer der Versammlung ist es*.", footnotes: ["o. man", "℘ Kap. 6,23; 8,17; 16,27; 2Mo 29,14; Hebr 13,11.12", "o. man", "℘ Hes 45,22"] },
      { number: 22, text: "Wenn ein Fürst sündigt und tut aus Versehen irgendetwas von alledem, was der HERR, sein Gott, zu tun verboten hat*, und wird schuldig*,", footnotes: ["w. eines von allen Geboten des HERRN, <seines Gottes,> die nicht getan werden dürfen", "℘ Kap. 5,17; 4Mo 15,22-29; Ps 19,13; 1Tim 1,13"] },
      { number: 23, text: "und seine Sünde, mit der er gesündigt hat, wird ihm zu Bewusstsein gebracht*, dann soll er seine Opfergabe bringen, einen Ziegenbock*, ein Männchen ohne Fehler*.", footnotes: ["LXX: ist ihm bekannt geworden\n℘ Ps 90,8", "w. Haarigen der Ziegen", "℘ Kap. 1,3.10"] },
      { number: 24, text: "Und er soll seine Hand auf den Kopf des Ziegenbockes* legen* und ihn schlachten an dem Ort, wo man das Brandopfer vor dem HERRN schlachtet*: ein Sündopfer ist es.", footnotes: ["w. Haarigen", "℘ Kap. 1,4; 2Chr 29,23", "℘ Kap. 6,18; 7,2"] },
      { number: 25, text: "Und der Priester nehme mit seinen Fingern <etwas> von dem Blut des Sündopfers und tue es an die Hörner des Brandopferaltars; und sein Blut soll er an den Fuß des Brandopferaltars gießen*.", footnotes: ["℘ Kap. 5,9; 8,15; 9,9; 2Mo 29,12"] },
      { number: 26, text: "All sein Fett aber soll er auf dem Altar in Rauch aufgehen lassen, wie das Fett des Heilsopfers*. Und so erwirke der Priester Sühnung für ihn wegen seiner Sünde*, und es wird ihm vergeben werden*.", footnotes: ["o. Friedensopfers; o. Abschlussopfers; o. Gemeinschaftsopfers", "℘ Kap. 17,11; Hes 43,22", "℘ Kap. 5,10; 14,18; 19,22; 4Mo 15,25.26.28; 1Jo 1,9"] },
      { number: 27, text: "Und wenn jemand* vom Volk des Landes aus Versehen sündigt*, indem er eines von dem tut, was der HERR zu tun verboten hat*, und schuldig wird*,", footnotes: ["w. eine Seele", "℘ 4Mo 15,27; Hes 45,17.20", "w. eines von allen Geboten des HERRN, <seines Gottes,> die nicht getan werden dürfen", "℘ Kap. 5,17; 4Mo 15,22-29; Ps 19,13; 1Tim 1,13"] },
      { number: 28, text: "und seine Sünde, die er begangen hat, wird ihm zu Bewusstsein gebracht*, dann soll er seine Opfergabe bringen, eine weibliche Ziege* ohne Fehler, für seine Sünde, die er begangen hat.", footnotes: ["℘ Ps 90,8", "w. Haarige der Ziegen"] },
      { number: 29, text: "Und er soll seine Hand auf den Kopf des Sündopfers legen* und das Sündopfer am Ort des Brandopfers schlachten.", footnotes: ["℘ Kap. 1,4; 2Chr 29,23"] },
      { number: 30, text: "Und der Priester nehme mit seinem Finger <etwas> von seinem Blut und tue es an die Hörner des Brandopferaltars. All sein Blut aber soll er an den Fuß des Altars gießen*.", footnotes: ["℘ Kap. 5,9; 8,15; 9,9; 2Mo 29,12"] },
      { number: 31, text: "Und all sein Fett soll er abtrennen, ebenso wie das Fett vom Heilsopfer* abgetrennt wird*; und der Priester soll es auf dem Altar in Rauch aufgehen lassen als wohlgefälligen Geruch* für den HERRN. So erwirke der Priester Sühnung für ihn, und es wird ihm vergeben werden*. —", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 3,14.15", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 5,10; 14,18; 19,22; 4Mo 15,25.26.28; 1Jo 1,9"] },
      { number: 32, text: "Und wenn er ein Schaf bringt als seine Opfergabe zum Sündopfer, dann bringe er ein weibliches <Tier> ohne Fehler*.", footnotes: ["℘ Kap. 1,3.10"] },
      { number: 33, text: "Und er soll seine Hand auf den Kopf des Sündopfers legen* und es als Sündopfer schlachten an dem Ort, wo man das Brandopfer schlachtet*.", footnotes: ["℘ Kap. 6,18; 7,2", "℘ Kap. 6,18; 7,2"] },
      { number: 34, text: "Und der Priester nehme mit seinem Finger <etwas> vom Blut des Sündopfers und tue es an die Hörner des Brandopferaltars. All sein Blut aber soll er an den Fuß des Altars gießen." },
      { number: 35, text: "Und all sein Fett soll er abtrennen, ebenso wie das Fett des Schafes vom Heilsopfer* abgetrennt wird; und der Priester soll es auf dem Altar in Rauch aufgehen lassen, auf* den Feueropfern des HERRN. So erwirke der Priester Sühnung für ihn wegen seiner Sünde*, die er begangen hat, und es wird ihm vergeben werden*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "o. bei; o. mit", "℘ Kap. 5,10; 14,18; 19,22; 4Mo 15,25.26.28; 1Jo 1,9", "℘ Kap. 5,10; 14,18; 19,22; 4Mo 15,25.26.28; 1Jo 1,9"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und wenn jemand* sündigt, dass er die Stimme der Verfluchung hört, und er war Zeuge, sei es, dass er es gesehen oder gekannt hat — wenn er es nicht meldet*, dann soll er seine Schuld tragen*;", heading: "Gesetze vom Sündopfer", footnotes: ["w. eine Seele", "℘ Spr 29,24", "o. wenn er es nicht anzeigt und so Schuld auf sich lädt\n℘ V. 17"] },
      { number: 2, text: "oder wenn jemand irgendetwas Unreines anrührt, sei es das Aas eines unreinen wilden Tieres oder das Aas eines unreinen Viehs oder das Aas eines unreinen kriechenden Tieres* —, ist es ihm auch verborgen, dann ist er <doch> unrein* und schuldig*.", footnotes: ["w. unreinen Gewimmels; wie 1Mo 1,20", "℘ Kap. 11,24.31.39", "℘ V. 17"] },
      { number: 3, text: "Oder* wenn er die Unreinheit eines Menschen anrührt, was seine Unreinheit auch sei, durch die er unrein wird*, und es ist ihm verborgen — erkennt er es, dann ist er schuldig.", footnotes: ["o. und es ist ihm verborgen, dass er unrein und schuldig ist, 3 oder", "℘ Kap. 7,21; 12,2; 13,3; 15,2"] },
      { number: 4, text: "Oder wenn jemand* schwört, indem er unbesonnen mit den Lippen redet, Böses oder Gutes zu tun, nach allem, was ein Mensch mit einem Schwur unbesonnen reden mag*, und es ist ihm verborgen — erkennt er es, dann ist er schuldig in einem von diesen.", footnotes: ["w. eine Seele", "℘ 1Sam 14,24.39.44; Pred 5,2-6"] },
      { number: 5, text: "Und es soll geschehen, wenn er in einem von diesen <Dingen> schuldig wird, dann bekenne er, worin er gesündigt hat*;", footnotes: ["℘ Kap. 16,21; 26,40; 4Mo 5,7; Ps 32,5"] },
      { number: 6, text: "und er bringe dem HERRN sein Schuldopfer für seine Sünde, die er begangen hat: ein weibliches <Tier> vom Kleinvieh, ein Schaf oder eine Ziege*, zum Sündopfer. So soll der Priester wegen seiner Sünde Sühnung für ihn erwirken*.", footnotes: ["w. Haarige der Ziegen", "℘ Kap. 4,31.35"] },
      { number: 7, text: "Und wenn seine Hand das <zum Kauf> eines Schafes* Ausreichende nicht aufbringen kann*, so bringe er für das, worin er gesündigt hat, dem HERRN sein Schuldopfer*: zwei Turteltauben oder zwei junge Tauben*; eine zum Sündopfer und eine zum Brandopfer*.", footnotes: ["o. einer Ziege; o. eines Lammes", "w. nicht erreicht, o. nicht findet\n℘ Kap. 12,8; 14,21; 27,8", "o. so bringe er, der gesündigt hat, dem HERRN als ein Schuldopfer", "℘ Kap. 1,14", "℘ Kap. 12,8; 14,22"] },
      { number: 8, text: "Und er soll sie zum Priester bringen; und dieser bringe die zum Sündopfer zuerst dar und kneife ihr den Kopf dicht beim Genick ab*. Er soll ihn aber nicht <völlig> abtrennen.", footnotes: ["d. i. mit dem Fingernagel"] },
      { number: 9, text: "Und er sprenge <etwas> von dem Blut des Sündopfers an die Wand des Altars*, das Übrige von dem Blut aber soll an den Fuß des Altars ausgedrückt werden: ein Sündopfer ist es.", footnotes: ["℘ Kap. 4,7"] },
      { number: 10, text: "Und die andere soll er als Brandopfer opfern, nach der Vorschrift*. So erwirke der Priester Sühnung für ihn wegen seiner Sünde, die er begangen hat, und es wird ihm vergeben werden*.", footnotes: ["℘ Kap. 1,14-17", "℘ V. 16.18.26; Kap. 4,20"] },
      { number: 11, text: "Wenn aber seine Hand zwei Turteltauben oder zwei junge Tauben nicht aufbringen kann*, dann bringe er, der gesündigt hat, als seine Opfergabe ein zehntel Efa Weizengrieß* zum Sündopfer. Er soll kein Öl darauf tun und keinen Weihrauch darauf legen, denn ein Sündopfer ist es.", footnotes: ["℘ Kap. 12,8; 14,21; 27,8", "℘ Kap. 2,1"] },
      { number: 12, text: "Und er soll es zum Priester bringen; und der Priester nehme davon seine Hand voll, die Askara* davon, und lasse es auf dem Altar in Rauch aufgehen, auf den Feueropfern des HERRN*: ein Sündopfer ist es.", footnotes: ["d. i. der zu verbrennende Teil des Speisopfers", "℘ Kap. 2,2"] },
      { number: 13, text: "So erwirke der Priester Sühnung für ihn wegen seiner Sünde, die er begangen hat in einem von diesen <Dingen>, und es wird ihm vergeben werden*. Das Sündopfer* aber soll dem Priester gehören wie das Speisopfer*.", footnotes: ["℘ V. 16.18.26; Kap. 4,20", "w. Es", "℘ Kap. 2,10"] },
      { number: 14, text: "Und der HERR redete zu Mose:", heading: "Schuldopfer" },
      { number: 15, text: "Wenn jemand* Untreue begeht und aus Versehen an den heiligen Dingen des HERRN sündigt*, dann soll er dem HERRN sein Schuldopfer bringen*: einen Widder ohne Fehler* vom Kleinvieh, nach deiner Schätzung an Schekeln Silber, nach dem Schekel des Heiligtums*, zum Schuldopfer*.", footnotes: ["w. eine Seele", "℘ Kap. 22,14", "℘ Hes 40,39", "℘ Kap. 1,3.10", "℘ Kap. 27,25", "℘ V. 16.18.26; Kap. 4,20"] },
      { number: 16, text: "Und worin er an dem Heiligen gesündigt hat, soll er erstatten* und ein Fünftel davon noch hinzufügen* und es dem Priester geben. Und der Priester soll Sühnung für ihn erwirken mit dem Widder des Schuldopfers, und es wird ihm vergeben werden*.", footnotes: ["w. unversehrt o. vollständig machen\n℘ 1Sam 6,3", "℘ Kap. 22,14; 27,13.15.27; 4Mo 5,7", "℘ Kap. 4,20"] },
      { number: 17, text: "Und wenn jemand* sündigt und irgendetwas von all dem tut, was der HERR zu tun verboten hat* — hat er es auch nicht erkannt*, dann ist er <doch> schuldig und soll seine Schuld tragen*.", footnotes: ["w. eine Seele", "w. eines von allen Geboten des HERRN tut, die nicht getan werden dürfen", "℘ Kap. 4,2.13", "℘ V. 1.2"] },
      { number: 18, text: "Er soll* nach deiner Schätzung einen Widder ohne Fehler*, vom Kleinvieh, zum Priester bringen für das Schuldopfer. Und der Priester soll für ihn Sühnung erwirken wegen seines Versehens, das er begangen hat, ohne es zu erkennen; und es wird ihm vergeben werden*.", footnotes: ["o. und hatte er es nicht erkannt und ist schuldig geworden und hat Schuld auf sich geladen, 18 dann soll er", "℘ Kap. 4,20", "℘ Kap. 4,20"] },
      { number: 19, text: "Ein Schuldopfer ist es*; er ist auf jeden Fall am HERRN schuldig geworden.", footnotes: ["℘ Hes 40,39"] },
      { number: 20, text: "*Und der HERR redete zu Mose:", footnotes: ["℘ V. 20-24: 2Mo 22,6-14"] },
      { number: 21, text: "Wenn jemand* sündigt und Untreue gegen den HERRN begeht, dass er seinem Nächsten ein anvertrautes Gut ableugnet oder ein Darlehen oder etwas Geraubtes, oder er hat von seinem Nächsten etwas erpresst,", footnotes: ["w. eine Seele"] },
      { number: 22, text: "oder er hat Verlorenes gefunden und leugnet es ab, und er schwört falsch oder irgendetwas von allem, was ein Mensch tun mag, sich darin zu versündigen*:", footnotes: ["℘ Kap. 19,11.13; 4Mo 5,6"] },
      { number: 23, text: "Dann soll es geschehen, wenn er gesündigt hat und schuldig geworden ist, dass er zurückerstatte das Geraubte, das er geraubt, oder das Erpresste, das er erpresst hat, oder das Anvertraute, das ihm anvertraut worden ist, oder das Verlorene, das er gefunden hat," },
      { number: 24, text: "oder <etwas> von all dem, worüber er falsch geschworen hat; und er soll es erstatten* nach seiner <vollen> Summe und ein Fünftel davon noch hinzufügen*. Wem es gehört, dem soll er es geben am Tag seines Schuldopfers.", footnotes: ["w. unversehrt o. vollständig machen\n℘ 4Mo 5,7; 1Sam 12,3; Hes 33,15", "℘ Kap. 22,14; 27,13.15.27; 4Mo 5,7"] },
      { number: 25, text: "Und dem HERRN soll er sein Schuldopfer bringen: einen Widder ohne Fehler* vom Kleinvieh, nach deiner Schätzung, als Schuldopfer zum Priester*.", footnotes: ["℘ Kap. 1,3.10", "℘ Esr 10,19"] },
      { number: 26, text: "Und der Priester soll Sühnung für ihn erwirken vor dem HERRN, und es wird ihm vergeben werden wegen irgendetwas von allem, was er getan hat, darin schuldig zu werden*.", footnotes: ["℘ Kap. 4,20"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Gesetz vom Brandopfer und Speisopfer" },
      { number: 2, text: "Befiehl Aaron und seinen Söhnen und sage: Dies ist das Gesetz des Brandopfers. Dieses, das Brandopfer, soll auf seiner Feuerstelle sein, auf dem Altar, die ganze Nacht bis zum Morgen; und das Feuer des Altars soll auf ihm in Brand gehalten werden*.", footnotes: ["℘ Kap. 1,3.8"] },
      { number: 3, text: "Und der Priester soll sein leinenes Gewand anziehen und soll seine leinenen Beinkleider anziehen über sein Fleisch*; und er soll die Fettasche* abheben, zu der das Feuer das Brandopfer auf dem Altar verzehrt hat, und soll sie neben den Altar schütten*.", footnotes: ["℘ Kap. 16,4; 2Mo 28,42", "d. i. Asche, die sich auf dem Altar aus verbranntem Holz und den Fettstücken bildet", "℘ Kap. 1,16"] },
      { number: 4, text: "Und er soll seine Kleider ausziehen und andere Kleider anlegen* und die Fettasche* hinaustragen nach draußen vor das Lager an einen reinen Ort*.", footnotes: ["℘ Hes 44,19", "d. i. Asche, die sich auf dem Altar aus verbranntem Holz und den Fettstücken bildet", "℘ Kap. 4,12"] },
      { number: 5, text: "Und das Feuer auf dem Altar soll auf ihm in Brand gehalten werden, es soll nicht erlöschen; und der Priester soll Holz auf ihm anzünden, Morgen für Morgen*, und das Brandopfer auf ihm zurichten und die Fettstücke der Heilsopfer* auf ihm in Rauch aufgehen lassen.", footnotes: ["℘ 2Mo 30,7", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 6, text: "Ein beständiges Feuer soll auf dem Altar in Brand gehalten werden, es soll nicht erlöschen*.", footnotes: ["℘ Neh 10,35; Hes 40,46"] },
      { number: 7, text: "Und dies ist das Gesetz des Speisopfers*: Die Söhne Aarons sollen* es vor dem HERRN darbringen, am Altar*.", footnotes: ["℘ Kap. 2,1", "so mit SamPent; Mas. T.: <Einer der> Söhne Aarons soll", "o. auf der Oberseite des Altars"] },
      { number: 8, text: "Und er soll davon seine Hand voll nehmen*, vom Weizengrieß des Speisopfers und von seinem Öl, und allen Weihrauch, der auf dem Speisopfer ist, und es auf dem Altar in Rauch aufgehen lassen: <Es ist> ein wohlgefälliger Geruch*, seine Askara* für den HERRN.", footnotes: ["w. abheben", "o. Geruch der Befriedigung o. Beschwichtigung", "d. i. der zu verbrennende Teil des Speisopfers"] },
      { number: 9, text: "Das Übrige davon aber sollen Aaron und seine Söhne essen. Ungesäuert soll es gegessen werden an heiliger Stätte. Im Vorhof des Zeltes der Begegnung sollen sie es essen*.", footnotes: ["℘ V. 19; Kap. 2,3.10; 1Kor 9,13"] },
      { number: 10, text: "Es soll nicht gesäuert gebacken werden*; als ihren Anteil habe ich es ihnen gegeben von meinen Feueropfern: hochheilig ist es*, wie das Sündopfer und wie das Schuldopfer.", footnotes: ["℘ Kap. 2,11", "℘ V. 18.22; Kap. 21,22"] },
      { number: 11, text: "Alles Männliche unter den Söhnen Aarons soll es essen*: Eine ewige Ordnung* von den Feueropfern des HERRN für eure Generationen <ist es>. Alles, was sie anrührt, wird geheiligt sein*.", footnotes: ["℘ V. 22; Kap. 7,6; 24,9", "o. Eine ewige Gebühr; o. Ein ewiger Anspruch", "d. h. es gehört dem Heiligtum\n℘ V. 20; 2Mo 29,37"] },
      { number: 12, text: "Und der HERR redete zu Mose:", heading: "Opfer zur Priesterweihe" },
      { number: 13, text: "Dies ist die Opfergabe Aarons und seiner Söhne, die sie dem HERRN darbringen sollen an dem Tag, an dem er gesalbt wird*: ein zehntel Efa Weizengrieß* als regelmäßiges Speisopfer, die Hälfte davon am Morgen und die Hälfte davon am Abend.", footnotes: ["℘ 2Mo 29,1.2.7", "℘ 2Mo 29,40"] },
      { number: 14, text: "Es soll in der Pfanne mit Öl bereitet werden, <mit Öl> eingerührt, sollst du es bringen. Gebäck als Speisopferbrocken sollst du darbringen* als einen wohlgefälligen Geruch* für den HERRN*.", footnotes: ["Das hebr. Wort für »Gebäck« ist nicht sicher übersetzbar. Darum üs. einige nach der syr. Üs.: Zerbröckeln sollst du es, als Speisopferbrocken sollst du es darbringen", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Kap. 1,9; 1Chr 9,31"] },
      { number: 15, text: "Und der Priester, der unter seinen Söhnen an seiner Statt gesalbt wird, soll es opfern; eine ewige Ordnung*: Es soll für den HERRN ganz in Rauch aufgehen.", footnotes: ["o. Eine ewige Gebühr; o. Ein ewiger Anspruch\n℘ 2Mo 27,21"] },
      { number: 16, text: "Und jedes Speisopfer des Priesters soll ein Ganzopfer* sein; es darf nicht gegessen werden.", footnotes: ["d. i. ein Opfer, das ganz verbrannt wurde und nicht mehr zum Verzehr diente"] },
      { number: 17, text: "Und der HERR redete zu Mose:", heading: "Gesetz des Sündopfers" },
      { number: 18, text: "Rede zu Aaron und zu seinen Söhnen: Dies ist das Gesetz des Sündopfers*. An dem Ort, wo das Brandopfer geschlachtet wird, soll das Sündopfer vor dem HERRN geschlachtet werden: hochheilig ist es*.", footnotes: ["℘ Kap. 4,3.21", "℘ V. 10; Kap. 4,24.33"] },
      { number: 19, text: "Der Priester, der es als Sündopfer opfert, soll es essen. An heiliger Stätte soll es gegessen werden*, im Vorhof des Zeltes der Begegnung*.", footnotes: ["℘ V. 9", "℘ Kap. 10,18; Hes 42,13"] },
      { number: 20, text: "Alles, was sein Fleisch anrührt, wird geheiligt sein*. Wenn von seinem Blut <etwas> auf ein Kleid spritzt — das, worauf es spritzt, sollst du waschen an heiliger Stätte.", footnotes: ["d. h. es gehört dem Heiligtum\n℘ V. 11"] },
      { number: 21, text: "Das Tongefäß aber, in dem es gekocht wird, soll zerbrochen werden, und wenn es in einem bronzenen Gefäß gekocht wird, dann soll dieses gescheuert und mit Wasser gespült werden*.", footnotes: ["℘ Kap. 11,33; 15,12"] },
      { number: 22, text: "Alles Männliche unter den Priestern soll es essen*: hochheilig ist es*.", footnotes: ["℘ V. 11; Hos 4,8", "℘ V. 10; Kap. 4,24.33"] },
      { number: 23, text: "Aber alles Sündopfer, von dessen Blut <etwas> in das Zelt der Begegnung gebracht wird, um im Heiligtum Sühnung zu erwirken*, soll nicht gegessen werden. Es soll mit Feuer verbrannt werden*.", footnotes: ["℘ Kap. 4,5; 16,27", "℘ Kap. 4,12"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und dies ist das Gesetz des Schuldopfers*; hochheilig ist es*.", heading: "Nähere Bestimmungen über das Schuldopfer", footnotes: ["℘ Kap. 5,6", "℘ Kap. 21,22"] },
      { number: 2, text: "An dem Ort, wo man das Brandopfer schlachtet, soll man das Schuldopfer schlachten*. Der Priester* soll sein Blut ringsherum an den Altar sprengen.", footnotes: ["℘ Kap. 4,24.33; Hes 40,39", "w. Er"] },
      { number: 3, text: "Und all sein Fett davon soll er darbringen, den Fettschwanz und das Fett, das die Eingeweide bedeckt," },
      { number: 4, text: "und die beiden Nieren und das Fett, das an ihnen und das an den Lenden ist, und den Lappen über der Leber: bei den Nieren soll er es abtrennen." },
      { number: 5, text: "Und der Priester soll es auf dem Altar in Rauch aufgehen lassen als ein Feueropfer für den HERRN*: ein Schuldopfer ist es.", footnotes: ["℘ Kap. 3,3"] },
      { number: 6, text: "Alles Männliche unter den Priestern soll es essen*; an heiliger Stätte soll es gegessen werden: hochheilig ist es*.", footnotes: ["℘ Kap. 6,11.22; 4Mo 18,10; 1Kor 10,18", "℘ Kap. 21,22"] },
      { number: 7, text: "Wie das Sündopfer, so das Schuldopfer: ein Gesetz soll für sie sein. Der Priester, der damit Sühnung erwirkt, ihm soll es gehören*. —", footnotes: ["℘ 4Mo 5,8"] },
      { number: 8, text: "Und der Priester, der jemandes Brandopfer darbringt, ihm, dem Priester, soll die Haut des Brandopfers gehören, das er dargebracht hat." },
      { number: 9, text: "Und alles Speisopfer, das im Ofen gebacken, und alles, was im Topf oder in der Pfanne bereitet wird: dem Priester, der es darbringt, ihm soll es gehören*.", footnotes: ["℘ Kap. 2,3.10; 2Kö 12,17"] },
      { number: 10, text: "Und alles Speisopfer, das mit Öl gemengt* oder trocken ist, soll allen Söhnen Aarons gehören, dem einen wie dem anderen.", footnotes: ["o. angefeuchtet"] },
      { number: 11, text: "Und dies ist das Gesetz des Heilsopfers*, das man dem HERRN darbringt:", heading: "Gesetz des Heilsopfers", footnotes: ["o. Friedensopfers; o. Abschlussopfers; o. Gemeinschaftsopfers\n℘ V. 29; Kap. 3,1; 2Chr 29,31; 33,16"] },
      { number: 12, text: "Wenn man es zum Dank* darbringt*, so bringe man zu dem Dankopfer hinzu ungesäuerte Kuchen dar, mit Öl gemengt*, und ungesäuerte Fladen, mit Öl gesalbt, und Weizengrieß, <mit Öl> eingerührt, Kuchen, gemengt mit Öl*.", footnotes: ["anderswo: Lob; eigentlich: Anerkennung", "℘ Ps 107,22; Hebr 13,15", "o. angefeuchtet", "℘ Kap. 2,4.5; 4Mo 6,15"] },
      { number: 13, text: "Außer den Kuchen soll man gesäuertes <Brot> als seine Gabe darbringen zu seinem Dank-Heilsopfer*.", footnotes: ["o. Lob-Friedensopfer\n℘ Am 4,5"] },
      { number: 14, text: "Und man soll <je> eines davon, von der ganzen Gabe, dem HERRN als Hebopfer* darbringen; dem Priester, der das Blut des Heilsopfers sprengt, ihm soll es gehören*.", footnotes: ["d. i. ein Opfer, das durch Hochheben dem HERRN geweiht wird", "℘ 4Mo 18,8.11.19"] },
      { number: 15, text: "Und das Fleisch seines Dank-Heilsopfers soll am Tag seiner Darbringung gegessen werden; er soll nichts davon liegen lassen bis zum Morgen*.", footnotes: ["℘ Kap. 22,29.30; 2Mo 12,10"] },
      { number: 16, text: "Und wenn das Schlachtopfer seiner Opfergabe ein Gelübde oder eine freiwillige Gabe ist*, soll es an dem Tag, an dem er sein Schlachtopfer darbringt, gegessen werden; und am nächsten Tag soll dann gegessen werden, was davon übrig bleibt.", footnotes: ["℘ 4Mo 15,3"] },
      { number: 17, text: "Was aber vom Fleisch des Schlachtopfers am dritten Tag übrig bleibt, soll mit Feuer verbrannt werden." },
      { number: 18, text: "Und wenn vom Fleisch seines Heilsopfers* am dritten Tag noch irgendetwas gegessen wird, dann wird es* nicht <mehr> als wohlgefällig betrachtet werden; wer es dargebracht hat, dem wird es nicht angerechnet werden: Unreines* wird es sein; und die Person*, die davon isst, wird ihre Sündenschuld tragen*.", footnotes: ["o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "d. i. das Opfer", "d. i. kultisch unrein gewordenes Opferfleisch", "o. Seele", "℘ Kap. 19,5-8"] },
      { number: 19, text: "Und das Fleisch, das mit irgendetwas Unreinem in Berührung kommt, soll nicht gegessen werden; mit Feuer soll es verbrannt werden. Und <was> das Fleisch <betrifft>, jeder Reine darf das Fleisch essen;" },
      { number: 20, text: "aber die Person*, die Fleisch von dem Heilsopfer* isst, das dem HERRN gehört, und ihre Unreinheit ist an ihr*, diese Person* soll aus ihren Volksgenossen* ausgerottet werden*.", footnotes: ["o. Seele", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "℘ 1Sam 20,26", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "w. Völkern", "℘ V. 25.27; Kap. 18,29; 19,8; 20,3.17; 22,3; 23,29; 2Mo 30,33.38; Hes 33,25"] },
      { number: 21, text: "Und wenn eine Person* irgendetwas Unreines anrührt*, die Unreinheit eines Menschen oder ein unreines Vieh oder irgendetwas unreines Abscheuliches, und sie isst vom Fleisch des Heilsopfers*, das dem HERRN gehört: diese Person* soll aus ihren Volksgenossen* ausgerottet werden*.", footnotes: ["o. Seele", "℘ Kap. 5,3; 11,24.25", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "w. Völkern", "℘ V. 25.27; Kap. 18,29; 19,8; 20,3.17; 22,3; 23,29; 2Mo 30,33.38; Hes 33,25"] },
      { number: 22, text: "Und der HERR redete zu Mose:", heading: "Verbot des Essens von Fett und Blut" },
      { number: 23, text: "Rede zu den Söhnen Israel: Alles Fett von Stier und Schaf und Ziege dürft ihr nicht essen*.", footnotes: ["℘ 2Mo 22,30"] },
      { number: 24, text: "Und das Fett von Aas und das Fett von Zerrissenem kann verwendet werden zu allerlei Werk; aber ihr dürft es auf keinen Fall essen*.", footnotes: ["℘ 2Mo 22,30"] },
      { number: 25, text: "Denn jeder, der Fett vom Vieh isst, von dem man dem HERRN ein Feueropfer darbringt — die Person*, die es isst, soll aus ihren Volksgenossen* ausgerottet werden*.", footnotes: ["o. Seele", "w. Völkern", "℘ V. 20.21"] },
      { number: 26, text: "Ihr sollt kein Blut essen in allen euren Wohnsitzen, es sei von den Vögeln oder vom Vieh*.", footnotes: ["℘ 2Mo 22,30"] },
      { number: 27, text: "Jede Person*, die irgendwelches Blut isst, diese Person soll aus ihren Volksgenossen* ausgerottet werden*.", footnotes: ["o. Seele", "w. Völkern", "℘ V. 20.21"] },
      { number: 28, text: "Und der HERR redete zu Mose:", heading: "Priesteranteil am Opfer" },
      { number: 29, text: "Rede zu den Söhnen Israel und sage: Wer dem HERRN sein Heilsopfer* darbringt, soll von seinem Heilsopfer seine Opfergabe dem HERRN bringen.", footnotes: ["o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)\n℘ V. 11"] },
      { number: 30, text: "Seine Hände sollen die Feueropfer des HERRN bringen; das Fett*, zusammen mit der Brust soll er es bringen: die Brust, um sie als Schwingopfer* vor dem HERRN zu schwingen*.", footnotes: ["℘ Kap. 3,3.4", "d. i. ein Opfer, das hin- und hergeschwungen und so dem HERRN geweiht wurde", "℘ Kap. 9,20.21; 2Mo 29,24.27"] },
      { number: 31, text: "Und der Priester soll das Fett auf dem Altar in Rauch aufgehen lassen, und die Brust soll Aaron und seinen Söhnen gehören." },
      { number: 32, text: "Die rechte Keule sollt ihr als Hebopfer* von euren Heilsopfern* dem Priester geben.", footnotes: ["d. i. ein Opfer, das durch Hochheben dem HERRN geweiht wird", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)"] },
      { number: 33, text: "Wer von den Söhnen Aarons das Blut des Heilsopfers* und das Fett darbringt, dem soll die rechte Keule zum Anteil werden.", footnotes: ["o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)"] },
      { number: 34, text: "Denn die Brust des Schwingopfers* und die Keule des Hebopfers* habe ich von den Söhnen Israel genommen, von ihren Heilsopfern*, und habe sie dem Priester Aaron und seinen Söhnen gegeben als eine ewige Ordnung* vonseiten der Söhne Israel*. —", footnotes: ["d. i. ein Opfer, das hin- und hergeschwungen und so dem HERRN geweiht wurde", "d. i. ein Opfer, das durch Hochheben dem HERRN geweiht wird", "o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)", "o. Gebühr; o. Anspruch auf Gebühr", "℘ Kap. 10,14.15; 4Mo 6,20; 18,18.19; 5Mo 18,3"] },
      { number: 35, text: "Das ist das Salbungsteil* Aarons und das Salbungsteil* seiner Söhne von den Feueropfern des HERRN, an dem Tag*, als man* sie herantreten ließ, für den HERRN den Priesterdienst auszuüben,", footnotes: ["w. die Salbung", "w. die Salbung", "d. h. von dem Tag an", "o. er"] },
      { number: 36, text: "das der HERR geboten hat, ihnen vonseiten der Söhne Israel zu geben, an dem Tag, als man* sie salbte*: eine ewige Ordnung* bei ihren Generationen*.", footnotes: ["o. er", "℘ Kap. 8,12.30", "o. Gebühr; o. Anspruch auf Gebühr", "℘ 2Mo 27,21"] },
      { number: 37, text: "Das ist das Gesetz für das Brandopfer, das Speisopfer und das Sündopfer und das Schuldopfer und das Einweihungsopfer und das Heilsopfer*,", footnotes: ["o. Friedensopfer(n/s); o. Abschlussopfer(n/s); o. Gemeinschaftsopfer(n/s)"] },
      { number: 38, text: "das der HERR dem Mose auf dem Berg Sinai geboten hat, an dem Tag, als er den Söhnen Israel gebot, ihre Opfergaben dem HERRN darzubringen, in der Wüste Sinai.*", footnotes: ["℘ Kap. 1,1"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose:", heading: "Weihe Aarons und seiner Söhne", footnotes: ["℘ V. 1-13: 2Mo 28,1-4; V. 1-36: 2Mo 29"] },
      { number: 2, text: "Nimm Aaron und seine Söhne mit ihm und die Kleider und das Salböl* und den Stier des Sündopfers und die zwei Widder und den Korb der ungesäuerten Brote,", footnotes: ["℘ 2Mo 30,25.31"] },
      { number: 3, text: "und versammle die ganze Gemeinde am Eingang des Zeltes der Begegnung*.", footnotes: ["℘ 4Mo 8,9"] },
      { number: 4, text: "Und Mose tat, wie der HERR ihm geboten hatte. Und die Gemeinde versammelte sich am Eingang des Zeltes der Begegnung." },
      { number: 5, text: "Und Mose sprach zu der Gemeinde: Dies ist es, was der HERR zu tun geboten hat." },
      { number: 6, text: "Und Mose ließ Aaron und seine Söhne herantreten* und wusch sie mit Wasser.", footnotes: ["w. sich nähern"] },
      { number: 7, text: "Und er legte ihm den Leibrock an und umgürtete ihn mit dem Gürtel*; und er bekleidete ihn mit dem Oberkleid und legte ihm das Efod an und umgürtete ihn mit dem Gurt des Efods und band es ihm damit fest.", footnotes: ["o. der Schärpe"] },
      { number: 8, text: "Und er legte ihm die Brusttasche* an und legte in die Brusttasche die Urim und die Tummim*;", footnotes: ["o. den Brustschild", "Urim und Tummim sind heilige Lose, die in schwierigen Fällen Rechtsentscheidungen herbeiführen konnten. Die Bedeutung der Wörter »Urim« und »Tummim« ist unsicher. LXX: Licht und Recht\n℘ 2Mo 28,15.30"] },
      { number: 9, text: "und er setzte den Kopfbund auf sein Haupt und setzte an den Kopfbund, an seine Vorderseite, das <blumenförmige> Stirnblatt aus Gold, das heilige Diadem*: ganz wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 28,36", "℘ V. 21.36; 2Mo 40,16"] },
      { number: 10, text: "Und Mose nahm das Salböl und salbte die Wohnung und alles, was darin war, und heiligte sie*.", footnotes: ["℘ 2Mo 30,29"] },
      { number: 11, text: "Und er sprengte davon siebenmal auf den Altar, und er salbte den Altar* und alle seine Geräte und das Becken und sein Gestell, um sie zu heiligen.", footnotes: ["℘ Kap. 4,6; 14,16"] },
      { number: 12, text: "Und er goss von dem Salböl auf den Kopf Aarons und salbte ihn, um ihn zu heiligen*.", footnotes: ["℘ V. 30; 2Mo 28,41; Ps 133,2"] },
      { number: 13, text: "Und Mose ließ die Söhne Aarons herantreten* und bekleidete sie mit den Leibröcken und umgürtete sie mit einem Gürtel und band ihnen die Turbane um*: ganz wie der HERR dem Mose geboten hatte*.", footnotes: ["w. sich nähern", "℘ 2Mo 40,14", "℘ V. 21.36; 2Mo 40,16"] },
      { number: 14, text: "Und er brachte den Stier des Sündopfers* herzu; und Aaron und seine Söhne legten* ihre Hände auf den Kopf des Sündopferstiers.", footnotes: ["℘ Kap. 4,4", "w. stützten, o. stemmten"] },
      { number: 15, text: "Und er schlachtete ihn, und Mose nahm das Blut und tat <etwas davon> mit seinem Finger ringsherum an die Hörner des Altars* und entsündigte <so> den Altar. Und das Blut goss er an den Fuß des Altars und heiligte ihn, indem er Sühnung für ihn erwirkte*.", footnotes: ["℘ Kap. 4,7; Hes 43,20", "℘ 4Mo 8,12; Hebr 9,21"] },
      { number: 16, text: "Und er nahm das ganze Fett, das an den Eingeweiden ist, und den Lappen der Leber und die beiden Nieren und ihr Fett, und Mose ließ es auf dem Altar in Rauch aufgehen." },
      { number: 17, text: "Und den Stier und seine Haut und sein Fleisch und seinen Mageninhalt* verbrannte er mit Feuer außerhalb des Lagers*: ganz wie der HERR dem Mose geboten hatte. —", footnotes: ["o. Darminhalt", "℘ Kap. 4,12"] },
      { number: 18, text: "Und er brachte den Widder des Brandopfers herbei; und Aaron und seine Söhne legten ihre Hände auf den Kopf des Widders*.", footnotes: ["℘ Kap. 1,4"] },
      { number: 19, text: "Und er schlachtete ihn, und Mose sprengte das <übrige> Blut ringsherum an den Altar." },
      { number: 20, text: "Den Widder aber zerlegte er in seine Stücke. Und Mose ließ den Kopf und die Stücke und das Fett in Rauch aufgehen." },
      { number: 21, text: "Die Eingeweide und die Unterschenkel aber wusch er mit Wasser. Und Mose ließ den ganzen Widder auf dem Altar in Rauch aufgehen: ein Brandopfer war es zum wohlgefälligen Geruch*, ein Feueropfer für den HERRN war es: ganz wie der HERR dem Mose geboten hatte*. —", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung\n℘ Kap. 1,9", "℘ V. 21.36; 2Mo 40,16"] },
      { number: 22, text: "Und er brachte den zweiten Widder, den Widder der Einweihung, herbei; und Aaron und seine Söhne legten ihre Hände auf den Kopf des Widders." },
      { number: 23, text: "Und er schlachtete ihn, und Mose nahm <etwas> von seinem Blut und tat es auf das rechte Ohrläppchen Aarons und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes*.", footnotes: ["℘ Kap. 14,14.17.25.28"] },
      { number: 24, text: "Und er ließ die Söhne Aarons herantreten*, und Mose tat <etwas> von dem Blut auf ihr rechtes Ohrläppchen und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes*; und Mose sprengte das <übrige> Blut ringsherum an den Altar.", footnotes: ["w. sich nähern", "℘ Kap. 14,14.17.25.28"] },
      { number: 25, text: "Und er nahm das Fett und den Fettschwanz und alles Fett, das an den Eingeweiden ist, und den Lappen der Leber und die beiden Nieren und ihr Fett und die rechte Keule;" },
      { number: 26, text: "und er nahm aus dem Korb der ungesäuerten Brote, der vor dem HERRN war, einen ungesäuerten Kuchen und einen Kuchen mit Öl bestrichenen Brotes und einen Fladen und legte es auf die Fettstücke und auf die rechte Keule;" },
      { number: 27, text: "und er legte das alles auf die Hände Aarons und auf die Hände seiner Söhne und schwang es als Schwingopfer vor dem HERRN*.", footnotes: ["℘ Kap. 14,12"] },
      { number: 28, text: "Und Mose nahm es von ihren Händen weg und ließ es auf dem Altar in Rauch aufgehen, auf dem Brandopfer: ein Einweihungsopfer* zum wohlgefälligen Geruch*, ein Feueropfer war es für den HERRN.", footnotes: ["w. eine Füllung; weil die Hände der Priester mit den in V. 25 und 26 erwähnten Dingen gefüllt wurden; vgl. 2Mo 28,41", "o. Geruch der Befriedigung o. Beschwichtigung\n℘ Kap. 1,9"] },
      { number: 29, text: "Und Mose nahm die Brust und schwang sie als Schwingopfer vor dem HERRN; von dem Einweihungswidder wurde sie für Mose zum Anteil: ganz wie der HERR dem Mose geboten hatte." },
      { number: 30, text: "Und Mose nahm von dem Salböl und von dem Blut, das auf dem Altar war, und sprengte es auf Aaron, auf seine Kleider sowie auf seine Söhne und auf die Kleider seiner Söhne mit ihm; und er heiligte Aaron, seine Kleider und seine Söhne und die Kleider seiner Söhne mit ihm.*", footnotes: ["℘ V. 12"] },
      { number: 31, text: "Und Mose sagte zu Aaron und zu seinen Söhnen: Kocht das Fleisch am Eingang des Zeltes der Begegnung! Ihr sollt es dort essen und das Brot, das im Korb des Einweihungsopfers ist, ganz wie ich geboten habe: Aaron und seine Söhne sollen es essen." },
      { number: 32, text: "Und den Rest von dem Fleisch und von dem Brot sollt ihr mit Feuer verbrennen." },
      { number: 33, text: "Und vom Eingang des Zeltes der Begegnung sollt ihr sieben Tage lang nicht weggehen bis zu dem Tag, an dem die Tage eures Einweihungsopfers* erfüllt sind; denn sieben Tage sollen euch die Hände gefüllt werden*.", footnotes: ["w. eurer Füllung; s. Anm. zu V. 28", "Der Ausdruck bezieht sich normalerweise auf die Einkünfte des Priesters aus seiner Amtstätigkeit; hier ist aber die Amtseinsetzung gemeint.\n℘ Hes 43,26"] },
      { number: 34, text: "So wie man an diesem Tag tat, hat der HERR zu tun geboten, um Sühnung für euch zu erwirken." },
      { number: 35, text: "Sieben Tage lang sollt ihr Tag und Nacht am Eingang des Zeltes der Begegnung bleiben und sollt für den Dienst des HERRN sorgen, damit ihr nicht sterbt; denn so ist mir geboten worden." },
      { number: 36, text: "Und Aaron und seine Söhne taten alles, was der HERR durch Mose geboten hatte*.", footnotes: ["℘ V. 9.13.21"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und es geschah am achten Tag, da rief Mose Aaron und seine Söhne und die Ältesten Israels,", heading: "Diensteinführung Aarons und seiner Söhne" },
      { number: 2, text: "und er sagte zu Aaron: Nimm dir ein Kalb von den Rindern* zum Sündopfer* und einen Widder zum Brandopfer, ohne Fehler*, und bringe <sie> dar vor dem HERRN!", footnotes: ["w. ein Kalb, einen Rindersohn", "℘ Kap. 4,3", "℘ Kap. 1,3.10"] },
      { number: 3, text: "Und zu den Söhnen Israel sollst du reden: Nehmt einen Ziegenbock* für das Sündopfer* und ein Kalb und ein Lamm, einjährige, ohne Fehler, für das Brandopfer,", footnotes: ["w. Haarigen der Ziegen", "℘ Kap. 4,3"] },
      { number: 4, text: "und einen Stier und einen Widder für das Heilsopfer*, um sie vor dem HERRN zu opfern, und ein Speisopfer*, mit Öl gemengt*, denn heute wird der HERR euch erscheinen*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ Kap. 3,1; Hes 43,27", "℘ Kap. 2,1", "o. angefeuchtet", "℘ V. 23; 2Mo 29,43"] },
      { number: 5, text: "Und sie brachten das, was Mose geboten hatte, vor das Zelt der Begegnung, und die ganze Gemeinde trat heran* und stand vor dem HERRN.", footnotes: ["w. näherte sich dem"] },
      { number: 6, text: "Und Mose sagte: Dies ist es, was der HERR geboten hat, dass ihr es tun sollt; und die Herrlichkeit des HERRN wird euch erscheinen*.", footnotes: ["℘ V. 23; 2Mo 29,43"] },
      { number: 7, text: "Und Mose sagte zu Aaron: Tritt an den* Altar und opfere dein Sündopfer und dein Brandopfer und erwirke Sühnung für dich und für das Volk*! Opfere die Opfergabe des Volkes und tue Sühnung für sie, ganz wie der HERR geboten hat!", footnotes: ["w. Nähere dich dem", "℘ Kap. 16,6.11.24"] },
      { number: 8, text: "Und Aaron trat an den* Altar und schlachtete das Kalb des Sündopfers, das für ihn war.", footnotes: ["w. näherte sich dem"] },
      { number: 9, text: "Und die Söhne Aarons brachten ihm das Blut, und er tauchte seinen Finger in das Blut und gab <etwas> davon an die Hörner des Altars*, und er goss das Blut an den Fuß des Altars*.", footnotes: ["℘ Kap. 4,7", "℘ V. 23; 2Mo 29,43"] },
      { number: 10, text: "Und das Fett und die Nieren und den Lappen der Leber vom Sündopfer ließ er auf dem Altar in Rauch aufgehen*, ganz wie der HERR dem Mose geboten hatte.", footnotes: ["℘ Kap. 3,3-5"] },
      { number: 11, text: "Und das Fleisch und die Haut verbrannte er mit Feuer außerhalb des Lagers." },
      { number: 12, text: "Und er schlachtete das Brandopfer; und die Söhne Aarons reichten ihm das Blut, und er sprengte es ringsherum an den Altar." },
      { number: 13, text: "Und das Brandopfer reichten sie ihm in seinen Stücken und den Kopf, und er ließ es auf dem Altar in Rauch aufgehen." },
      { number: 14, text: "Und er wusch die Eingeweide und die Unterschenkel und ließ sie auf dem Brandopfer auf dem Altar in Rauch aufgehen." },
      { number: 15, text: "Dann brachte er herzu die Opfergabe des Volkes, nahm den Ziegenbock* des Sündopfers*, der* für das Volk war, und schlachtete ihn und opferte ihn als Sündopfer wie das erste Mal.", footnotes: ["w. Haarigen", "℘ Kap. 10,16; 2Chr 29,24", "o. das"] },
      { number: 16, text: "Und er brachte das Brandopfer herzu und opferte es nach der Vorschrift." },
      { number: 17, text: "Und er brachte das Speisopfer herzu und füllte seine Hand davon und ließ es auf dem Altar in Rauch aufgehen außer dem Morgenbrandopfer*.", footnotes: ["℘ 2Mo 29,38.39; 1Chr 16,40; 2Chr 2,3"] },
      { number: 18, text: "Und er schlachtete den Stier und den Widder, das Heilsopfer*, das für das Volk war. Und die Söhne Aarons reichten ihm das Blut, und er sprengte es an den Altar ringsherum,", footnotes: ["o. Friedensopfer(s); o. Abschlussopfer(s); o. Gemeinschaftsopfer(s)"] },
      { number: 19, text: "und die Fettstücke von dem Stier und von dem Widder den Fettschwanz und was <die Eingeweide> bedeckt und die Nieren und den Lappen der Leber." },
      { number: 20, text: "Und sie legten die Fettstücke auf die Bruststücke, und er ließ die Fettstücke auf dem Altar in Rauch aufgehen." },
      { number: 21, text: "Und die Bruststücke und die rechte Keule schwang Aaron als Schwingopfer vor dem HERRN, ganz wie Mose geboten hatte*.", footnotes: ["hebr. Handschr., SamPent und LXX: wie der HERR dem Mose geboten hatte\n℘ Kap. 7,30-34"] },
      { number: 22, text: "Und Aaron erhob seine Hände zum Volk hin und segnete sie*. Und er stieg herab nach der Opferung des Sündopfers und des Brandopfers und des Heilsopfers*.", footnotes: ["℘ 2Mo 39,43; 4Mo 6,23; 5Mo 10,8; 21,5", "o. Friedensopfer(s); o. Abschlussopfer(s); o. Gemeinschaftsopfer(s)"] },
      { number: 23, text: "Und Mose und Aaron gingen hinein in das Zelt der Begegnung. Und als sie herauskamen, segneten sie das Volk. Da erschien die Herrlichkeit des HERRN dem ganzen Volk*.", footnotes: ["℘ V. 4.6; 2Mo 16,10; Hebr 7,7"] },
      { number: 24, text: "Und Feuer ging vom HERRN aus* und verzehrte auf dem Altar das Brandopfer und die Fettstücke*. Als das ganze Volk es sah, da jauchzten sie und fielen auf ihr Angesicht*.", footnotes: ["℘ Kap. 10,2; 1Chr 21,26", "℘ Ri 6,21; 1Kö 18,38", "℘ 4Mo 23,21; Ri 13,20; 2Chr 7,1.3"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und die Söhne Aarons, Nadab und Abihu*, nahmen jeder sein Feuerbecken* und taten Feuer hinein und legten Räucherwerk darauf und brachten fremdes Feuer* vor dem HERRN dar, das er ihnen nicht geboten hatte.", heading: "Nadabs und Abihus eigenmächtiges Opfer und Tod — Gebote für die Priester", footnotes: ["℘ 2Mo 6,23", "Das ist ein Gefäß zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ 2Mo 30,9"] },
      { number: 2, text: "Da ging Feuer vom HERRN aus* und verzehrte sie. Und sie starben vor dem HERRN*.", footnotes: ["℘ Kap. 9,24", "℘ Kap. 16,1; 4Mo 3,4; 14,37; 2Kö 1,10.12; 1Chr 24,2; Hebr 12,29"] },
      { number: 3, text: "Und Mose sagte zu Aaron: Dies ist es, was der HERR geredet hat: Bei denen, die mir nahen*, will ich geheiligt und vor dem ganzen Volk will ich verherrlicht werden*. Und Aaron schwieg*.", footnotes: ["o. nahe sind\n℘ 2Mo 19,22", "o. will ich mich als heilig erweisen, und vor dem . . . Volk will ich mich verherrlichen\n℘ Kap. 21,6; 4Mo 20,12", "℘ Ps 39,10"] },
      { number: 4, text: "Und Mose rief Mischaël und Elizafan, die Söhne von Aarons Onkel Usiël*, und sagte zu ihnen: Tretet herbei, tragt eure Brüder weg vom Heiligtum* hinaus vor das Lager!", footnotes: ["℘ 2Mo 6,18.22", "w. weg vom Gesicht des Heiligtums"] },
      { number: 5, text: "Und sie traten herbei und trugen sie in ihren Leibröcken hinaus vor das Lager, ganz wie Mose geredet hatte. —" },
      { number: 6, text: "Und Mose sagte zu Aaron und zu seinen Söhnen Eleasar und Itamar*: Euer Haupthaar* sollt ihr nicht frei hängen lassen* und eure Kleider nicht zerreißen*, damit ihr nicht sterbt und er nicht über die ganze Gemeinde zornig wird*. Aber eure Brüder, das ganze Haus Israel, sollen diesen Brand beweinen, den der HERR angerichtet hat.", footnotes: ["℘ 2Mo 6,23; 4Mo 20,25", "w. Eure Köpfe", "o. verwildern lassen", "℘ Kap. 21,10; Hes 24,17", "℘ 4Mo 16,22; Jos 7,1"] },
      { number: 7, text: "Vom Eingang des Zeltes der Begegnung sollt ihr nicht weggehen, damit ihr nicht sterbt; denn das Öl der Salbung des HERRN ist auf euch*. Und sie taten nach dem Wort des Mose.", footnotes: ["℘ Kap. 8,12.30; 21,12; 2Mo 28,41"] },
      { number: 8, text: "Und der HERR redete zu Aaron:" },
      { number: 9, text: "Wein und berauschendes Getränk sollst du nicht trinken, du und deine Söhne mit dir, wenn ihr in das Zelt der Begegnung hineingeht*, damit ihr nicht sterbt — eine ewige Ordnung für eure Generationen* —,", footnotes: ["℘ 4Mo 6,3; Jes 28,7; Hes 44,21", "℘ 2Mo 27,21"] },
      { number: 10, text: "und damit ihr unterscheidet zwischen dem Heiligen und dem Unheiligen und zwischen dem Reinen und dem Unreinen*", footnotes: ["℘ Kap. 11,47; 14,57; 20,25; Hes 22,26"] },
      { number: 11, text: "und damit ihr die Söhne Israel all die Ordnungen, die der HERR durch Mose zu euch geredet hat, lehrt.*", footnotes: ["℘ 5Mo 33,10; 2Chr 15,3; Mal 2,7"] },
      { number: 12, text: "Und Mose redete zu Aaron und zu seinen übrig gebliebenen Söhnen Eleasar und zu Itamar: Nehmt das Speisopfer, das von den Feueropfern des HERRN übrig bleibt, und esst es ungesäuert neben dem Altar; denn hochheilig ist es*.", footnotes: ["℘ Kap. 21,22"] },
      { number: 13, text: "Und ihr sollt es an heiliger Stätte essen, denn es ist deine Gebühr* und die Gebühr deiner Söhne von den Feueropfern des HERRN; denn so ist mir geboten worden.", footnotes: ["o. Anspruch; o. Ordnung"] },
      { number: 14, text: "Und die Brust des Schwingopfers und die Keule des Hebopfers sollt ihr an reiner Stätte essen, du und deine Söhne und deine Töchter mit dir; denn als deine Gebühr* und die Gebühr deiner Söhne sind sie gegeben von den Heilsopfern* der Söhne Israel.", footnotes: ["o. Anspruch; o. Ordnung", "o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern"] },
      { number: 15, text: "Die Keule des Hebopfers und die Brust des Schwingopfers sollen sie mit den Feueropfern der Fettstücke bringen, um sie als Schwingopfer vor dem HERRN zu schwingen. Und das soll dir und deinen Söhnen mit dir zu einer ewigen Gebühr* sein, ganz wie der HERR geboten hat*.", footnotes: ["o. Anspruch; o. Ordnung", "℘ Kap. 2,3.10; 7,30-34; 2Mo 29,28"] },
      { number: 16, text: "Und Mose suchte eifrig den Ziegenbock des Sündopfers*, und siehe, er war verbrannt. Da wurde er zornig über die übrig gebliebenen Söhne Aarons Eleasar und Itamar und sagte:", footnotes: ["℘ Kap. 9,15"] },
      { number: 17, text: "Warum habt ihr das Sündopfer nicht an heiliger Stätte gegessen? Es ist doch hochheilig*! Und er hat es euch gegeben, die Schuld der Gemeinde zu tragen*, um vor dem HERRN Sühnung für sie zu erwirken.", footnotes: ["℘ Kap. 21,22", "℘ 2Mo 28,38"] },
      { number: 18, text: "Siehe, sein Blut ist nicht in das Innere des Heiligtums gebracht worden; ihr hättet es auf jeden Fall im Heiligtum essen sollen, ganz wie ich geboten habe*.", footnotes: ["Die syr., aram. und lat. Üs. lesen: wie ich Befehl erhalten habe; LXX: wie der HERR mir befohlen hat\n℘ Kap. 6,19; 2Mo 29,33"] },
      { number: 19, text: "Und Aaron redete zu Mose: Siehe, heute haben sie ihr Sündopfer und ihr Brandopfer vor dem HERRN dargebracht, und solches ist mir begegnet! Hätte ich heute das Sündopfer gegessen, wäre es in den Augen des HERRN gut gewesen?" },
      { number: 20, text: "Und Mose hörte es, und es war gut in seinen Augen." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und zu Aaron und sprach zu ihnen:", heading: "Reine und unreine Tiere", footnotes: ["℘ 5Mo 14,4-19"] },
      { number: 2, text: "Redet zu den Söhnen Israel: Dies sind die Tiere, die ihr von allen Tieren*, die auf der Erde sind, essen dürft!*", footnotes: ["o. von allem Vieh", "℘ Hebr 9,10"] },
      { number: 3, text: "Alles, was gespaltene Hufe hat, und zwar wirklich aufgespaltene Hufe, <und was> wiederkäut* <unter den Tieren>, das dürft ihr essen.", footnotes: ["w. das Gekaute <wieder> aufsteigen lässt; entsprechend auch in den Versen 4—6"] },
      { number: 4, text: "Nur diese von den wiederkäuenden und von denen, die gespaltene Hufe haben, dürft ihr nicht essen: das Kamel, denn es käut wieder, aber gespaltene Hufe hat es nicht: unrein soll es euch sein;" },
      { number: 5, text: "den Klippdachs*, denn er käut wieder*, aber er hat keine gespaltenen Hufe: unrein soll er euch sein;", footnotes: ["d. i. ein murmeltierähnlicher gelbbrauner Pflanzenfresser, der in kleinen Rudeln zwischen Felsen lebt\n℘ Spr 30,26", "s. Anm. zu V. 3"] },
      { number: 6, text: "den Hasen, denn er käut wieder*, aber er hat keine gespaltenen Hufe: unrein soll er euch sein;", footnotes: ["s. Anm. zu V. 3"] },
      { number: 7, text: "das Schwein, denn es hat gespaltene Hufe, und zwar wirklich aufgespaltene Hufe, aber es käut nicht wieder: unrein soll es euch sein*.", footnotes: ["℘ Jes 65,4"] },
      { number: 8, text: "Von ihrem Fleisch dürft ihr nicht essen und ihr Aas nicht berühren; unrein sollen sie euch sein." },
      { number: 9, text: "Dieses dürft ihr essen von allem, was im Wasser ist: Alles, was Flossen und Schuppen hat im Wasser, in den Meeren und in den Flüssen, das dürft ihr essen." },
      { number: 10, text: "Aber alles, was keine Flossen und Schuppen hat in den Meeren und in den Flüssen von allem Gewimmel des Wassers und von jedem Lebewesen*, das im Wasser ist, sie sollen euch etwas Abscheuliches sein.", footnotes: ["w. von jeder lebendigen Seele"] },
      { number: 11, text: "Ja, etwas Abscheuliches sollen sie euch sein: Von ihrem Fleisch sollt ihr nicht essen, und ihr Aas sollt ihr verabscheuen." },
      { number: 12, text: "Alles im Wasser, was nicht Flossen und Schuppen hat, soll euch etwas Abscheuliches sein." },
      { number: 13, text: "Und diese von den Vögeln sollt ihr verabscheuen — sie sollen nicht gegessen werden, etwas Abscheuliches sind sie: den Adler* und den Lämmergeier und den Mönchsgeier", footnotes: ["o. den Gänsegeier"] },
      { number: 14, text: "und die Gabelweihe und die Königsweihe nach ihrer Art," },
      { number: 15, text: "alle Raben nach ihrer Art" },
      { number: 16, text: "und die Straußenhenne* und den Falken* und die Seemöwe* und den Habicht nach seiner Art", footnotes: ["w. Tochter des Straußes. — Nach anderen bezeichnet das hebr. Wort eine Eulenart.", "Andere vermuten eine Eulenart.", "o. Fledermaus"] },
      { number: 17, text: "und den Steinkauz und die Fischeule und den Ibis*", footnotes: ["o. die Katzenohreule"] },
      { number: 18, text: "und die Schleiereule und den Wüstenkauz und den Aasgeier" },
      { number: 19, text: "und den Storch und den Fischreiher* nach seiner Art und den Wiedehopf und die Fledermaus.", footnotes: ["o. Kormoran; o. Regenpfeifer; o. Strandläufer"] },
      { number: 20, text: "Alles geflügelte Kleingetier*, das auf vieren geht, soll euch etwas Abscheuliches sein.", footnotes: ["w. Gewimmel"] },
      { number: 21, text: "Nur dieses dürft ihr essen von allem geflügelten Kleingetier*, das auf vieren geht: was Unterschenkel hat* oberhalb seiner Füße, um damit auf der Erde zu hüpfen.", footnotes: ["w. Gewimmel", "so mit allen alten Üs. und der Leseform des Mas. T.; d. i. was Sprungbeine hat; mit der Schreibform: was keine Unterschenkel <hat>"] },
      { number: 22, text: "Diese dürft ihr von ihnen essen: den Arbe nach seiner Art und den Solam nach seiner Art und den Hargol nach seiner Art und den Hagab nach seiner Art*.", footnotes: ["vier verschiedene Arten von Heuschrecken\n℘ Mt 3,4"] },
      { number: 23, text: "Aber alles geflügelte Kleingetier*, das vier Füße hat, soll euch etwas Abscheuliches sein.", footnotes: ["w. Gewimmel"] },
      { number: 24, text: "Und durch diese* werdet ihr euch unrein machen*. Jeder, der ihr Aas berührt, wird unrein sein bis zum Abend*,", footnotes: ["w. in Bezug auf diese", "℘ Kap. 5,2", "℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 25, text: "und jeder, der von ihrem Aas <etwas> trägt, soll seine Kleider waschen und wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 26, text: "Für jedes Tier, das gespaltene Hufe, aber nicht wirklich aufgespaltene Hufe hat und nicht wiederkäut <gilt>: Unrein sollen sie euch sein; jeder, der sie berührt, wird unrein sein." },
      { number: 27, text: "Und alles, was auf seinen Tatzen geht unter allem Getier, das auf vieren geht, sie sollen euch unrein sein; jeder, der ihr Aas berührt, wird unrein sein bis zum Abend*.", footnotes: ["℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 28, text: "Und wer ihr Aas trägt, soll seine Kleider waschen und wird bis zum Abend unrein sein*. Unrein sollen sie euch sein.", footnotes: ["℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 29, text: "Und diese sollen euch unrein sein unter dem Gewimmel, das auf der Erde wimmelt: der Maulwurf und die Springmaus* und die Eidechse* nach ihrer Art", footnotes: ["℘ Jes 66,17", "d. i. die Dornschwanzeidechse\n℘ Spr 30,28"] },
      { number: 30, text: "und die Anaka und der Koach und die Letaah und der Chomet* und das Chamäleon.", footnotes: ["vier verschiedene Arten von Eidechsen"] },
      { number: 31, text: "Diese sollen euch unrein sein unter allem Kleingetier*. Jeder, der sie berührt, wenn sie tot sind, wird bis zum Abend unrein sein*.", footnotes: ["w. Gewimmel", "℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 32, text: "Und alles, worauf eines von ihnen fällt, wenn sie tot sind, wird unrein sein: jedes Holzgerät oder ein Kleid oder Fell oder Sack, jedes Gerät, womit eine Arbeit verrichtet wird, es soll ins Wasser getan werden und wird bis zum Abend unrein sein*; dann wird es rein sein.", footnotes: ["℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 33, text: "Und jedes Tongefäß, in das eines von ihnen hineinfällt: alles, was darin ist, wird unrein sein, und das Gefäß sollt ihr zerbrechen*.", footnotes: ["℘ Kap. 6,21; 4Mo 19,15"] },
      { number: 34, text: "Von aller Speise, die gegessen wird, auf die <solches> Wasser kommt<, gilt>: Sie wird unrein sein. Und alles Getränk, das getrunken wird, wird unrein sein in jedem <solchen> Gefäß." },
      { number: 35, text: "Und alles, worauf <etwas> von ihrem Aas fällt, wird unrein sein. Ofen und Herd sollen niedergerissen werden, unrein sind sie, unrein sollen sie euch sein." },
      { number: 36, text: "Doch Quelle und Zisterne, Wasserbehälter werden rein sein. Wer aber das Aas darin* berührt, wird unrein sein.", footnotes: ["w. ihr Aas"] },
      { number: 37, text: "Und wenn von ihrem Aas <etwas> auf irgendwelche Saat fällt, die gesät wird, ist sie rein." },
      { number: 38, text: "Wenn aber Wasser auf den Samen getan wurde, und es fällt von ihrem Aas <etwas> auf ihn, soll er euch unrein sein." },
      { number: 39, text: "Und wenn eins von dem Vieh stirbt, das euch zur Nahrung dient: Wer sein Aas berührt, wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 40, text: "Und wer von seinem Aas isst*, soll seine Kleider waschen und wird bis zum Abend unrein sein. Und wer dessen Aas trägt, soll seine Kleider waschen und wird bis zum Abend unrein sein*.", footnotes: ["℘ 5Mo 14,21; Hes 4,14", "℘ Kap. 14,46; 15; 16,26.28; 17,15; 22,6; 4Mo 19,7-22"] },
      { number: 41, text: "Und alles Kleingetier*, das auf der Erde wimmelt, ist etwas Abscheuliches: es soll nicht gegessen werden.", footnotes: ["w. Gewimmel"] },
      { number: 42, text: "Alles, was auf dem Bauch kriecht, und alles, was auf vieren geht, bis zu allem Vielfüßigen von allem Kleingetier*, das auf der Erde wimmelt: ihr sollt sie nicht essen; denn etwas Abscheuliches sind sie.", footnotes: ["w. Gewimmel"] },
      { number: 43, text: "Macht euch selbst nicht zu etwas Abscheulichem durch all das wimmelnde Kleingetier, und macht euch nicht unrein durch sie, so dass ihr dadurch unrein würdet!" },
      { number: 44, text: "Denn ich bin der HERR, euer Gott*. So heiligt euch und seid heilig*, denn ich bin heilig! Und ihr sollt euch selbst* nicht unrein machen durch all das Kleingetier*, das sich auf der Erde regt.", footnotes: ["℘ Kap. 18,2.30; 19,3.10; 4Mo 15,40.41", "℘ Kap. 19,2; 20,7.26; 2Mo 19,6; 22,30; Jos 24,19; 1Sam 2,2; 1Thes 4,3.7; 1Petr 1,15.16", "w. eure Seelen", "w. Gewimmel"] },
      { number: 45, text: "Denn ich bin der HERR, der euch aus dem Land Ägypten heraufgeführt hat*, um euer Gott zu sein*: So sollt ihr heilig sein, denn ich bin heilig!*", footnotes: ["℘ Kap. 19,36", "℘ 2Mo 20,2", "℘ Kap. 19,2;20,7.26; 2Mo 19,6; 22,30; Jos 24,19; 1Sam 2,2; 1Thes 4,3.7; 1Petr 1,15.16"] },
      { number: 46, text: "Das ist das Gesetz <betreffs> des Viehs und der Vögel und <betreffs> jedes Lebewesens*, das sich im Wasser regt, und von jedem Wesen, das auf der Erde wimmelt;", footnotes: ["w. jeder lebendigen Seele"] },
      { number: 47, text: "um zu unterscheiden zwischen dem Unreinen und dem Reinen* und zwischen dem Getier, das gegessen wird, und dem Getier, das nicht gegessen werden soll.", footnotes: ["℘ Kap. 10,10; 1Mo 7,2"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Verordnungen für Wöchnerinnen" },
      { number: 2, text: "Rede zu den Söhnen Israel: Wenn eine Frau empfängt und ein männliches Kind gebiert, so wird sie sieben Tage <lang> unrein sein; wie in den Tagen der Absonderung* ihres Unwohlseins* wird sie unrein sein*.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel", "o. Blutflusses", "℘ Kap. 5,3; 15,19"] },
      { number: 3, text: "Und am achten Tag soll das Fleisch seiner Vorhaut beschnitten werden*.", footnotes: ["℘ 1Mo 17,12; Joh 7,22; Apg 15,1; Phil 3,5"] },
      { number: 4, text: "Und sie soll 33 Tage im Blut der Reinigung <daheim> bleiben. Nichts Heiliges soll sie anrühren, und zum Heiligtum soll sie nicht kommen, bis die Tage ihrer Reinigung erfüllt sind*.", footnotes: ["℘ Lk 2,22"] },
      { number: 5, text: "Und wenn sie ein weibliches Kind gebiert, so wird sie zwei Wochen unrein sein wie bei ihrer Absonderung*. Und 66 Tage soll sie wegen des Blutes der Reinigung daheim bleiben.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel"] },
      { number: 6, text: "Und wenn die Tage ihrer Reinigung für einen Sohn oder eine Tochter erfüllt sind, soll sie ein einjähriges Lamm zum Brandopfer bringen und eine junge Taube oder eine Turteltaube zum Sündopfer, zum Priester an den Eingang des Zeltes der Begegnung." },
      { number: 7, text: "Und er soll es vor dem HERRN darbringen und Sühnung für sie erwirken, und sie wird rein sein vom Fluss ihres Blutes. Das ist das Gesetz der Gebärenden bei einem männlichen oder bei einem weiblichen Kind." },
      { number: 8, text: "Und wenn ihre Hand das zu einem Schaf* Ausreichende nicht findet*, soll sie zwei Turteltauben oder zwei junge Tauben* nehmen, eine zum Brandopfer und eine zum Sündopfer*. Und der Priester soll Sühnung für sie erwirken, und sie wird rein sein*.", footnotes: ["o. einer Ziege; o. einem Lamm", "d. h. wenn sie (finanziell) dazu nicht in der Lage ist; dieselbe Wendung wie in Ri 9,33; 1Sam 10,7; 25,8\n℘ Kap. 5,7.11", "℘ Kap. 1,14", "℘ Lk 2,24", "℘ Kap. 15,15"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und zu Aaron:", heading: "Gesetz vom Aussatz an Menschen" },
      { number: 2, text: "Wenn ein Mensch in der Haut seines Fleisches eine Erhöhung oder einen Schorf oder einen Flecken bekommt, und es wird in der Haut seines Fleisches zu einem Aussatzmal, dann soll er zum Priester Aaron gebracht werden oder zu einem von seinen Söhnen, den Priestern*.", footnotes: ["℘ 5Mo 24,8; Mt 8,4"] },
      { number: 3, text: "Und besieht der Priester das Mal in der Haut des Fleisches, und das Haar in dem Mal hat sich in Weiß verwandelt, und das Mal erscheint tiefer als die <übrige> Haut seines Fleisches, <dann> ist es das Mal des Aussatzes. Und sieht es der Priester, dann soll er ihn für unrein erklären*.", footnotes: ["℘ Kap. 5,3"] },
      { number: 4, text: "Und wenn der Flecken in der Haut seines Fleisches weiß ist und er nicht tiefer erscheint als die Haut, und sein Haar hat sich nicht in Weiß verwandelt, dann soll der Priester <den, der> das Mal <hat, für> sieben Tage einschließen*.", footnotes: ["℘ V. 50; Kap. 14,38; 4Mo 12,14.15"] },
      { number: 5, text: "Und besieht es der Priester am siebten Tag, und siehe, das Mal ist in seinen Augen stehen geblieben, das Mal hat in der Haut nicht um sich gegriffen, dann soll der Priester ihn* zum zweiten Mal <für> sieben Tage einschließen.", footnotes: ["w. es; d. i. das Mal"] },
      { number: 6, text: "Und besieht es der Priester am siebten Tag zum zweiten Mal, und siehe, das Mal ist blass geworden, und das Mal hat nicht um sich gegriffen in der Haut, dann soll der Priester ihn für rein erklären: es ist Schorf*. Er soll seine Kleider waschen und ist rein*.", footnotes: ["o. Hautausschlag", "℘ Kap. 14,8"] },
      { number: 7, text: "Wenn aber der Schorf* in der Haut weiter um sich greift, nachdem er sich dem Priester zu seiner Reinigung gezeigt hat, dann soll er sich dem Priester zum zweiten Mal zeigen.", footnotes: ["o. Hautausschlag"] },
      { number: 8, text: "Und besieht <ihn> der Priester, und siehe, der Schorf* hat in der Haut um sich gegriffen, dann soll der Priester ihn für unrein erklären: Aussatz ist es.", footnotes: ["o. Hautausschlag"] },
      { number: 9, text: "Wenn ein Aussatzmal an einem Menschen entsteht, dann soll er zum Priester gebracht werden." },
      { number: 10, text: "Und besieht <ihn> der Priester, und siehe, es ist eine weiße Erhöhung in der Haut, und sie hat das Haar in Weiß verwandelt, und eine Bildung von wildem Fleisch ist in der Erhöhung," },
      { number: 11, text: "<dann> ist es ein alter Aussatz in der Haut seines Fleisches, und der Priester soll ihn für unrein erklären; er soll ihn nicht einschließen, denn er ist unrein." },
      { number: 12, text: "Wenn aber der Aussatz in der Haut kräftig ausbricht* und der Aussatz die ganze Haut dessen, der das Mal hat*, bedeckt, von seinem Kopf bis zu seinen Füßen, wohin auch die Augen des Priesters sehen,", footnotes: ["o. wuchert", "w. die ganze Haut des Mals"] },
      { number: 13, text: "und der Priester besieht <ihn>, und siehe, der Aussatz hat sein ganzes Fleisch bedeckt, dann soll er <den, der> das Mal <hat,> für rein erklären; hat es sich ganz in Weiß verwandelt*, ist er* rein.", footnotes: ["℘ 4Mo 12,10", "o. es"] },
      { number: 14, text: "An dem Tag aber, da wildes Fleisch an ihm gesehen wird, wird er unrein sein." },
      { number: 15, text: "Und sieht der Priester das wilde Fleisch, dann soll er ihn für unrein erklären; das rohe Fleisch ist unrein: Aussatz ist es." },
      { number: 16, text: "Wenn aber das wilde Fleisch wieder zurückgeht und in Weiß verwandelt wird, dann soll er zum Priester kommen." },
      { number: 17, text: "Und besieht ihn* der Priester, und siehe, das Mal ist in Weiß verwandelt, dann soll der Priester <den, der> das Mal <hat,> für rein erklären: rein ist er.", footnotes: ["w. es; d. i. das Mal"] },
      { number: 18, text: "Und wenn <im> Fleisch, in dessen Haut, ein Geschwür entsteht und <wieder> heilt," },
      { number: 19, text: "und es entsteht an der Stelle des Geschwürs eine weiße Erhöhung oder ein weiß-rötlicher Fleck, dann soll er sich dem Priester zeigen." },
      { number: 20, text: "Und besieht <ihn> der Priester, und siehe, der Fleck* erscheint niedriger als die <übrige> Haut, und sein Haar hat sich in Weiß verwandelt, dann soll der Priester ihn für unrein erklären: das Mal des Aussatzes ist es. Er ist in dem Geschwür ausgebrochen.", footnotes: ["w. er"] },
      { number: 21, text: "Wenn der Priester ihn besieht, und siehe, es ist kein weißes Haar darin, und der Fleck* ist nicht niedriger als die <übrige> Haut und ist blass, dann soll der Priester ihn <für> sieben Tage einschließen.", footnotes: ["w. er"] },
      { number: 22, text: "Wenn er aber in der Haut weiter um sich greift, dann soll der Priester ihn für unrein erklären: ein Mal ist es." },
      { number: 23, text: "Und wenn der Fleck an seiner Stelle stehen bleibt, <wenn er> nicht um sich gegriffen hat, dann ist es die Narbe des Geschwürs. Der Priester soll ihn für rein erklären." },
      { number: 24, text: "Oder wenn <im> Fleisch, in dessen Haut, eine <Brand>wunde entsteht, und die Bildung der Wunde wird ein weiß-rötlicher oder weißer Fleck," },
      { number: 25, text: "und der Priester besieht ihn, und siehe, das Haar im Fleck ist in Weiß verwandelt, und er erscheint tiefer als die <übrige> Haut, <dann> ist es Aussatz; er ist in der <Brand>wunde ausgebrochen. Der Priester soll ihn für unrein erklären: das Mal des Aussatzes ist es." },
      { number: 26, text: "Und wenn der Priester ihn besieht, und siehe, es ist kein weißes Haar in dem Fleck, und er ist nicht niedriger als die <übrige> Haut und ist blass, dann soll der Priester ihn <für> sieben Tage einschließen." },
      { number: 27, text: "Und der Priester soll ihn am siebten Tag besehen. Wenn er in der Haut weiter um sich greift, dann soll der Priester ihn für unrein erklären: das Mal des Aussatzes ist es." },
      { number: 28, text: "Und wenn der Fleck an seiner Stelle stehen bleibt, <wenn er> in der Haut nicht um sich gegriffen hat und blass ist, ist es die Erhöhung der <Brand>wunde. Der Priester soll ihn für rein erklären, denn es ist die Narbe der <Brand>wunde." },
      { number: 29, text: "Und wenn ein Mann oder eine Frau ein Mal am Kopf oder am Bart bekommt," },
      { number: 30, text: "und der Priester besieht das Mal, und siehe, es erscheint tiefer als die <übrige> Haut, und goldglänzendes, dünnes Haar ist darin, dann soll der Priester ihn für unrein erklären: Krätze ist es, Aussatz des Kopfes oder des Bartes." },
      { number: 31, text: "Und wenn der Priester das Mal der Krätze besieht, und siehe, es erscheint nicht tiefer als die <übrige> Haut, und es ist kein schwarzes Haar darin, dann soll der Priester <den, der> das Mal der Krätze <hat, für> sieben Tage einschließen." },
      { number: 32, text: "Und besieht der Priester das Mal am siebten Tag, und siehe, die Krätze hat nicht um sich gegriffen, und es ist kein goldglänzendes Haar darin, und die Krätze erscheint nicht tiefer als die <übrige> Haut," },
      { number: 33, text: "dann soll er sich scheren; aber den Schorf soll er nicht scheren. Und der Priester schließe <den, der> die Krätze <hat,> zum zweiten Mal <für> sieben Tage ein." },
      { number: 34, text: "Und besieht der Priester die Krätze am siebten Tag, und siehe, die Krätze hat in der Haut nicht um sich gegriffen, und sie erscheint nicht tiefer als die <übrige> Haut, dann soll der Priester ihn für rein erklären. Er soll seine Kleider waschen, und er ist rein." },
      { number: 35, text: "Wenn aber nach seiner Reinigung die Krätze in der Haut weiter um sich greift," },
      { number: 36, text: "und der Priester besieht ihn, und siehe, die Krätze hat in der Haut um sich gegriffen, dann soll der Priester nicht nach dem goldglänzenden Haar forschen: unrein ist er." },
      { number: 37, text: "Wenn aber in seinen Augen die Krätze stehen geblieben ist, und es ist schwarzes Haar darin gewachsen, dann ist die Krätze geheilt: rein ist er. Der Priester soll ihn für rein erklären." },
      { number: 38, text: "Und wenn ein Mann oder eine Frau in der Haut ihres Fleisches Flecken bekommt, weiße Flecken," },
      { number: 39, text: "und der Priester besieht sie, und siehe, in der Haut ihres Fleisches sind blasse, weiße Flecken, dann ist es ein <gutartiger> Ausschlag, der in der Haut ausgebrochen ist: rein ist er." },
      { number: 40, text: "Und wenn bei jemandem sein Kopf kahl wird, ist er ein Glatzkopf: rein ist er." },
      { number: 41, text: "Und wenn sein Kopf an seiner Vorderseite kahl wird, ist er stirnglatzig: rein ist er." },
      { number: 42, text: "Und wenn an der kahlen Stelle <hinten> oder an der Stirnglatze ein weiß-rötliches Mal ist, dann ist es Aussatz, der an seiner kahlen Stelle <hinten> oder an seiner Stirnglatze ausgebrochen ist." },
      { number: 43, text: "Und besieht ihn der Priester, und siehe, die Erhöhung des Mals ist weiß-rötlich an seiner kahlen Stelle <hinten> oder an seiner Stirnglatze gleich dem Aussehen des Aussatzes in der Haut des Fleisches," },
      { number: 44, text: "<dann> ist er ein aussätziger Mann: unrein ist er. Der Priester soll ihn für ganz und gar unrein erklären; sein Mal ist an seinem Kopf." },
      { number: 45, text: "Und der Aussätzige, an dem das Mal ist — seine Kleider sollen zerrissen und sein Kopf<haar> soll frei hängen gelassen werden*, und er soll seinen Bart verhüllen* und ausrufen: Unrein, unrein*!", footnotes: ["o. soll verwildern", "℘ Mi 3,7", "℘ Kla 4,15"] },
      { number: 46, text: "All die Tage, die das Mal an ihm ist, soll er unrein sein; unrein ist er: Allein soll er wohnen, außerhalb des Lagers soll seine Wohnung sein*.", footnotes: ["℘ 4Mo 5,2; 2Kö 7,3; 15,5; Lk 17,12"] },
      { number: 47, text: "Und wenn an einem Kleid ein Aussatzmal entsteht, an einem Kleid aus Wolle oder an einem Kleid aus Leinen", heading: "Gesetz vom Aussatz an Kleidern" },
      { number: 48, text: "oder an einem Gewebe oder an Gewirktem aus Leinen oder aus Wolle oder an einem Fell oder an irgendeinem Fellwerk," },
      { number: 49, text: "und das Mal ist grünlich oder rötlich am Kleid oder am Fell oder am Gewebe oder am Gewirkten oder an irgendeinem Gerät aus Fell, <dann> ist es das Mal des Aussatzes. Man soll es den Priester besehen lassen." },
      { number: 50, text: "Und der Priester besehe das Mal und schließe <das, woran> das Mal <ist, für> sieben Tage ein*.", footnotes: ["℘ V. 4"] },
      { number: 51, text: "Und sieht er das Mal am siebten Tag, dass das Mal um sich gegriffen hat am Kleid oder am Gewebe oder am Gewirkten oder am Fell, nach allem, wozu das Fell verarbeitet wird, <dann> ist das Mal ein bösartiger Aussatz: unrein ist es*.", footnotes: ["℘ Kap. 14,44"] },
      { number: 52, text: "Und man soll das Kleid oder das Gewebe oder das Gewirkte aus Wolle oder aus Leinen oder jedes Gerät aus Fell, woran das Mal ist, verbrennen; denn ein bösartiger Aussatz ist es: Mit Feuer soll es verbrannt werden." },
      { number: 53, text: "Und wenn der Priester es besieht, und siehe, das Mal hat nicht um sich gegriffen am Kleid oder am Gewebe oder am Gewirkten oder an irgendeinem Gerät aus Fell," },
      { number: 54, text: "dann soll der Priester gebieten, dass man das wäscht, woran das Mal ist; und er soll es zum zweiten Mal <für> sieben Tage einschließen." },
      { number: 55, text: "Und besieht der Priester das Mal nach dem Waschen, und siehe, das Mal hat sein Aussehen nicht geändert, und das Mal hat nicht um sich gegriffen, <dann> ist es unrein. Mit Feuer sollst du es verbrennen; es ist eine Vertiefung auf seiner kahlen Stelle <hinten> oder auf der kahlen Stelle <vorn>." },
      { number: 56, text: "Und wenn der Priester es besieht, und siehe, das Mal ist blass geworden nach dem Waschen, dann soll er es abreißen vom Kleid oder vom Fell oder vom Gewebe oder vom Gewirkten." },
      { number: 57, text: "Und wenn es sich noch zeigen wird am Kleid oder am Gewebe oder am Gewirkten oder an irgendeinem Gerät aus Fell, <dann> ist es ein ausbrechender <Aussatz>: Mit Feuer sollst du verbrennen, woran das Mal ist." },
      { number: 58, text: "Und das Kleid oder das Gewebe oder das Gewirkte oder irgendein Gerät aus Fell, das du wäschst, so dass das Mal daraus weicht: Es soll zum zweiten Mal gewaschen werden. Dann ist es rein." },
      { number: 59, text: "Das ist das Gesetz <betreffs> des Aussatzmals an einem Kleid aus Wolle oder aus Leinen, oder an einem Gewebe oder an einem Gewirkten oder an irgendeinem Gerät aus Fell, es für rein oder für unrein zu erklären*.", footnotes: ["℘ Kap. 14,57"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Reinigungsopfer und Gebräuche für Aussätzige" },
      { number: 2, text: "Dies soll das Gesetz des Aussätzigen sein am Tag seiner Reinigung*: Er soll zum Priester gebracht werden*,", footnotes: ["d. h. am Tag, an dem er für rein erklärt wird", "℘ Mt 8,4; Mk 1,44"] },
      { number: 3, text: "und der Priester soll nach draußen vor das Lager gehen. Und besieht ihn der Priester, und siehe, das Mal des Aussatzes ist an dem Aussätzigen geheilt," },
      { number: 4, text: "dann soll der Priester gebieten, dass man für den, der zu reinigen ist, zwei lebende, reine Vögel nehme und Zedernholz, Karmesin und Ysop*.", footnotes: ["℘ 4Mo 19,6; Hebr 9,19"] },
      { number: 5, text: "Und der Priester soll gebieten, dass man den einen Vogel über lebendigem Wasser* in ein Tongefäß hinein schlachte.", footnotes: ["d. h. über fließendem, nicht aus einer Zisterne geschöpftem Wasser\n℘ V. 50"] },
      { number: 6, text: "Den lebenden Vogel soll er nehmen, ihn und das Zedernholz, den Karmesin und den Ysop, und dieses und den lebenden Vogel in das Blut des Vogels tauchen, der über dem lebendigen Wasser* geschlachtet worden ist.", footnotes: ["d. h. über fließendem, nicht aus einer Zisterne geschöpftem Wasser\n℘ V. 50"] },
      { number: 7, text: "Und er soll <davon etwas> auf den, der vom Aussatz zu reinigen ist, siebenmal sprengen* und ihn für rein erklären*. Und den lebenden Vogel soll er ins freie Feld fliegen lassen*.", footnotes: ["℘ Kap. 4,6", "o. und ihn <so> reinigen\n℘ 4Mo 19,19", "℘ Kap. 16,22"] },
      { number: 8, text: "Und der zu reinigen ist, soll seine Kleider waschen und all sein Haar scheren und sich im Wasser baden. Dann ist er rein*. Und danach darf er ins Lager kommen, aber er soll sieben Tage außerhalb seines Zeltes bleiben.", footnotes: ["℘ Kap. 13,6"] },
      { number: 9, text: "Und es soll geschehen, am siebten Tag soll er all sein Haar scheren, sein Haupt und seinen Bart und seine Augenbrauen; ja, all sein Haar soll er scheren und seine Kleider waschen und sein Fleisch im Wasser baden: Dann ist er rein*.", footnotes: ["℘ 4Mo 8,7"] },
      { number: 10, text: "Und am achten Tag soll er zwei Schaflämmer ohne Fehler nehmen und ein weibliches Schaflamm, einjährig, ohne Fehler*, drei Zehntel Weizengrieß, mit Öl gemengt*, zum Speisopfer, und ein Log Öl.", footnotes: ["℘ Kap. 1,3.10", "o. angefeuchtet\n℘ Kap. 2,1"] },
      { number: 11, text: "Und der reinigende Priester soll den Mann, der zu reinigen ist, zusammen mit diesen Dingen an den Eingang des Zeltes der Begegnung vor den HERRN stellen." },
      { number: 12, text: "Und der Priester nehme das eine Lamm* und bringe es als Schuldopfer* dar mit dem Log Öl und schwinge sie als Schwingopfer vor dem HERRN*.", footnotes: ["w. den einen jungen Widder. — Im Gegensatz zu V. 10 ist hier ein männliches Tier gemeint.", "℘ Kap. 5,15", "℘ Kap. 8,27"] },
      { number: 13, text: "Und er schlachte das Lamm an der Stelle, wo man das Sündopfer und das Brandopfer schlachtet, an heiliger Stätte*; denn wie das Sündopfer, so gehört das Schuldopfer dem Priester*: hochheilig ist es*.", footnotes: ["℘ Kap. 7,2", "℘ Kap. 2,3.10", "℘ Kap. 21,22"] },
      { number: 14, text: "Und der Priester nehme <etwas> von dem Blut des Schuldopfers, und der Priester tue es auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes*.", footnotes: ["℘ Kap. 8,23.24; 2Mo 29,20"] },
      { number: 15, text: "Und der Priester nehme <etwas> von dem Log Öl und gieße es in seine* linke Hand.", footnotes: ["w. des Priesters"] },
      { number: 16, text: "Und der Priester tauche seinen rechten Finger in das Öl, das in seiner linken Hand ist, und versprenge <etwas> von dem Öl mit seinem Finger siebenmal vor dem HERRN*.", footnotes: ["℘ Kap. 8,11"] },
      { number: 17, text: "Und vom Rest des Öles, das in seiner Hand ist, soll der Priester <etwas> auf das rechte Ohrläppchen dessen tun, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes*, auf das Blut* des Schuldopfers.", footnotes: ["℘ Kap. 8,23.24; 2Mo 29,20", "LXX, die syr. und aram. Üs.: auf die Stelle des Blutes; wie V. 28"] },
      { number: 18, text: "Und das restliche Öl, das in der Hand des Priesters ist, soll er auf den Kopf dessen tun, der zu reinigen ist. Und der Priester soll Sühnung für ihn erwirken vor dem HERRN*.", footnotes: ["℘ Kap. 4,20"] },
      { number: 19, text: "Und der Priester soll das Sündopfer opfern und für den Sühnung erwirken, der von seiner Unreinheit zu reinigen ist. Danach soll er das Brandopfer schlachten." },
      { number: 20, text: "Und der Priester soll das Brandopfer und das Speisopfer auf dem Altar opfern. Und so erwirke der Priester Sühnung für ihn: dann ist er rein." },
      { number: 21, text: "Wenn er aber gering ist und seine Hand es nicht aufbringen* kann*, dann soll er ein Lamm als Schuldopfer nehmen für das Schwingopfer, um Sühnung für ihn zu erwirken, und für das Speisopfer ein Zehntel Weizengrieß, mit Öl gemengt*, und ein Log Öl", footnotes: ["w. erreichen", "℘ Kap. 5,7.11", "o. angefeuchtet"] },
      { number: 22, text: "und zwei Turteltauben oder zwei junge Tauben, die seine Hand aufbringen* kann: eine soll ein Sündopfer und die andere ein Brandopfer sein.", footnotes: ["w. erreichen"] },
      { number: 23, text: "Und er soll sie am achten Tag seiner Reinigung zum Priester bringen an den Eingang des Zeltes der Begegnung vor den HERRN*.", footnotes: ["℘ Kap. 15,14"] },
      { number: 24, text: "Und der Priester nehme das Lamm des Schuldopfers und das Log Öl, und der Priester schwinge sie als Schwingopfer vor dem HERRN." },
      { number: 25, text: "Und er schlachte das Lamm des Schuldopfers! Und der Priester nehme <etwas> von dem Blut des Schuldopfers und tue es auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes*.", footnotes: ["℘ Kap. 8,23.24; 2Mo 29,20"] },
      { number: 26, text: "Und der Priester gieße <etwas> von dem Öl in seine* linke Hand;", footnotes: ["w. des Priesters"] },
      { number: 27, text: "und der Priester sprenge vor dem HERRN siebenmal mit seinem rechten Finger <etwas> von dem Öl, das in seiner linken Hand ist." },
      { number: 28, text: "Und der Priester tue <etwas> von dem Öl, das in seiner Hand ist, auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes*, auf die Stelle des Blutes des Schuldopfers.", footnotes: ["℘ Kap. 8,23.24; 2Mo 29,20"] },
      { number: 29, text: "Und das übrige Öl, das in der Hand des Priesters ist, soll er auf den Kopf dessen tun, der zu reinigen ist, um Sühnung für ihn zu erwirken vor dem HERRN." },
      { number: 30, text: "Und er soll die eine von den Turteltauben oder von den jungen Tauben opfern, von dem, was seine Hand aufbringen* kann —", footnotes: ["w. erreichen"] },
      { number: 31, text: "das, was seine Hand aufbringen* kann: die eine als Sündopfer und die andere als Brandopfer, mit dem Speisopfer. So erwirke der Priester Sühnung vor dem HERRN für den, der zu reinigen ist.", footnotes: ["w. erreichen"] },
      { number: 32, text: "Das ist das Gesetz für den, an dem das Mal des Aussatzes ist, dessen Hand bei seiner Reinigung nicht aufbringen* kann<, was vorgeschrieben ist>.", footnotes: ["w. erreichen"] },
      { number: 33, text: "Und der HERR redete zu Mose und zu Aaron:", heading: "Reinigung vom Aussatz an Häusern" },
      { number: 34, text: "Wenn ihr in das Land Kanaan kommt, das ich euch zum Eigentum gebe*, und ich im Land eures Eigentums ein Aussatzmal an ein Haus setze,", footnotes: ["℘ Kap. 20,24; 1Mo 17,8; 5Mo 32,49"] },
      { number: 35, text: "dann soll der, dem das Haus gehört, kommen und es dem Priester melden und sagen: Es sieht mir aus wie ein Mal am Haus." },
      { number: 36, text: "Und der Priester soll gebieten, dass man das Haus ausräumt, ehe der Priester hineingeht, das Mal zu besehen, damit nicht alles, was im Haus ist, unrein wird. Danach soll der Priester hineingehen, das Haus zu besehen." },
      { number: 37, text: "Und besieht er das Mal, und siehe, das Mal ist an den Wänden des Hauses, grünliche oder rötliche Vertiefungen, und sie erscheinen tiefer als die Wand," },
      { number: 38, text: "dann soll der Priester aus dem Haus hinaus an den Eingang des Hauses gehen und das Haus <für> sieben Tage verschließen*.", footnotes: ["℘ Kap. 13,4.50"] },
      { number: 39, text: "Und der Priester soll am siebten Tag wiederkommen. Und besieht er es, und siehe, das Mal hat an den Wänden des Hauses um sich gegriffen," },
      { number: 40, text: "dann soll der Priester gebieten, dass man die Steine, an denen das Mal ist, herausreißt und sie hinauswirft nach draußen vor die Stadt an einen unreinen Ort." },
      { number: 41, text: "Das Haus aber soll man inwendig ringsum abkratzen und den Lehm, den man abgekratzt hat, hinausschütten nach draußen vor die Stadt an einen unreinen Ort." },
      { number: 42, text: "Und man soll andere Steine nehmen und sie an die Stelle der <herausgerissenen> Steine bringen, und man soll anderen Lehm nehmen und das Haus <damit> verputzen*.", footnotes: ["w. überstreichen"] },
      { number: 43, text: "Wenn aber nach dem Ausreißen der Steine, nach dem Abkratzen des Hauses und nach dem Verputzen* das Mal zurückkehrt und am Haus ausbricht,", footnotes: ["w. Überstrichenwerden"] },
      { number: 44, text: "dann soll der Priester kommen. Und besieht er es, und siehe, das Mal hat am Haus um sich gegriffen, <dann> ist es ein bösartiger Aussatz am Haus: Unrein ist es*.", footnotes: ["℘ Kap. 13,51"] },
      { number: 45, text: "Man soll das Haus niederreißen, seine Steine und sein Holz und allen Lehm des Hauses, und es hinausbringen nach draußen vor die Stadt an einen unreinen Ort." },
      { number: 46, text: "Und wer in das Haus, solange es verschlossen ist, hineingeht, wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25"] },
      { number: 47, text: "Wer in dem Haus schläft, soll seine Kleider waschen, und wer in dem Haus isst, soll seine Kleider waschen." },
      { number: 48, text: "Wenn aber der Priester wieder hineingeht und es besieht, und siehe, das Mal hat nach dem Verputzen* des Hauses nicht um sich gegriffen am Haus, dann soll der Priester das Haus für rein erklären; denn das Mal ist geheilt.", footnotes: ["w. Überstrichenwerden"] },
      { number: 49, text: "Und er soll, um das Haus zu entsündigen, zwei Vögel nehmen und Zedernholz und Karmesin und Ysop;" },
      { number: 50, text: "und er schlachte den einen Vogel über lebendigem Wasser* in ein Tongefäß hinein.", footnotes: ["d. h. über fließendem, nicht aus einer Zisterne geschöpftem Wasser\n℘ V. 4-6"] },
      { number: 51, text: "Und er nehme das Zedernholz und den Ysop und den Karmesin und den lebenden Vogel und tauche sie in das Blut des geschlachteten Vogels und in das lebendige Wasser und besprenge <damit> das Haus siebenmal." },
      { number: 52, text: "Und er entsündige das Haus mit dem Blut des Vogels, mit dem lebendigen Wasser und mit dem lebenden Vogel, mit dem Zedernholz, mit dem Ysop und mit dem Karmesin." },
      { number: 53, text: "Den lebenden Vogel aber soll er nach draußen vor die Stadt ins freie Feld fliegen lassen. So erwirke er Sühnung für das Haus: Dann wird es rein sein." },
      { number: 54, text: "Das ist das Gesetz für das ganze Mal des Aussatzes und für die Krätze*", footnotes: ["℘ Kap. 13,3-46"] },
      { number: 55, text: "und für den Aussatz des Kleides* und des Hauses*", footnotes: ["℘ Kap. 13,47-58", "℘ V. 34-53"] },
      { number: 56, text: "und für die Erhöhung und für den Schorf* und für den Fleck*,", footnotes: ["℘ Kap. 13,3-46", "℘ Kap. 13,3-46"] },
      { number: 57, text: "um zu belehren, wann für unrein und wann für rein zu erklären ist*: Das ist das Gesetz des Aussatzes.", footnotes: ["℘ Kap. 10,10; 13,59"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und zu Aaron:", heading: "Gesetz über die Unreinheit bei Männern und Frauen" },
      { number: 2, text: "Redet zu den Söhnen Israel und sagt zu ihnen: Wenn irgendein Mann an seinem Fleisch an Fluss leidet*, ist er unrein durch seinen Schleimfluss*.", footnotes: ["w. in seinem Fleisch fließt", "℘ Kap. 5,3; 22,4; 4Mo 5,2; 2Sam 3,29"] },
      { number: 3, text: "Und dies wird seine Unreinheit bei seinem Schleimfluss sein: Lässt sein Fleisch seinen Schleimfluss triefen oder hält sein Fleisch seinen Schleimfluss zurück, ist das seine Unreinheit." },
      { number: 4, text: "Jedes Lager, worauf der an Ausfluss Leidende liegt, wird unrein sein, und jedes Gerät, worauf er sitzt, wird unrein sein." },
      { number: 5, text: "Und wer sein Lager berührt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 6, text: "Und wer sich auf das Gerät setzt, worauf der an Ausfluss Leidende zu sitzen pflegt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 7, text: "Und wer das Fleisch des an Ausfluss Leidenden berührt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 8, text: "Und wenn der an Ausfluss Leidende auf einen Reinen speit, dann soll dieser seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 9, text: "Jeder Sattelsitz, auf dem der an Ausfluss Leidende reitet, wird unrein sein." },
      { number: 10, text: "Und jeder, der irgendetwas berührt, was er unter sich hat, wird bis zum Abend unrein sein. Und wer es trägt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 11, text: "Und jeder, den der an Ausfluss Leidende berührt — er hat aber seine Hände nicht im Wasser abgespült —, der soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 12, text: "Und das Tongefäß, das der an Ausfluss Leidende berührt, soll zerbrochen werden; jedes hölzerne Gefäß aber soll im Wasser gespült werden*.", footnotes: ["℘ Kap. 6,21"] },
      { number: 13, text: "Und wenn der an Ausfluss Leidende von seinem Schleimfluss rein wird, dann soll er für seine Reinigung sieben Tage für sich zählen. Und er soll seine Kleider waschen und sein Fleisch in lebendigem Wasser baden, dann wird er rein sein." },
      { number: 14, text: "Und am achten Tag soll er sich zwei Turteltauben oder zwei junge Tauben nehmen und an den Eingang des Zeltes der Begegnung vor den HERRN kommen und sie dem Priester geben*.", footnotes: ["℘ Kap. 14,22.23"] },
      { number: 15, text: "Und der Priester soll sie opfern, eine als Sündopfer und die andere als Brandopfer. So erwirke der Priester vor dem HERRN Sühnung für ihn wegen seines Schleimflusses*.", footnotes: ["℘ Kap. 12,7.8"] },
      { number: 16, text: "Und wenn einem Mann der Samenerguss entgeht, dann soll er sein ganzes Fleisch im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 22,4; 5Mo 23,11.12"] },
      { number: 17, text: "Und jedes Kleid und jedes Fell, worauf der Samenerguss kommt, soll im Wasser gewaschen werden, und es wird bis zum Abend unrein sein." },
      { number: 18, text: "Und eine Frau, bei der ein Mann liegt mit Samenerguss — sie sollen sich im Wasser baden und werden bis zum Abend unrein sein*.", footnotes: ["℘ 2Mo 19,15; Hebr 9,10"] },
      { number: 19, text: "Und wenn eine Frau an Fluss leidet* <und> ihr Fluss an ihrem Fleisch Blut ist, soll sie sieben Tage in ihrer Absonderung* sein*. Und jeder, der sie anrührt, wird bis zum Abend unrein sein.", footnotes: ["w. eine an <Blut>fluss Leidende ist", "o. Ausscheidung; d. i. die Monatsregel", "℘ Kap. 12,2; Hes 36,17"] },
      { number: 20, text: "Alles, worauf sie in ihrer Absonderung* liegt, wird unrein sein, und alles, worauf sie sitzt, wird unrein sein.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel"] },
      { number: 21, text: "Und jeder, der ihr Lager berührt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 22, text: "Und jeder, der irgendein Gerät berührt, worauf sie zu sitzen pflegt, soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 23, text: "Und wenn etwas auf dem Lager oder auf dem Gerät ist, worauf sie zu sitzen pflegt — wenn er es berührt, wird er bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 24, text: "Und wenn etwa ein Mann neben ihr liegt, und ihre Absonderung* kommt auf ihn, dann wird er sieben Tage unrein sein. Jedes Lager, worauf er liegt, wird unrein sein.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel"] },
      { number: 25, text: "Und wenn eine Frau ihren Blutfluss viele Tage außer der Zeit ihrer Absonderung* hat* oder wenn sie den Fluss über ihre Absonderung hinaus hat*, soll sie all die Tage des Flusses ihrer Unreinheit sein wie in den Tagen ihrer Absonderung: Unrein ist sie.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel", "℘ Mt 9,20; Mk 5,25", "℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 26, text: "Jedes Lager, worauf sie alle Tage ihres Flusses liegt, soll ihr sein wie das Lager ihrer Absonderung*, und jedes Gerät, worauf sie sitzt, wird unrein sein nach der Unreinheit ihrer Absonderung.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel"] },
      { number: 27, text: "Und jeder, der es berührt, wird unrein sein, und er soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*.", footnotes: ["℘ Kap. 11,24.25; 4Mo 19,22"] },
      { number: 28, text: "Und wenn sie rein geworden ist von ihrem Fluss, dann soll sie sich sieben Tage zählen, danach wird sie rein sein." },
      { number: 29, text: "Und am achten Tag soll sie sich zwei Turteltauben oder zwei junge Tauben nehmen und sie an den Eingang des Zeltes der Begegnung zum Priester bringen." },
      { number: 30, text: "Und der Priester soll die eine als Sündopfer und die andere als Brandopfer opfern. So erwirke der Priester Sühnung für sie vor dem HERRN wegen des Flusses ihrer Unreinheit." },
      { number: 31, text: "Und ihr sollt die Söhne Israel warnen vor* ihrer Unreinheit, damit sie nicht in ihrer* Unreinheit sterben, indem sie meine Wohnung, die in ihrer Mitte ist, unrein machen*.", footnotes: ["so mit SamPent und der syr. Üs.; ähnlich LXX und Vulg. Mas. T.: ihr sollt . . . zurückhalten von", "o. durch ihre", "℘ 4Mo 5,3; 19,13.20; 1Kor 5,13"] },
      { number: 32, text: "Das ist das Gesetz <betreffs> dessen, der an Ausfluss leidet, und dessen, dem der Samenerguss entgeht, so dass er durch ihn unrein wird," },
      { number: 33, text: "und <betreffs der,> die krank* ist in ihrer Absonderung*, und dessen, der seinen Schleimfluss hat*, es sei Mann oder Frau, und für den Mann, der neben einer Unreinen liegt.", footnotes: ["d. h. menstruierend", "o. Ausscheidung; d. i. die Monatsregel", "w. der in seinem Fluss fließt"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und der HERR redete zu Mose nach dem Tod der beiden Söhne Aarons, als sie vor den HERRN traten* und starben*.", heading: "Der Versöhnungstag", footnotes: ["w. dem HERRN nahten", "℘ Kap. 10,1.2"] },
      { number: 2, text: "Und der HERR sprach zu Mose: Rede zu deinem Bruder Aaron, dass er nicht zu jeder Zeit* in das Heiligtum hineingeht innerhalb des Vorhangs*, vor die Deckplatte*, die auf der Lade ist, damit er nicht stirbt. Denn ich erscheine in der Wolke über der Deckplatte*.", footnotes: ["℘ V. 34", "w. des Absperrenden; d. h. hinter den Vorhang, der das Heilige vom Allerheiligsten trennt\n℘ 4Mo 18,7", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet.\n℘ 2Mo 25,22", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet."] },
      { number: 3, text: "Auf diese Weise soll Aaron in das Heiligtum hineingehen, mit einem Jungstier* für das Sündopfer und einem Widder für das Brandopfer*.", footnotes: ["℘ Kap. 4,3.13.14", "℘ Kap. 1,10; 9,2"] },
      { number: 4, text: "Er soll einen heiligen Leibrock aus Leinen anziehen, und leinene Beinkleider sollen auf seinem Fleisch* sein, und mit einem leinenen Gürtel soll er sich umgürten und einen Kopfbund aus Leinen sich umbinden; das sind heilige Kleider*. Er soll sein Fleisch im Wasser baden* und sie <dann> anziehen.", footnotes: ["vgl. 2Mo 28,42", "℘ Kap. 6,3; Hes 44,17", "℘ Kap. 8,6"] },
      { number: 5, text: "Und von der Gemeinde der Söhne Israel soll er zwei Ziegenböcke nehmen für das Sündopfer* und einen Widder für das Brandopfer*.", footnotes: ["℘ Kap. 1,10; 9,2", "℘ Kap. 1,10; 9,2"] },
      { number: 6, text: "Und Aaron soll den Stier des Sündopfers, der für ihn ist, herbeibringen und Sühnung erwirken für sich und für sein Haus*.", footnotes: ["℘ Kap. 9,7; Hebr 5,3"] },
      { number: 7, text: "Und er soll die zwei Ziegenböcke nehmen und sie an den Eingang des Zeltes der Begegnung vor den HERRN stellen." },
      { number: 8, text: "Und Aaron soll Lose werfen über die zwei Ziegenböcke, ein Los für den HERRN und ein Los für Asasel*.", footnotes: ["d. h. vielleicht: Wegschaffung, o. der wegschafft, o. der weggeschafft wird, o. der davongeht; nach anderen: Gott ist mächtig\n℘ Spr 16,33"] },
      { number: 9, text: "Und Aaron soll den Ziegenbock herzubringen, auf den das Los für den HERRN gefallen ist, und ihn als Sündopfer opfern." },
      { number: 10, text: "Und der Ziegenbock, auf den das Los für Asasel* gefallen ist, soll lebendig vor den HERRN gestellt werden, um für ihn Sühnung zu erwirken, um ihn für Asasel* in die Wüste fortzuschicken.", footnotes: ["d. h. vielleicht: Wegschaffung, o. der wegschafft, o. der weggeschafft wird, o. der davongeht; nach anderen: Gott ist mächtig", "d. h. vielleicht: Wegschaffung, o. der wegschafft, o. der weggeschafft wird, o. der davongeht; nach anderen: Gott ist mächtig"] },
      { number: 11, text: "Und Aaron bringe den Stier des Sündopfers, der für ihn ist, herbei und tue Sühnung für sich und für sein Haus und schlachte den Stier des Sündopfers, der für ihn ist*.", footnotes: ["℘ Kap. 9,7; Hebr 5,3"] },
      { number: 12, text: "Und er nehme eine Pfanne voll Feuerkohlen von dem Altar* vor* dem HERRN und seine beiden Hände voll von wohlriechendem, klein gestoßenem Räucherwerk* und bringe es <in den Raum> innerhalb des Vorhangs*.", footnotes: ["℘ Offb 8,5", "w. von vor", "℘ 2Mo 30,34.35", "w. des Absperrenden; d. h. hinter den Vorhang, der das Heilige vom Allerheiligsten trennt\n℘ Hebr 6,19"] },
      { number: 13, text: "Und er lege das Räucherwerk auf das Feuer vor den HERRN, damit die Wolke des Räucherwerks die Deckplatte*, die auf dem Zeugnis* ist*, bedeckt und er nicht stirbt.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet.", "o. Mahnzeichen; o. Bezeugung", "℘ 2Mo 25,21; Hebr 9,4.5"] },
      { number: 14, text: "Und er nehme <etwas> von dem Blut des Stiers und sprenge <es> mit seinem Finger* auf die Vorderseite* der Deckplatte* nach Osten zu, und vor die Deckplatte* soll er siebenmal <etwas> von dem Blut mit seinem Finger sprengen.", footnotes: ["℘ Kap. 4,5.6; Röm 3,25; Hebr 9,12", "o. Oberfläche", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet.", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet."] },
      { number: 15, text: "Und er schlachte den Ziegenbock des Sündopfers, der für das Volk ist, und bringe sein Blut <in den Raum> innerhalb des Vorhangs* und tue mit seinem Blut ebenso, wie er mit dem Blut des Stiers getan hat, und sprenge es auf die Deckplatte* und vor die Deckplatte*.", footnotes: ["d. h. ins Allerheiligste", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet.", "o. Sühneplatte. — Das hebr. Wort ist von einem Verb abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, vergeben« bedeutet.\n℘ Kap. 4,5.6; Röm 3,25; Hebr 9,12"] },
      { number: 16, text: "Und er erwirke Sühnung* für das Heiligtum* wegen der Unreinheiten der Söhne Israel und wegen ihrer Vergehen, nach allen ihren Sünden. Und ebenso soll er für das Zelt der Begegnung tun, das sich bei ihnen befindet* mitten in ihren Unreinheiten.", footnotes: ["℘ 4Mo 17,11; 28,15.30", "℘ Hes 45,18", "w. das bei ihnen wohnt"] },
      { number: 17, text: "Und kein Mensch soll in dem Zelt der Begegnung sein, wenn er hineingeht, um Sühnung im Heiligtum zu erwirken, bis er herauskommt. So erwirke er Sühnung für sich und für sein Haus und für die ganze Versammlung Israels." },
      { number: 18, text: "Und er soll hinausgehen zu dem Altar, der vor dem HERRN ist, und für ihn Sühnung erwirken*. Und er nehme <etwas> von dem Blut des Stiers und von dem Blut des Ziegenbocks und tue es ringsherum an die Hörner des Altars.", footnotes: ["℘ 2Mo 30,10"] },
      { number: 19, text: "Und er sprenge <etwas> von dem Blut siebenmal mit seinem Finger an ihn und reinige ihn und heilige ihn von den Unreinheiten der Söhne Israel*.", footnotes: ["℘ 1Chr 6,34; Hebr 9,22"] },
      { number: 20, text: "Und hat er die Sühnung des Heiligtums und des Zeltes der Begegnung und des Altars vollendet, dann soll er den lebenden Ziegenbock herbeibringen." },
      { number: 21, text: "Und Aaron lege* seine beiden Hände auf den Kopf des lebenden Ziegenbocks und bekenne auf ihn alle Schuld der Söhne Israel und all ihre Vergehen nach allen ihren Sünden*. Und er lege sie auf den Kopf des Ziegenbocks und schicke ihn durch einen bereitstehenden Mann fort in die Wüste,", footnotes: ["w. stütze, o. stemme", "℘ Kap. 5,5"] },
      { number: 22, text: "damit der Ziegenbock all ihre Schuld auf sich trägt in ein ödes Land; und er schicke den Ziegenbock in die Wüste*.", footnotes: ["℘ Kap. 14,7"] },
      { number: 23, text: "Und Aaron soll in das Zelt der Begegnung hineingehen und die Kleider aus Leinen ausziehen, die er anzog, als er in das Heiligtum hineinging, und soll sie dort niederlegen." },
      { number: 24, text: "Und er soll an heiliger Stätte sein Fleisch im Wasser baden und seine Kleider anziehen*. Und er soll herauskommen und sein Brandopfer und das Brandopfer des Volkes opfern und <so> für sich und für das Volk Sühnung erwirken*.", footnotes: ["℘ Hes 42,14", "℘ Kap. 9,7"] },
      { number: 25, text: "Und das Fett des Sündopfers soll er auf dem Altar in Rauch aufgehen* lassen.", footnotes: ["℘ Kap. 3,3.4"] },
      { number: 26, text: "Und wer den Ziegenbock für Asasel* fortschickt, soll seine Kleider waschen und sein Fleisch im Wasser baden. Danach darf er ins Lager kommen*.", footnotes: ["d. h. vielleicht: Wegschaffung, o. der wegschafft, o. der weggeschafft wird, o. der davongeht; nach anderen: Gott ist mächtig", "℘ Kap. 11,24.25"] },
      { number: 27, text: "Und den Stier des Sündopfers und den Ziegenbock des Sündopfers, deren Blut hineingebracht worden ist, um im Heiligtum Sühnung zu erwirken, soll man hinausbringen nach draußen vor das Lager und ihre Häute und ihr Fleisch und ihren Mageninhalt* mit Feuer verbrennen*.", footnotes: ["o. Darminhalt", "℘ Kap. 4,11.12.21"] },
      { number: 28, text: "Und der sie verbrennt, soll seine Kleider waschen und sein Fleisch im Wasser baden; danach darf er ins Lager kommen*.", footnotes: ["℘ Kap. 11,24.25"] },
      { number: 29, text: "Und dies soll euch zu einer ewigen Ordnung sein: Im siebten Monat, am Zehnten des Monats, sollt ihr euch selbst demütigen* und keinerlei Arbeit tun, der Einheimische und der Fremde, der in eurer Mitte als Fremder wohnt*.", footnotes: ["w. eure Seelen <durch Fasten> erniedrigen", "℘ Kap. 23,27; 4Mo 29,7"] },
      { number: 30, text: "Denn an diesem Tag wird man für euch Sühnung erwirken, um euch zu reinigen; von all euren Sünden werdet ihr rein sein vor dem HERRN*.", footnotes: ["℘ Jer 33,8; Hes 36,25; Tit 2,14"] },
      { number: 31, text: "Ein Sabbat völliger Ruhe* soll er euch sein, und ihr sollt euch selbst demütigen* — eine ewige Ordnung.", footnotes: ["w. Sabbat der Sabbatfeier; vgl. Kap. 23,24.32.39; 25,4", "℘ Kap. 23,32; Jes 58,3"] },
      { number: 32, text: "Und der Priester soll Sühnung erwirken, den man salben wird und dem man die Hand füllt*, damit er den Priesterdienst an seines Vaters Statt ausübt. Er soll die Kleider aus Leinen anziehen, die heiligen Kleider*,", footnotes: ["d. h. den man zum Priesterdienst weiht; s. Anm. zu Kap. 8,28 und zu 2Mo 28,41", "℘ 2Mo 29,29.30"] },
      { number: 33, text: "und er soll Sühnung erwirken für das heilige Heiligtum und für das Zelt der Begegnung. Und für den Altar soll er Sühnung erwirken*, und für die Priester und für das ganze Volk der Gemeinde soll er Sühnung erwirken.", footnotes: ["℘ Kap. 23,28"] },
      { number: 34, text: "Das soll euch zu einer ewigen Ordnung sein*, für die Söhne Israel einmal im Jahr* Sühnung zu tun wegen all ihrer Sünden. Und er tat <es>, ganz wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 27,21", "℘ V. 2; Hebr 10,3", "℘ Kap. 24,23; 2Mo 39,43"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Ort zum Opfern — Verbot des Essens von Blut und Aas" },
      { number: 2, text: "Rede zu Aaron und zu seinen Söhnen und zu allen Söhnen Israel und sage zu ihnen: Dies ist die Sache, die* der HERR geboten hat:", footnotes: ["o. das Wort, das"] },
      { number: 3, text: "Jedermann aus dem Haus Israel, der einen Stier oder ein Schaf oder eine Ziege im Lager schlachtet oder der außerhalb des Lagers schlachtet*", footnotes: ["℘ 5Mo 12,13.14"] },
      { number: 4, text: "und es nicht an den Eingang des Zeltes der Begegnung gebracht hat, um <es> dem HERRN als Opfergabe darzubringen vor der Wohnung des HERRN*, diesem Mann soll <es> als Blut* zugerechnet werden*: Blut hat er vergossen; und dieser Mann soll aus der Mitte seines Volkes ausgerottet werden*.", footnotes: ["℘ Kap. 3,2; 5Mo 12,5.11", "d. h. als Blutschuld", "℘ 5Mo 21,8", "℘ 2Mo 30,33.38"] },
      { number: 5, text: "<Dies wird angeordnet,> damit die Söhne Israel ihre Schlachtopfer hineinbringen, die sie jetzt auf freiem Feld schlachten*, und zwar sie hineinbringen für den HERRN an den Eingang des Zeltes der Begegnung zum Priester und sie als Heilsopfer* dem HERRN schlachten*.", footnotes: ["d. h. zum Opfer schlachten\n℘ 1Kö 3,2; Hes 20,28", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 3,1"] },
      { number: 6, text: "Und der Priester soll das Blut an den Altar des HERRN vor dem Eingang des Zeltes der Begegnung sprengen und das Fett in Rauch aufgehen lassen als wohlgefälligen Geruch* für den HERRN*.", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung", "℘ Hes 44,15"] },
      { number: 7, text: "Und sie sollen nicht mehr ihre Schlachtopfer den Bocksdämonen* schlachten*, denen sie nachhuren*. Das soll ihnen eine ewige Ordnung sein für ihre Generationen.*", footnotes: ["w. Haarigen", "℘ 5Mo 32,17; 2Chr 11,15; 1Kor 10,20", "℘ Kap. 20,5; 2Mo 22,19; Ps 106,37", "℘ 2Mo 27,21"] },
      { number: 8, text: "Und du sollst zu ihnen sagen: Jedermann aus dem Haus Israel und von den Fremden, die in ihrer Mitte als Fremde wohnen, der ein Brandopfer oder Schlachtopfer opfert" },
      { number: 9, text: "und es nicht an den Eingang des Zeltes der Begegnung bringt, um es dem HERRN zu opfern, dieser Mann soll aus seinen Völkern* ausgerottet werden*.", footnotes: ["d. h. aus seiner Volksgemeinschaft", "℘ 2Mo 30,33.38"] },
      { number: 10, text: "Und jedermann aus dem Haus Israel und von den Fremden, die in ihrer Mitte als Fremde wohnen, der irgendwelches Blut isst* — gegen die Seele*, die das Blut isst, werde ich mein Angesicht richten* und sie aus der Mitte ihres Volkes ausrotten*.", footnotes: ["℘ Kap. 3,17", "d. h. die Person; o. das Leben. — Für »Seele«, »Leben«, »Person« steht im Hebr. dasselbe Wort.", "℘ Kap. 26,17", "℘ 2Mo 30,33.38"] },
      { number: 11, text: "Denn die Seele* des Fleisches ist im Blut*, und ich selbst habe es euch auf den Altar gegeben*, Sühnung für eure Seelen zu erwirken. Denn das Blut ist es, das Sühnung tut durch die Seele* <in ihm>*.", footnotes: ["d. h. die Person; o. das Leben. — Für »Seele«, »Leben«, »Person« steht im Hebr. dasselbe Wort.", "℘ 5Mo 12,23", "o. <zum Gebrauch> auf dem Altar gegeben", "d. h. kraft des ihm innewohnenden Lebens", "℘ Kap. 4,25.26; Hebr 9,22"] },
      { number: 12, text: "Darum habe ich zu den Söhnen Israel gesagt: Keine Seele* von euch soll Blut essen; auch der Fremde, der in eurer Mitte als Fremder wohnt, soll nicht Blut essen.", footnotes: ["d. h. die Person; o. das Leben. — Für »Seele«, »Leben«, »Person« steht im Hebr. dasselbe Wort."] },
      { number: 13, text: "Und jedermann von den Söhnen Israel und von den Fremden, die in eurer Mitte als Fremde wohnen, der ein Wild oder einen Vogel erjagt*, die gegessen werden dürfen, soll ihr Blut ausfließen lassen und es mit Erde bedecken*.", footnotes: ["w. der ein Wild erjagt, Vierfüßiges oder Vogel", "℘ Hes 24,7"] },
      { number: 14, text: "Denn <was> die Seele* alles Fleisches <betrifft>; sein Blut, das ist seine Seele* — und ich habe zu den Söhnen Israel gesagt: Das Blut irgendwelches Fleisches sollt ihr nicht essen*, denn die Seele* alles Fleisches ist sein Blut; jeder, der es isst, soll ausgerottet werden*. —", footnotes: ["d. h. die Person; o. das Leben. — Für »Seele«, »Leben«, »Person« steht im Hebr. dasselbe Wort.", "w. sein Blut — in seiner Seele ist es", "℘ Kap. 3,17", "w. sein Blut — in seiner Seele ist es", "℘ 2Mo 30,33.38"] },
      { number: 15, text: "Jeder, der ein Aas* oder Zerrissenes isst*, er sei Einheimischer oder Fremder, der soll seine Kleider waschen und sich im Wasser baden, und er wird bis zum Abend unrein sein*; dann wird er rein sein.", footnotes: ["w. Die Seele (o. Person), die irgendein Aas", "℘ 2Mo 22,30", "℘ Kap. 11,25"] },
      { number: 16, text: "Und wenn er sie nicht wäscht und sein Fleisch nicht badet, so wird er seine Schuld tragen*.", footnotes: ["℘ 4Mo 19,20"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Verordnungen für Ehe und Keuschheit" },
      { number: 2, text: "Rede zu den Söhnen Israel und sage zu ihnen: Ich bin der HERR, euer Gott*.", footnotes: ["℘ V. 30; Kap. 11,44; Hes 20,5.7"] },
      { number: 3, text: "Nach der Weise des Landes Ägypten, in dem ihr gewohnt habt, sollt ihr nicht tun; und nach der Weise des Landes Kanaan, wohin ich euch bringe, sollt ihr nicht tun; und in ihren Ordnungen sollt ihr nicht leben*.", footnotes: ["w. gehen\n℘ Kap. 20,23; 2Mo 23,24; 5Mo 12,30; 29,17; Jer 10,2.3; Eph 4,17"] },
      { number: 4, text: "Meine Rechtsbestimmungen sollt ihr tun, und meine Ordnungen sollt ihr halten, um in ihnen zu leben*. Ich bin der HERR, euer Gott.", footnotes: ["w. gehen\n℘ Kap. 19,19; Hes 20,19"] },
      { number: 5, text: "Und meine Ordnungen und meine Rechtsbestimmungen sollt ihr halten. Durch sie wird der Mensch, der sie tut, Leben haben*. Ich bin der HERR.", footnotes: ["℘ 5Mo 4,1; 30,6.20; Neh 9,29; Hes 20,11; Mt 19,17; Röm 10,5; Gal 3,12"] },
      { number: 6, text: "*Niemand von euch soll sich irgendeinem seiner Blutsverwandten* nähern, um die Blöße aufzudecken. Ich bin der HERR.", footnotes: ["℘ V. 6-30: Kap. 20,11-23", "w. dem Leib seines Fleisches"] },
      { number: 7, text: "Die Blöße deines Vaters* und die Blöße deiner Mutter sollst du nicht aufdecken; sie ist deine Mutter, du sollst ihre Blöße nicht aufdecken.", footnotes: ["℘ 1Mo 19,32; Hes 22,10"] },
      { number: 8, text: "Die Blöße der Frau deines Vaters sollst du nicht aufdecken; es ist die Blöße deines Vaters*.", footnotes: ["℘ 1Mo 35,22; 5Mo 23,1; 1Kor 5,1"] },
      { number: 9, text: "Die Blöße deiner Schwester, der Tochter deines Vaters oder der Tochter deiner Mutter, im Haus geboren oder draußen geboren — ihre Blöße sollst du nicht aufdecken*.", footnotes: ["℘ 5Mo 27,22; 2Sam 13,12"] },
      { number: 10, text: "Die Blöße der Tochter deines Sohnes oder der Tochter deiner Tochter — ihre Blöße sollst du nicht aufdecken, denn es ist deine Blöße." },
      { number: 11, text: "Die Blöße der Tochter der Frau deines Vaters, von deinem Vater gezeugt — sie ist deine Schwester, ihre Blöße sollst du nicht aufdecken." },
      { number: 12, text: "Die Blöße der Schwester deines Vaters sollst du nicht aufdecken; sie ist die Blutsverwandte* deines Vaters.", footnotes: ["w. sie ist der Leib"] },
      { number: 13, text: "Die Blöße der Schwester deiner Mutter sollst du nicht aufdecken, denn sie ist die Blutsverwandte* deiner Mutter.", footnotes: ["w. sie ist der Leib"] },
      { number: 14, text: "Die Blöße des Bruders deines Vaters sollst du nicht aufdecken; seiner Frau sollst du dich nicht nähern, sie ist deine Tante." },
      { number: 15, text: "Die Blöße deiner Schwiegertochter* sollst du nicht aufdecken; sie ist die Frau deines Sohnes, ihre Blöße sollst du nicht aufdecken.", footnotes: ["℘ 1Mo 38,18; Hes 22,11"] },
      { number: 16, text: "Die Blöße der Frau deines Bruders sollst du nicht aufdecken*; es ist die Blöße deines Bruders.", footnotes: ["℘ Mt 14,3.4"] },
      { number: 17, text: "Die Blöße einer Frau und ihrer Tochter sollst du nicht aufdecken; die Tochter ihres Sohnes und die Tochter ihrer Tochter sollst du nicht nehmen, um ihre Blöße aufzudecken; sie sind deine Blutsverwandten*: Es ist eine Schandtat*.", footnotes: ["so mit LXX. Die Bedeutung des hebr. Wortes ist unbekannt.", "℘ 5Mo 27,23"] },
      { number: 18, text: "Und du sollst nicht eine Frau zu ihrer Schwester nehmen, <sie> eifersüchtig zu machen*, indem du ihre Blöße neben ihr aufdeckst bei ihrem Leben*. —", footnotes: ["o. als Nebenfrau nehmen", "d. h. so lange sie lebt"] },
      { number: 19, text: "Und einer Frau in der Absonderung* ihrer Unreinheit sollst du nicht nahen, um ihre Blöße aufzudecken.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel"] },
      { number: 20, text: "Und bei der Frau deines Nächsten sollst du nicht zur Begattung liegen, dass du durch sie unrein wirst*. —", footnotes: ["℘ Spr 6,29; Hes 18,6; Hebr 13,4"] },
      { number: 21, text: "Und von deinen Nachkommen sollst du nicht <einen> hingeben, um sie dem Moloch durch <das Feuer> gehen zu lassen*. Und du sollst den Namen des HERRN, deines Gottes, nicht entweihen*. Ich bin der HERR. —", footnotes: ["d. h. um sie dem Moloch zu opfern. Moloch war ein ammonitischer Götze, dem Kinder geopfert wurden (vgl. 2Kö 23,10).\n℘ 5Mo 12,31; 2Kö 16,3; Ps 106,37; Jer 7,31", "℘ Kap. 20,3; 21,6; 22,2; 24,15; Am 2,7"] },
      { number: 22, text: "Und bei einem Mann sollst du nicht liegen, wie man bei einer Frau liegt: Ein Gräuel ist es*.", footnotes: ["℘ 1Mo 19,5"] },
      { number: 23, text: "Und bei keinem Vieh sollst du liegen, so dass du dich an ihm unrein machst. Und eine Frau soll sich nicht vor ein Vieh hinstellen, damit es sie begattet: Es ist eine schändliche Befleckung*.", footnotes: ["℘ 2Mo 22,18"] },
      { number: 24, text: "Macht euch nicht unrein durch all dieses! Denn durch all dieses haben die Nationen sich unrein gemacht, die ich vor euch vertreibe*.", footnotes: ["℘ 5Mo 9,4.5; 2Chr 33,2"] },
      { number: 25, text: "Und das Land wurde unrein gemacht*, und ich suchte seine Schuld an ihm heim*, und das Land spie seine Bewohner aus.", footnotes: ["℘ 4Mo 35,34; Esr 9,11; Ps 106,38; Jer 2,7; Hes 36,17", "℘ Jer 5,9.29"] },
      { number: 26, text: "Ihr aber, ihr sollt meine Ordnungen und meine Rechtsbestimmungen halten, und ihr sollt nichts tun von all diesen Gräueln, der Einheimische und der Fremde, der in eurer Mitte als Fremder wohnt —" },
      { number: 27, text: "denn all diese Gräuel haben die Menschen des Landes getan, die vor euch <da> waren, und das Land ist unrein gemacht worden —," },
      { number: 28, text: "damit das Land euch nicht ausspeit*, wenn ihr es unrein macht, ebenso wie es die Nation ausgespien hat, die vor euch <da> war;", footnotes: ["o. so wird euch das Land nicht ausspeien"] },
      { number: 29, text: "denn jeder, der etwas von all diesen Gräueln tut — die Personen*, die es tun, sollen ausgerottet werden aus der Mitte ihres Volkes*.", footnotes: ["o. Seelen", "℘ 2Mo 30,33.38; Mal 2,12"] },
      { number: 30, text: "Und ihr sollt meine Vorschriften halten*, damit ihr keine der gräulichen Bräuche* übt, die vor euch geübt worden sind*. Ihr sollt euch nicht durch sie unrein machen. Ich bin der HERR, euer Gott*.", footnotes: ["o. für meinen Dienst sorgen", "w. Ordnungen", "℘ 5Mo 12,30.31; Ri 20,6; 1Kö 14,24; 21,26; Esr 9,1", "℘ V. 2"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Vom Umgang mit Gott und dem Nächsten" },
      { number: 2, text: "Rede zu der ganzen Gemeinde der Söhne Israel und sage zu ihnen: Ihr sollt heilig sein; denn ich, der HERR, euer Gott, bin heilig*.", footnotes: ["℘ Kap. 11,44; 2Mo 19,6"] },
      { number: 3, text: "Ihr sollt jeder seine Mutter und seinen Vater fürchten*; und meine Sabbate sollt ihr halten*. Ich bin der HERR, euer Gott*. —", footnotes: ["℘ 2Mo 20,12; Mal 1,6; Hebr 12,9", "℘ V. 30; 2Mo 20,8-11; Neh 9,14; Jes 58,13", "℘ V. 25.34; Kap. 11,44"] },
      { number: 4, text: "Ihr sollt euch nicht zu den Götzen* wenden*, und gegossene Götter sollt ihr euch nicht machen*. Ich bin der HERR, euer Gott*.", footnotes: ["w. den Nichtigen", "℘ Kap. 26,1; 2Mo 34,17; 5Mo 7,25; 1Kö 14,9; 2Chr 28,2; 1Kor 10,14", "℘ 2Mo 20,4; 5Mo 4,16.23.25", "℘ V. 25.34; Kap. 11,44"] },
      { number: 5, text: "Und wenn ihr ein Heilsopfer* dem HERRN opfert, opfert es <so, dass es> euch zum Wohlgefallen <vor Gott dient>*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 3,6"] },
      { number: 6, text: "An dem Tag, an dem ihr es opfert, und am nächsten Tag soll es gegessen werden. Was aber bis zum dritten Tag übrig bleibt, soll mit Feuer verbrannt werden*.", footnotes: ["℘ Kap. 7,17; 2Mo 12,10"] },
      { number: 7, text: "Und wenn es irgend am dritten Tag gegessen wird, ist es Unreines*; es* wird nicht als wohlgefällig betrachtet werden.", footnotes: ["d. h. kultisch unrein gewordenes Opferfleisch", "d. i. das Opfer"] },
      { number: 8, text: "Wer es isst, wird seine Schuld tragen, denn das Heilige des HERRN hat er entweiht; und diese Person* soll ausgerottet werden aus ihren Völkern*.", footnotes: ["o. Seele", "d. h. aus ihrer Volksgemeinschaft\n℘ 2Mo 30,33.38"] },
      { number: 9, text: "Und wenn ihr die Ernte eures Landes erntet, darfst du den Rand deines Feldes nicht vollständig abernten und darfst keine Nachlese deiner Ernte halten*.", footnotes: ["℘ Kap. 23,22; 5Mo 24,19; Rt 2,15"] },
      { number: 10, text: "Und in deinem Weinberg sollst du nicht nachlesen, und die abgefallenen Beeren deines Weinbergs sollst du nicht auflesen; für den Elenden und für den Fremden sollst du sie lassen*. Ich bin der HERR, euer Gott*.", footnotes: ["℘ Kap. 23,22; 5Mo 24,21", "℘ V. 25.34; Kap. 11,44"] },
      { number: 11, text: "Ihr sollt nicht stehlen*; und ihr sollt nicht lügen und nicht betrügerisch handeln einer gegen den anderen*.", footnotes: ["℘ 2Mo 20,15", "℘ Ps 101,7; Eph 4,25; 1Thes 4,6"] },
      { number: 12, text: "Und ihr sollt bei meinem Namen nicht falsch schwören*, dass du den Namen deines Gottes entweihen würdest*. Ich bin der HERR. —", footnotes: ["℘ 2Mo 20,7; Sach 5,3; Mt 5,33", "℘ Kap. 5,22; 20,3; Jer 5,2; 34,16"] },
      { number: 13, text: "Du sollst deinen Nächsten nicht unterdrücken* und sollst <ihn> nicht berauben*; der Lohn des Tagelöhners darf über Nacht bis zum Morgen nicht bei dir bleiben*.", footnotes: ["o. erpressen; o. übervorteilen; vgl. Kap. 5,23\n℘ Kap. 25,17", "℘ Spr 22,22; Jer 22,13; Hes 22,29", "℘ 5Mo 24,14.15; Mt 20,8; Jak 5,4"] },
      { number: 14, text: "Du sollst einem Tauben nicht fluchen und vor einen Blinden kein Hindernis legen*, und du sollst dich fürchten vor deinem Gott*. Ich bin der HERR. —", footnotes: ["℘ 5Mo 27,18", "℘ V. 32; Kap. 25,17.36.43; Ps 111,10; 1Petr 2,17"] },
      { number: 15, text: "Ihr sollt im Gericht nicht Unrecht tun; du sollst die Person des Geringen nicht bevorzugen und die Person des Großen nicht ehren*; in Gerechtigkeit sollst du deinen Nächsten richten*.", footnotes: ["w. das Gesicht des Geringen sollst du nicht erheben und das Gesicht des Großen nicht auszeichnen", "℘ V. 35; 2Mo 23,2.3.6; Hi 32,21; Jak 2,1"] },
      { number: 16, text: "Du sollst nicht als ein Verleumder unter deinen Volksgenossen* umhergehen*. Du sollst nicht gegen das Blut deines Nächsten auftreten*. Ich bin der HERR. —", footnotes: ["w. unter deinen Völkern", "℘ Ps 15,3; 101,5; Spr 10,18; Jak 4,11", "d. h. dem Nächsten nach dem Leben trachten\n℘ 2Mo 23,1; 1Sam 24,10; Mt 5,43.44"] },
      { number: 17, text: "Du sollst deinen Bruder in deinem Herzen nicht hassen*. Du sollst deinen Nächsten ernstlich zurechtweisen*, damit du nicht seinetwegen Schuld trägst*.", footnotes: ["℘ 1Jo 3,15", "℘ Neh 13,17; Mt 18,15; 2Thes 3,15", "w. Sünde trägst. — Andere üs.: und sollst Sünde auf ihm nicht ertragen\n℘ Ps 141,5; 2Sam 13,22"] },
      { number: 18, text: "Du sollst dich nicht rächen* und den Kindern deines Volkes nichts nachtragen und sollst deinen Nächsten lieben wie dich selbst*. Ich bin der HERR.", footnotes: ["℘ Spr 20,22; Röm 12,19", "℘ Mt 5,43; Lk 10,27; Röm 13,9; Gal 5,14; Jak 2,8"] },
      { number: 19, text: "Meine Ordnungen sollt ihr halten*. Dein Vieh von zweierlei <Art> sollst du sich nicht begatten lassen*; dein Feld sollst du nicht mit zweierlei <Samen> besäen, und ein Kleid, aus zweierlei Stoff gewebt, soll nicht auf dich kommen*.", footnotes: ["℘ V. 37; Kap. 18,4; 20,8.22; 22,31; 25,18; 5Mo 4,1.5", "d. h. verschiedene Arten nicht kreuzen", "℘ 5Mo 22,9.11"] },
      { number: 20, text: "Und wenn ein Mann bei einer Frau zur Begattung liegt, und sie ist eine Sklavin, einem Mann verlobt*, und sie ist keineswegs losgekauft, noch ist ihr die Freiheit geschenkt, dann besteht Schadenersatzpflicht. Sie sollen nicht getötet werden, denn sie ist nicht frei gewesen.", footnotes: ["w. für einen <anderen> Mann bestimmt"] },
      { number: 21, text: "Und er soll dem HERRN sein Schuldopfer an den Eingang des Zeltes der Begegnung bringen, einen Widder als Schuldopfer." },
      { number: 22, text: "Und der Priester soll für ihn mit dem Widder des Schuldopfers vor dem HERRN Sühnung erwirken für seine Sünde, die er begangen hat; und in Bezug auf seine Sünde*, die er begangen hat, wird ihm vergeben werden*.", footnotes: ["w. von seiner Sünde <weg>", "℘ Kap. 4,20"] },
      { number: 23, text: "Und wenn ihr in das Land kommt und allerlei Bäume zur Speise pflanzt, dann sollt ihr ihre Früchte als ihre Vorhaut unbeschnitten lassen. Drei Jahre sollen sie euch als unbeschnitten gelten, sie dürfen nicht gegessen werden." },
      { number: 24, text: "Im vierten Jahr sollen all ihre Früchte dem HERRN eine heilige Festgabe* sein.", footnotes: ["w. ein heiliges Freudenfest. — Dieses Fest wurde am Ende der Ernte gefeiert."] },
      { number: 25, text: "Und im fünften Jahr sollt ihr ihre Früchte essen, damit ihr Ertrag euch <den Gewinn> vermehrt*. Ich bin der HERR, euer Gott.", footnotes: ["℘ Kap. 23,14"] },
      { number: 26, text: "Ihr sollt <Fleisch> nicht <zusammen> mit Blut essen*. Ihr sollt nicht Wahrsagerei noch Zauberei treiben*.", footnotes: ["℘ Kap. 3,17", "℘ 5Mo 18,10.11; 2Kö 17,17"] },
      { number: 27, text: "Ihr sollt nicht den Rand eures Haupthaares* rund scheren, und den Rand deines Bartes sollst du nicht verderben*.", footnotes: ["w. Kopfes", "℘ Kap. 21,5; Jer 9,25"] },
      { number: 28, text: "Und einen Einschnitt wegen eines Toten* sollt ihr an eurem Fleisch nicht machen*; und geätzte* Schrift sollt ihr an euch nicht machen. Ich bin der HERR.", footnotes: ["w. für die Seele", "℘ 5Mo 14,1; Jer 16,6", "o. tätowierte"] },
      { number: 29, text: "Du sollst deine Tochter nicht entweihen, sie zur Hurerei anzuhalten, dass das Land nicht Hurerei treibt und das Land voll Schandtaten wird*.", footnotes: ["℘ 5Mo 23,18"] },
      { number: 30, text: "Meine Sabbate sollt ihr halten*, und mein Heiligtum sollt ihr fürchten*. Ich bin der HERR.", footnotes: ["℘ V. 3", "℘ Kap. 26,2; 2Chr 36,14"] },
      { number: 31, text: "Ihr sollt euch nicht zu den Totengeistern* und zu den Wahrsagern* wenden*; ihr sollt sie nicht aufsuchen, euch an ihnen* unrein zu machen*. Ich bin der HERR, euer Gott*.", footnotes: ["o. zu den Totenbeschwörern", "w. Wissenden, o. Erkennenden", "℘ 5Mo 18,10.11; 2Kö 17,17", "o. durch sie", "℘ Kap. 20,6.27; 1Sam 28,3.7", "℘ V. 3.4.10.25"] },
      { number: 32, text: "Vor grauem Haar sollst du aufstehen und die Person* eines Greises ehren*, und du sollst dich fürchten vor deinem Gott. Ich bin der HERR.", footnotes: ["w. das Gesicht", "℘ Hi 32,4.6; 1Tim 5,1; 1Petr 5,5"] },
      { number: 33, text: "Und wenn ein Fremder bei dir — in eurem Land — als Fremder wohnt, sollt ihr ihn nicht unterdrücken*.", footnotes: ["℘ 2Mo 22,20; Jer 7,6"] },
      { number: 34, text: "Wie ein Einheimischer unter euch soll euch der Fremde sein, der bei euch als Fremder wohnt*; du sollst ihn lieben wie dich selbst. Denn Fremde seid ihr im Land Ägypten gewesen*. Ich bin der HERR, euer Gott*.", footnotes: ["℘ 2Mo 12,48.49; Hes 47,22", "℘ 5Mo 23,8; Rt 2,10", "℘ V. 3.4.10.25"] },
      { number: 35, text: "Ihr sollt nicht Unrecht tun im Gericht*, im Längenmaß, im Gewicht und im Hohlmaß.", footnotes: ["℘ V. 15"] },
      { number: 36, text: "Gerechte Waage, gerechte Gewichtsteine, gerechtes Efa und gerechtes Hin sollt ihr haben*. Ich bin der HERR, euer Gott, der ich euch aus dem Land Ägypten herausgeführt habe*.", footnotes: ["℘ 5Mo 25,13-15; 1Chr 23,29; Spr 16,11; Hes 45,10", "℘ Kap. 11,45"] },
      { number: 37, text: "Und so sollt ihr all meine Ordnungen und all meine Rechtsbestimmungen halten und sie tun*. Ich bin der HERR.", footnotes: ["℘ V. 19"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Gegen Götzendienst und Unzucht" },
      { number: 2, text: "Du sollst zu den Söhnen Israel sagen: Jedermann von den Söhnen Israel und von den Fremden, die in Israel als Fremde wohnen, der <eins> von seinen Kindern dem Moloch gibt*, muss getötet werden; das Volk des Landes soll ihn steinigen*.", footnotes: ["s. Anm. zu Kap. 18,21\n℘ 5Mo 12,31; 1Kö 11,7; Hes 23,37", "℘ V. 27; Kap. 24,14-16.23; 5Mo 13,11; 17,2-5; 21,21; 22,21.24"] },
      { number: 3, text: "Und ich werde mein Angesicht gegen diesen Mann richten und ihn aus der Mitte seines Volkes ausrotten*, weil er <eins> von seinen Kindern dem Moloch gegeben hat, mein Heiligtum unrein zu machen und meinen heiligen Namen zu entweihen*.", footnotes: ["℘ 2Mo 30,33.38", "℘ Kap. 18,21; 19,12; 21,6"] },
      { number: 4, text: "Und wenn das Volk des Landes seine Augen irgend verhüllt vor diesem Mann, wenn er von seinen Kindern <eins> dem Moloch gibt, so dass es ihn nicht tötet," },
      { number: 5, text: "so werde ich mein Angesicht gegen diesen Mann richten und gegen seine Sippe und werde ihn und alle, die ihm nachhuren, um dem Moloch nachzuhuren*, ausrotten aus der Mitte ihres Volkes*.", footnotes: ["℘ Kap. 17,7", "℘ 2Mo 20,5; Jer 44,11"] },
      { number: 6, text: "Und die Person*, die sich zu den Totengeistern* und zu den Wahrsagern* wendet, um ihnen nachzuhuren, gegen diese Person* werde ich mein Angesicht richten und sie ausrotten aus der Mitte ihres Volkes*. —", footnotes: ["o. Seele", "o. zu den Totenbeschwörern", "w. Wissenden, o. Erkennenden", "w. Wissenden, o. Erkennenden", "℘ V. 27; Kap. 19,31; 2Mo 22,17; 5Mo 18,11"] },
      { number: 7, text: "So sollt ihr euch heiligen und sollt heilig sein, denn ich bin der HERR, euer Gott*,", footnotes: ["℘ Kap. 11,44.45; Jos 3,5"] },
      { number: 8, text: "und sollt meine Ordnungen einhalten und sie tun*. Ich bin der HERR, der euch heiligt*.", footnotes: ["℘ Kap. 19,19.37", "℘ V. 26; Kap. 21,8; 22,32; 2Mo 31,13"] },
      { number: 9, text: "Wenn irgendjemand seinem Vater oder seiner Mutter flucht, muss er getötet werden*; er hat seinem Vater oder seiner Mutter geflucht, ihr Blut* ist auf ihm*.", footnotes: ["℘ 2Mo 21,17; Spr 30,11; Mk 7,10", "SamPent liest: sein Blut", "℘ Hes 18,13"] },
      { number: 10, text: "Wenn ein Mann mit einer Frau Ehebruch treibt, wenn ein Mann Ehebruch treibt mit der Frau seines Nächsten, müssen der Ehebrecher und die Ehebrecherin getötet werden*.", footnotes: ["℘ 2Mo 20,14; 5Mo 22,22-24; 2Sam 12,13; Hi 31,9-11; Joh 8,4.5"] },
      { number: 11, text: "*Und wenn ein Mann bei der Frau seines Vaters liegt; er hat die Blöße seines Vaters aufgedeckt, beide müssen getötet werden; ihr Blut ist auf ihnen.", footnotes: ["℘ V. 11-23: Kap. 18,6-30"] },
      { number: 12, text: "Und wenn ein Mann bei seiner Schwiegertochter liegt, müssen beide getötet werden. Sie haben eine schändliche Befleckung verübt; ihr Blut ist auf ihnen." },
      { number: 13, text: "Und wenn ein Mann bei einem Mann liegt, wie man bei einer Frau liegt, <dann> haben beide einen Gräuel verübt. Sie müssen getötet werden; ihr Blut ist auf ihnen." },
      { number: 14, text: "Und wenn ein Mann eine Frau nimmt und ihre Mutter, das ist eine Schandtat; man soll ihn und sie mit Feuer verbrennen*, damit keine Schandtat in eurer Mitte sei.", footnotes: ["℘ Kap. 21,9"] },
      { number: 15, text: "Und wenn ein Mann bei einem Vieh liegt, soll er unbedingt getötet werden*, und das Vieh sollt ihr umbringen.", footnotes: ["℘ 5Mo 27,21"] },
      { number: 16, text: "Und wenn eine Frau sich irgendeinem Vieh nähert, damit es sie begatte, dann sollst du die Frau und das Vieh umbringen. Sie müssen getötet werden; ihr Blut ist auf ihnen." },
      { number: 17, text: "Und wenn ein Mann seine Schwester nimmt, die Tochter seines Vaters oder die Tochter seiner Mutter, und er sieht ihre Blöße; und sie sieht seine Blöße: das ist eine Schande, und sie sollen ausgerottet werden vor den Augen der Kinder ihres Volkes*. Er hat die Blöße seiner Schwester aufgedeckt, er soll seine Schuld tragen.", footnotes: ["℘ 2Mo 30,33.38"] },
      { number: 18, text: "Und wenn ein Mann bei einer kranken* Frau liegt und ihre Blöße aufdeckt, so hat er ihre Quelle enthüllt, und sie hat die Quelle ihres Blutes aufgedeckt. Sie sollen beide ausgerottet werden aus der Mitte ihres Volkes*.", footnotes: ["d. h. menstruierenden", "℘ 2Mo 30,33.38"] },
      { number: 19, text: "Und die Blöße der Schwester deiner Mutter und der Schwester deines Vaters sollst du nicht aufdecken, denn wer das tut, hat* seine Blutsverwandte entblößt; sie sollen ihre Schuld tragen.", footnotes: ["w. denn er hat"] },
      { number: 20, text: "Und wenn ein Mann bei der Frau seines Onkels liegt, hat er die Blöße seines Onkels aufgedeckt. Sie sollen ihre Sünde tragen, kinderlos sollen sie sterben." },
      { number: 21, text: "Und wenn ein Mann die Frau seines Bruders nimmt; das ist eine Befleckung. Er hat die Blöße seines Bruders aufgedeckt, sie sollen kinderlos sein." },
      { number: 22, text: "Und ihr sollt all meine Ordnungen und all meine Rechtsbestimmungen halten und sie tun, damit euch das Land nicht ausspeit, in das ich euch bringe, darin zu wohnen." },
      { number: 23, text: "Und ihr sollt nicht in den Ordnungen der Nation* leben, die ich vor euch vertreibe; denn alle diese Dinge haben sie getan, und sie sind mir zum Ekel geworden*.", footnotes: ["Eine hebr. Handschr., SamPent und die alten Üs. lesen: Nationen", "℘ Kap. 18,2-4"] },
      { number: 24, text: "Und ich habe zu euch gesagt: Ihr sollt ihr Land besitzen, und ich werde es euch zum Besitz geben, ein Land, das von Milch und Honig überfließt*. Ich bin der HERR, euer Gott, der ich euch von den Völkern ausgesondert* habe*.", footnotes: ["℘ 2Mo 3,8.17", "o. unterschieden", "℘ 2Mo 19,5.6; 5Mo 7,6; 14,2"] },
      { number: 25, text: "Und ihr sollt unterscheiden zwischen dem reinen Vieh und dem unreinen, zwischen den unreinen Vögeln und den reinen, und sollt euch selbst* nicht zu etwas Abscheulichem machen durch das Vieh und durch die Vögel und durch alles, was sich auf dem Erdboden regt, das ich euch als unrein ausgesondert* habe*.", footnotes: ["w. eure Seelen", "o. unterschieden", "℘ Kap. 10,10; Apg 10,14"] },
      { number: 26, text: "Und ihr sollt mir heilig sein, denn ich bin heilig, ich, der HERR*. Und ich habe euch von den Völkern ausgesondert*, um mein zu sein*.", footnotes: ["℘ Kap. 11,44.45", "o. unterschieden", "℘ 5Mo 26,18.19; Neh 10,29; Tit 2,14"] },
      { number: 27, text: "Und wenn in einem Mann oder einer Frau ein Totengeist oder Wahrsagegeist ist; sie müssen getötet werden*. Man soll sie steinigen*; ihr Blut ist auf ihnen.", footnotes: ["℘ V. 6", "℘ V. 2"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und der HERR sprach zu Mose: Rede zu den Priestern, den Söhnen Aarons, und sage zu ihnen: Keiner von ihnen darf sich* an einer Leiche* unrein machen unter seinen Volksgenossen*,", heading: "Anforderungen an die Priester", footnotes: ["w. Er <der Priester> darf sich nicht", "w. Seele <eines Toten>", "w. Völkern\n℘ 4Mo 19,11.14.16; Hes 44,25"] },
      { number: 2, text: "außer an seiner Blutsverwandtschaft, die* ihm nahesteht: an seiner Mutter und an seinem Vater, seinem Sohn, seiner Tochter und seinem Bruder", footnotes: ["w. an seinem Fleisch, das"] },
      { number: 3, text: "und an seiner Schwester, der Jungfrau, die ihm nahesteht, die noch keinem Mann <zu eigen> geworden ist; wegen dieser darf er sich unrein machen." },
      { number: 4, text: "Er darf sich nicht unrein machen als Herr* unter seinen Volksgenossen*, sich zu entweihen.", footnotes: ["d. h. wohl: als <Ehe>herr; andere üs. mit Ergänzung eines Wortes: an <seiner Schwester>, die einem <Ehe>herrn verheiratet ist", "w. Völkern"] },
      { number: 5, text: "Sie sollen keine Glatze auf ihrem Kopf scheren, und den Rand ihres Bartes sollen sie nicht abscheren, und an ihrem Fleische sollen sie keine Einschnitte machen*.", footnotes: ["℘ Kap. 19,27.28; Jes 15,2; Hes 44,20"] },
      { number: 6, text: "Sie sollen ihrem Gott heilig sein, und den Namen ihres Gottes sollen sie nicht entweihen*, denn die Feueropfer des HERRN, das Brot ihres Gottes, bringen sie dar*; und sie sollen heilig sein*.", footnotes: ["℘ V. 23; Kap. 10,3; 18,21", "℘ 4Mo 28,2; 1Petr 2,5", "℘ Esr 8,28; Jes 52,11; Mal 1,7"] },
      { number: 7, text: "Eine Hure und eine Entehrte sollen sie nicht <zur Frau> nehmen*, und eine von ihrem Mann verstoßene Frau sollen sie nicht nehmen; denn heilig ist er seinem Gott.", footnotes: ["℘ Hes 44,22"] },
      { number: 8, text: "Und du sollst ihn für heilig achten, denn das Brot deines Gottes bringt er dar*. Er soll dir heilig sein; denn heilig bin ich, der HERR, der euch heiligt*.", footnotes: ["℘ 4Mo 28,2; 1Petr 2,5", "℘ Kap. 19,2; 20,7.8; 22,16; Neh 13,29"] },
      { number: 9, text: "Und wenn die Tochter eines Priesters sich durch Hurerei entweiht, so entweiht sie ihren Vater; sie soll mit Feuer verbrannt werden*. —", footnotes: ["℘ Kap. 20,14; 1Mo 38,24; Offb 17,16"] },
      { number: 10, text: "Und der Hohepriester unter seinen Brüdern, auf dessen Kopf das Salböl gegossen worden und der geweiht ist*, um die <heiligen> Kleider anzulegen, soll seinen Kopf nicht ungepflegt lassen* und soll seine Kleider nicht zerreißen*.", footnotes: ["w. der seine Hand gefüllt hat", "w. frei hängen lassen", "℘ Kap. 10,6.7; Mt 26,65"] },
      { number: 11, text: "Und er soll zu keiner Leiche kommen; um seines Vaters und um seiner Mutter willen soll er sich nicht unrein machen*.", footnotes: ["℘ 4Mo 19,14"] },
      { number: 12, text: "Und aus dem Heiligtum soll er nicht hinausgehen und nicht <so> das Heiligtum seines Gottes entweihen; denn die Weihe des Salböls seines Gottes ist auf ihm*. Ich bin der HERR.", footnotes: ["℘ Kap. 10,7; 4Mo 6,6-8"] },
      { number: 13, text: "Und er soll eine Frau in ihrer Jungfrauschaft nehmen*.", footnotes: ["℘ Hes 44,22"] },
      { number: 14, text: "Eine Witwe und eine Verstoßene und eine Entehrte, eine Hure, diese soll er nicht nehmen*, sondern eine Jungfrau aus seinen Volksgenossen* soll er zur Frau nehmen*.", footnotes: ["℘ Hes 44,22", "w. Völkern", "℘ Hes 44,22"] },
      { number: 15, text: "Und er soll seinen Samen nicht entweihen unter seinen Volksgenossen*; denn ich bin der HERR, der ihn heiligt*.", footnotes: ["w. Völkern\n℘ Esr 9,2", "℘ Kap. 19,2; 20,7.8; 22,16; Neh 13,29"] },
      { number: 16, text: "Und der HERR redete zu Mose:" },
      { number: 17, text: "Rede zu Aaron: Jemand von deinen Nachkommen bei ihren Generationen, an dem ein Makel ist, darf nicht herannahen, um das Brot seines Gottes darzubringen;" },
      { number: 18, text: "denn jedermann, an dem ein Makel ist, darf nicht herannahen, <sei es> ein blinder Mann oder ein lahmer oder einer mit gespaltener Nase oder der ein Glied zu lang hat*,", footnotes: ["Andere üs.: der schlitzohrig ist; LXX: mit einem verstümmelten Ohr"] },
      { number: 19, text: "oder ein Mann, der einen Bruch am Fuß oder einen Bruch an der Hand hat," },
      { number: 20, text: "oder ein Buckliger oder ein Zwerg* oder der einen <weißen> Flecken in seinem Auge hat oder der die Krätze oder Flechte oder der zerdrückte Hoden hat*.", footnotes: ["o. ein Schwindsüchtiger; w. ein Dünner, o. Elender", "℘ 5Mo 23,2"] },
      { number: 21, text: "Jedermann von den Nachkommen des Priesters Aaron, der einen Makel hat, soll nicht herantreten, die Feueropfer des HERRN darzubringen. Ein Makel ist an ihm, er soll nicht herzutreten, das Brot seines Gottes darzubringen." },
      { number: 22, text: "Das Brot seines Gottes von dem Hochheiligen* und von dem Heiligen* mag er essen*.", footnotes: ["℘ Kap. 2,3.10; 6,10.18.22; 7,1.6; 10,12.17; 14,13; 24,9; 27,28", "℘ Kap. 22,10-15; 4Mo 18,19", "℘ Kap. 22,7"] },
      { number: 23, text: "Nur zum Vorhang* soll er nicht kommen, und an den Altar soll er nicht herantreten, denn ein Makel ist an ihm, dass er nicht meine Heiligtümer* entweiht; denn ich bin der HERR, der sie heiligt*.", footnotes: ["w. zum Absperrenden", "o. heiligen Dinge", "℘ Kap. 19,2; 20,7.8; 22,16; Neh 13,29"] },
      { number: 24, text: "Und so redete Mose zu Aaron und zu seinen Söhnen und zu allen Söhnen Israel." },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Verordnungen über das Essen der Opfer" },
      { number: 2, text: "Rede zu Aaron und zu seinen Söhnen, dass sie sich enthalten von den heiligen Dingen* der Söhne Israel, die sie mir heiligen, und meinen heiligen Namen nicht entweihen*. Ich bin der HERR.", footnotes: ["o. sich ehrfurchtsvoll verhalten vor den heiligen Gaben", "℘ V. 32; Kap. 18,21; Jes 52,11"] },
      { number: 3, text: "Sage zu ihnen: Wer irgend von all euren Nachkommen, bei euren Generationen, sich den heiligen Dingen nähert, die die Söhne Israel dem HERRN heiligen, und seine Unreinheit ist an ihm, diese Person* soll ausgerottet werden vor meinem Angesicht hinweg*. Ich bin der HERR.", footnotes: ["o. Seele", "℘ 2Mo 30,33.38"] },
      { number: 4, text: "Jedermann von den Nachkommen Aarons, der aussätzig ist oder an Schleimfluss leidet*, soll nicht von den heiligen Dingen essen, bis er rein ist*. Und wer irgendeinen berührt, der durch eine Leiche* unrein gemacht ist*, oder jemanden, dem der Samenerguss entgeht*,", footnotes: ["w. fließt", "℘ Kap. 14,2; 15,2", "w. Seele <eines Toten>", "℘ 4Mo 19,11-13", "℘ Kap. 15,16"] },
      { number: 5, text: "oder wer irgendein kriechendes Tier* berührt, das für ihn unrein ist*, oder einen Menschen, der für ihn unrein ist, durch jegliche Unreinheit, die er hat:", footnotes: ["w. irgendein Gewimmel", "℘ Kap. 11,43.44"] },
      { number: 6, text: "Einer, der solches berührt, der wird bis zum Abend unrein sein. Er darf nicht von den heiligen Dingen essen, sondern soll sein Fleisch im Wasser baden*;", footnotes: ["℘ Kap. 11,24.25"] },
      { number: 7, text: "und ist die Sonne untergegangen, dann ist er rein. Danach darf er von den heiligen Dingen essen, denn es ist sein Brot*.", footnotes: ["℘ Kap. 21,22; 4Mo 18,9-13"] },
      { number: 8, text: "Aas und Zerrissenes darf er nicht essen, dass er sich dadurch unrein macht*. Ich bin der HERR.", footnotes: ["℘ 2Mo 22,30; Hes 44,31"] },
      { number: 9, text: "Und sie sollen meine Vorschriften beachten*, damit sie nicht deswegen Sünde auf sich laden* und dadurch sterben, weil sie es* entweihen*. Ich bin der HERR, der sie heiligt.", footnotes: ["o. für meinen Dienst sorgen", "w. Sünde tragen", "d. h. wahrscheinlich das Geheiligte, das Brot", "℘ 2Mo 28,43"] },
      { number: 10, text: "Und kein Fremder* darf Heiliges essen. Der Beisasse* und der Tagelöhner eines Priesters dürfen nicht Heiliges essen*.", footnotes: ["o. Unbefugter; d. h. einer, der nicht zum Stand der Priester gehört", "Das Wort bezeichnet einen Ansässigen ohne Bürgerrecht, das war ein sozialer Stand zwischen dem Sklaven und dem Vollbürger.", "℘ 2Mo 12,43; 29,33; 1Sam 21,7; Esr 2,63; Hes 44,8"] },
      { number: 11, text: "Wenn aber ein Priester eine Person* mit seinem Geld als Eigentum erwirbt, <dann> darf diese davon essen; und die in seinem Haus geborenen <Sklaven, auch> sie dürfen von seinem Brot essen*.", footnotes: ["o. Seele", "℘ Kap. 21,22; 4Mo 18,9-13"] },
      { number: 12, text: "Und wenn die Tochter eines Priesters <die Frau> eines fremden* Mannes wird, darf sie nicht von dem Hebopfer der heiligen Dinge essen.", footnotes: ["d. h. eines nicht-israelitischen, o. eines nicht-aaronitischen"] },
      { number: 13, text: "Wenn aber die Tochter eines Priesters Witwe oder verstoßen wird und keine Kinder* hat und in das Haus ihres Vaters zurückkehrt wie in ihrer Jugend*, <dann> darf sie vom Brot ihres Vaters essen*. Aber kein Fremder* darf davon essen*.", footnotes: ["w. keinen Samen", "℘ 1Mo 38,11", "℘ Kap. 10,14", "o. Unbefugter; d. h. einer, der nicht zum Stand der Priester gehört", "℘ 2Mo 12,43; 29,33; 1Sam 21,7; Esr 2,63; Hes 44,8"] },
      { number: 14, text: "Und wenn jemand aus Versehen Heiliges isst, dann soll er ein Fünftel davon hinzufügen und dem Priester das Heilige erstatten*.", footnotes: ["℘ Kap. 5,15.16"] },
      { number: 15, text: "Und man darf die heiligen Dinge* der Söhne Israel nicht entweihen*, die sie dem HERRN abheben*,", footnotes: ["o. Gaben", "℘ 2Mo 28,43", "d. i. durch Hochheben der Opfergabe weihen"] },
      { number: 16, text: "und ihnen so die Sünde einer Schuld aufladen, wenn sie ihre heiligen Dinge* essen; denn ich bin der HERR, der sie heiligt*.", footnotes: ["o. Gaben", "℘ Kap. 21,8.15"] },
      { number: 17, text: "Und der HERR redete zu Mose:" },
      { number: 18, text: "Rede zu Aaron und zu seinen Söhnen und zu allen Söhnen Israel und sage zu ihnen: Jedermann vom Haus Israel und von den Fremden in Israel, der seine Opfergabe darbringt, nach all ihren Gelübden und nach all ihren freiwilligen Gaben*, die sie dem HERRN als Brandopfer darbringen —", footnotes: ["℘ 4Mo 15,3; Am 4,5"] },
      { number: 19, text: "zum Wohlgefallen <Gottes> für euch <soll er sie darbringen>: ohne Fehler*, männlich, von den Rindern, von den Schafen oder von den Ziegen*.", footnotes: ["℘ Kap. 1,3.10", "℘ Kap. 1,2.10"] },
      { number: 20, text: "Alles, woran ein Makel ist, dürft ihr nicht darbringen, denn es wird nicht zum Wohlgefallen für euch sein*.", footnotes: ["℘ 5Mo 15,21; 17,1; Mal 1,8.13.14"] },
      { number: 21, text: "Und wenn jemand dem HERRN ein Heilsopfer* darbringt, um ein Gelübde zu erfüllen oder als freiwillige Gabe, vom Rind- oder vom Kleinvieh: ohne Fehler soll es sein, zum Wohlgefallen*; keinerlei Makel darf an ihm sein.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 3,1.6"] },
      { number: 22, text: "Ein blindes oder verletztes oder verstümmeltes Tier oder <eines>, das eine Warze oder die Krätze oder die Flechte hat, diese dürft ihr dem HERRN nicht darbringen, und <ihr> sollt dem HERRN keine Feueropfer davon auf den Altar geben." },
      { number: 23, text: "Und einen Stier oder ein Schaf* mit einem zu langen Glied* oder abgehauenen Schwanz*, das magst du als freiwillige Gabe opfern; aber zu einem Gelübde wird es nicht als wohlgefällig betrachtet werden*.", footnotes: ["o. Ziege; o. Lamm", "LXX: mit einem verstümmelten Ohr; andere üs.: schlitzohrig", "So deutet LXX das hebr. Wort; die aram. Üs. liest: mit verkümmerten Gliedern. Die Bedeutung des hebr. Wortes ist unbekannt.", "℘ 5Mo 15,21; 17,1; Mal 1,8.13.14"] },
      { number: 24, text: "Und dem die Hoden zerquetscht oder zerstoßen oder ausgerissen oder ausgeschnitten sind, dürft ihr dem HERRN nicht darbringen; und in eurem Land sollt ihr <so etwas> nicht tun*.", footnotes: ["d. h. ihr dürft weder Tiere kastrieren noch solche Tiere opfern"] },
      { number: 25, text: "Und aus der Hand eines Ausländers* dürft ihr nichts von diesen <Tieren kaufen und davon> die Speise eures Gottes darbringen; denn ihr Schaden ist an ihnen, ein Makel ist an ihnen. Sie werden nicht als wohlgefällig für euch betrachtet werden.", footnotes: ["w. Sohnes des Auslandes"] },
      { number: 26, text: "Und der HERR redete zu Mose:" },
      { number: 27, text: "Wenn ein Stier oder ein Schaf* oder eine Ziege geboren wird, dann soll es sieben Tage unter seiner Mutter sein. Und vom achten Tag an und weiterhin wird es als wohlgefällig betrachtet werden zur Opfergabe eines Feueropfers für den HERRN*. —", footnotes: ["w. ein männliches Schaflamm", "℘ 2Mo 22,29"] },
      { number: 28, text: "Und ein Rind oder ein Schaf*, es selbst und sein Junges dürft ihr nicht an einem Tag* schlachten. —", footnotes: ["o. eine Ziege", "℘ 5Mo 22,6.7"] },
      { number: 29, text: "Und wenn ihr dem HERRN ein Dankopfer schlachtet, sollt ihr es zum Wohlgefallen für euch schlachten*:", footnotes: ["℘ Kap. 7,11"] },
      { number: 30, text: "An demselben Tag soll es gegessen werden. Ihr sollt nichts davon bis zum <nächsten> Morgen übrig lassen*. Ich bin der HERR.", footnotes: ["℘ Kap. 7,15-18"] },
      { number: 31, text: "Und ihr sollt meine Gebote halten und sie tun*. Ich bin der HERR*.", footnotes: ["℘ Kap. 19,37", "℘ 5Mo 15,21; 17,1; Mal 1,8.13.14"] },
      { number: 32, text: "Und ihr sollt meinen heiligen Namen nicht entweihen*, damit ich geheiligt werde* in der Mitte der Söhne Israel. Ich bin der HERR, der euch heiligt*,", footnotes: ["℘ V. 2", "℘ Jes 8,13", "℘ Kap. 20,8"] },
      { number: 33, text: "der euch aus dem Land Ägypten herausgeführt hat, um euer Gott zu sein*. Ich bin der HERR.", footnotes: ["℘ Kap. 11,45; 4Mo 15,41"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Gebote zu Sabbat und zu den drei Jahresfesten" },
      { number: 2, text: "Rede zu den Söhnen Israel und sage zu ihnen: Die Feste* des HERRN, die ihr als heilige Versammlungen ausrufen sollt, meine Feste sind diese*:", footnotes: ["w. die bestimmten Zeiten; d. h. um Gott zu nahen; so auch V. 4.37.44", "℘ 2Chr 2,3; Esr 3,5; Hes 44,24; Kol 2,16"] },
      { number: 3, text: "Sechs Tage soll man Arbeit tun; aber am siebten Tag ist ein ganz feierlicher Sabbat*, eine heilige Versammlung. Keinerlei Arbeit dürft ihr tun; es ist ein Sabbat für den HERRN in all euren Wohnsitzen.", footnotes: ["w. ein Sabbat der Sabbatfeier\n℘ 2Mo 20,8-11"] },
      { number: 4, text: "Dies sind die Feste des HERRN, heilige Versammlungen, die ihr ausrufen sollt zu ihrer bestimmten Zeit*:", footnotes: ["℘ Jes 29,1"] },
      { number: 5, text: "Im ersten Monat, am Vierzehnten des Monats, zwischen den zwei Abenden*, ist Passah dem HERRN*.", footnotes: ["d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen dem Niedergang und dem Untergang der Sonne", "℘ 2Mo 12,2-11; Mt 26,17-19"] },
      { number: 6, text: "Am fünfzehnten Tag dieses Monats ist das Fest der ungesäuerten Brote dem HERRN; sieben Tage sollt ihr ungesäuertes Brot essen*.", footnotes: ["℘ 2Mo 12,15-20; Mk 14,1"] },
      { number: 7, text: "Am ersten Tag soll für euch eine heilige Versammlung sein, keinerlei Dienstarbeit dürft ihr tun*.", footnotes: ["℘ V. 21; 4Mo 28,18; 29,1"] },
      { number: 8, text: "Und ihr sollt dem HERRN sieben Tage <lang> ein Feueropfer darbringen*. Am siebten Tag ist eine heilige Versammlung, keinerlei Dienstarbeit dürft ihr tun.", footnotes: ["℘ Hes 45,23"] },
      { number: 9, text: "Und der HERR redete zu Mose:" },
      { number: 10, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ihr in das Land kommt, das ich euch gebe, und ihr seine Ernte erntet, dann sollt ihr eine Garbe der Erstlinge eurer Ernte zum Priester bringen*.", footnotes: ["℘ Kap. 2,12.14; 2Mo 23,16.19"] },
      { number: 11, text: "Und er soll die Garbe vor dem HERRN schwingen* zum Wohlgefallen für euch; am andern Tag nach dem Sabbat soll der Priester sie schwingen.", footnotes: ["℘ 2Mo 29,24"] },
      { number: 12, text: "Und ihr sollt an dem Tag, an dem ihr die Garbe schwingt, ein einjähriges Lamm ohne Fehler zum Brandopfer für den HERRN opfern*;", footnotes: ["℘ Kap. 1,10"] },
      { number: 13, text: "und sein Speisopfer: zwei Zehntel Weizengrieß, mit Öl gemengt*, ein Feueropfer für den HERRN, ein wohlgefälliger Geruch*; und sein Trankopfer: ein viertel Hin Wein*.", footnotes: ["o. angefeuchtet", "o. Geruch der Befriedigung o. Beschwichtigung\n℘ Kap. 2,14-16", "℘ 4Mo 15,5"] },
      { number: 14, text: "Und Brot und geröstete Körner und Jungkorn dürft ihr nicht essen bis zu ebendiesem Tag, bis ihr die Opfergabe eures Gottes gebracht habt*: eine ewige Ordnung für eure Generationen in all euren Wohnsitzen*.", footnotes: ["℘ Kap. 19,23-25", "℘ V. 31.41; 2Mo 27,21"] },
      { number: 15, text: "Und ihr sollt für euch zählen von dem Tag nach dem Sabbat, von dem Tag, an dem ihr die Garbe fürs Schwingopfer gebracht habt: Es sollen sieben volle Wochen sein*.", footnotes: ["℘ 2Mo 34,22; 5Mo 16,9.10"] },
      { number: 16, text: "Bis zum andern Tag nach dem siebten Sabbat sollt ihr fünfzig Tage zählen*. Dann sollt ihr dem HERRN ein neues Speisopfer darbringen*.", footnotes: ["℘ Apg 2,1", "℘ 4Mo 28,26"] },
      { number: 17, text: "Aus euren Wohnungen sollt ihr Brot fürs Schwingopfer bringen, zwei von zwei Zehnteln Weizengrieß sollen es sein, gesäuert sollen sie gebacken werden, als Erstlinge für den HERRN*.", footnotes: ["℘ 2Mo 23,16; 4Mo 15,20"] },
      { number: 18, text: "Und ihr sollt zu dem Brot hinzu sieben einjährige Lämmer ohne Fehler* darbringen und einen Jungstier und zwei Widder, sie sollen ein Brandopfer für den HERRN sein, dazu ihr Speisopfer und ihre Trankopfer: ein Feueropfer als wohlgefälliger Geruch* für den HERRN.", footnotes: ["℘ Kap. 1,3.10", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 19, text: "Und ihr sollt einen Ziegenbock* zum Sündopfer opfern und zwei einjährige Lämmer zum Heilsopfer*.", footnotes: ["w. Haarigen der Ziegen", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ Kap. 3,6.7; 4,23; 4Mo 15,24"] },
      { number: 20, text: "Und der Priester soll sie schwingen mit dem Erstlingsbrot* als Schwingopfer vor dem HERRN, mit den zwei Lämmern; sie sollen dem HERRN heilig sein für den Priester*.", footnotes: ["d. i. Brot vom ersten Korn der Ernte", "℘ 4Mo 18,8-12"] },
      { number: 21, text: "Und ihr sollt an ebendiesem Tag einen Ruf ergehen lassen — eine heilige Versammlung soll euch* sein. Keinerlei Dienstarbeit dürft ihr tun*: eine ewige Ordnung in all euren Wohnsitzen für eure Generationen*. —", footnotes: ["o. soll er", "℘ V. 7.8", "℘ V. 31.41; 2Mo 27,21"] },
      { number: 22, text: "Und wenn ihr die Ernte eures Landes erntet, darfst du den Rand deines Feldes nicht vollständig abernten, und du sollst keine Nachlese deiner Ernte halten; für den Elenden und für den Fremden sollst du sie lassen*. Ich bin der HERR, euer Gott.", footnotes: ["℘ Kap. 19,9.10"] },
      { number: 23, text: "*Und der HERR redete zu Mose:", footnotes: ["℘ V. 23-25: 4Mo 29,1-6"] },
      { number: 24, text: "Rede zu den Söhnen Israel: Im siebten Monat, am Ersten des Monats*, soll euch Ruhe* sein, eine Erinnerung durch Lärm<blasen>, eine heilige Versammlung.", footnotes: ["℘ Neh 8,2", "o. eine Sabbatfeier"] },
      { number: 25, text: "Keinerlei Dienstarbeit dürft ihr tun, und ihr sollt dem HERRN ein Feueropfer darbringen*.", footnotes: ["℘ Esr 3,6"] },
      { number: 26, text: "*Und der HERR redete zu Mose:", footnotes: ["℘ V. 26-32: 4Mo 29,7-11"] },
      { number: 27, text: "Doch am Zehnten dieses siebten Monats, da ist der Versöhnungstag*. Eine heilige Versammlung soll <er> für euch sein, und ihr sollt euch selbst demütigen* und sollt dem HERRN ein Feueropfer darbringen.", footnotes: ["℘ Kap. 16", "w. eure Seelen <durch Fasten> erniedrigen\n℘ Kap. 16,29-31"] },
      { number: 28, text: "Und keinerlei Arbeit dürft ihr tun an ebendiesem Tag; denn es ist der Versöhnungstag, um Sühnung für euch zu erwirken vor dem HERRN, eurem Gott*.", footnotes: ["℘ Kap. 16,30-34"] },
      { number: 29, text: "Denn jede Person*, die sich nicht demütigt an ebendiesem Tag, die soll ausgerottet werden aus ihren Völkern*.", footnotes: ["o. Seele", "d. h. aus ihrer Volksgemeinschaft\n℘ 2Mo 30,33.38; Apg 3,23"] },
      { number: 30, text: "Und jede Person*, die irgendeine Arbeit tut an ebendiesem Tag, ebendiese Person* werde ich umkommen lassen aus der Mitte ihres Volkes.", footnotes: ["o. Seele", "o. Seele"] },
      { number: 31, text: "Keinerlei Arbeit dürft ihr tun: eine ewige Ordnung für eure Generationen in all euren Wohnsitzen*.", footnotes: ["℘ V. 14.21"] },
      { number: 32, text: "Ein ganz feierlicher Sabbat* soll er für euch sein, und ihr sollt euch selbst demütigen*. Am Neunten des Monats, am Abend, vom Abend bis zum Abend, sollt ihr euren Sabbat feiern*.", footnotes: ["w. ein Sabbat der Sabbatfeier", "w. eure Seelen <durch Fasten> erniedrigen\n℘ Kap. 16,29-31", "w. Sabbat ruhen"] },
      { number: 33, text: "*Und der HERR redete zu Mose:", footnotes: ["℘ V. 33-43: 4Mo 29,12-38"] },
      { number: 34, text: "Rede zu den Söhnen Israel: Am fünfzehnten Tag dieses siebten Monats ist das Fest der Laubhütten sieben Tage für den HERRN*.", footnotes: ["℘ 2Mo 23,16; 34,22; 5Mo 16,13; 31,10; 1Kö 8,2; 12,32; Esr 3,4; Neh 8,14; Hes 45,25; Sach 14,16; Joh 7,2"] },
      { number: 35, text: "Am ersten Tag soll eine heilige Versammlung sein, keinerlei Dienstarbeit dürft ihr tun." },
      { number: 36, text: "Sieben Tage sollt ihr dem HERRN ein Feueropfer darbringen. Am achten Tag soll für euch eine heilige Versammlung sein*, und ihr sollt dem HERRN ein Feueropfer darbringen: Es ist eine Festversammlung, keinerlei Dienstarbeit dürft ihr tun*.", footnotes: ["℘ Joh 7,37", "℘ V. 7.8; Neh 8,18"] },
      { number: 37, text: "Das sind die Feste des HERRN, die ihr ausrufen sollt als heilige Versammlungen, um dem HERRN Feueropfer darzubringen: Brandopfer und Speisopfer, Schlachtopfer und Trankopfer, die Gebühr des Tages an seinem Tag;" },
      { number: 38, text: "außer den Sabbaten des HERRN und außer euren Gaben und außer all euren Gelübden und außer all euren freiwilligen Gaben, die ihr dem HERRN gebt*.", footnotes: ["℘ 4Mo 29,39; Ps 56,13; 76,12"] },
      { number: 39, text: "Doch am fünfzehnten Tag des siebten Monats, wenn ihr den Ertrag des Landes eingesammelt habt, sollt ihr sieben Tage das Fest des HERRN feiern. Am ersten Tag soll Ruhe* sein, und am achten Tag soll Ruhe sein.", footnotes: ["o. eine Sabbatfeier"] },
      { number: 40, text: "Und ihr sollt euch am ersten Tag prächtige Baumfrüchte nehmen, Palmwedel und Zweige von dicht belaubten Bäumen und von Bachpappeln und sollt euch vor dem HERRN, eurem Gott, sieben Tage freuen*.", footnotes: ["℘ 5Mo 12,12; Neh 8,14-17"] },
      { number: 41, text: "Und ihr sollt es sieben Tage im Jahr als Fest für den HERRN feiern: eine ewige Ordnung für eure Generationen;* im siebten Monat sollt ihr es feiern.", footnotes: ["℘ V. 14.21"] },
      { number: 42, text: "In Laubhütten sollt ihr wohnen sieben Tage. Alle Einheimischen in Israel sollen in Laubhütten wohnen*,", footnotes: ["℘ Hos 12,10"] },
      { number: 43, text: "damit eure Generationen wissen*, dass ich die Söhne Israel in Laubhütten habe wohnen lassen, als ich sie aus dem Land Ägypten herausführte*. Ich bin der HERR, euer Gott. —", footnotes: ["o. erkennen", "℘ 2Mo 12,51"] },
      { number: 44, text: "Und Mose sagte den Söhnen Israel die Feste des HERRN." },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Verordnungen über die Leuchter und Schaubrote" },
      { number: 2, text: "Befiehl den Söhnen Israel, dass sie dir reines Öl aus zerstoßenen Oliven bringen für die Leuchter, damit man beständig eine Lampe darauf setzen kann*.", footnotes: ["℘ 2Mo 27,20.21"] },
      { number: 3, text: "Außerhalb des Vorhangs des Zeugnisses*, im Zelt der Begegnung, soll Aaron sie beständig herrichten, vom Abend bis zum Morgen, vor dem HERRN: eine ewige Ordnung für eure Generationen.", footnotes: ["o. Über dem, was das Zeugnis absperrt; d. h. schützt"] },
      { number: 4, text: "Auf dem reinen Lampenständer* soll er die Lampen beständig vor dem HERRN zurichten*.", footnotes: ["o. Leuchter. — Andere üs.: Auf dem <aus> reinem <Gold angefertigten> Lampenständer", "℘ 2Mo 25,37; 2Chr 29,7"] },
      { number: 5, text: "Und du sollst Weizengrieß nehmen und daraus zwölf Kuchen backen: von zwei zehntel <Efa> soll ein Kuchen sein." },
      { number: 6, text: "Und du sollst sie in zwei Schichten* legen, sechs in jede Schicht, auf den reinen Tisch* vor dem HERRN*.", footnotes: ["o. Reihen", "Andere üs.: auf dem Tisch aus reinem <Gold>", "℘ 2Mo 25,30; Neh 10,34"] },
      { number: 7, text: "Und du sollst auf jede Schicht reinen Weihrauch legen, und er soll dem Brot als Askara* dienen, ein Feueropfer dem HERRN*.", footnotes: ["d. i. der zu verbrennende Teil des Speisopfers", "℘ Kap. 2,1.2"] },
      { number: 8, text: "Sabbattag für Sabbattag soll er es regelmäßig vor dem HERRN zurichten*: ein ewiger Bund bei den Söhnen Israel.", footnotes: ["℘ 1Sam 21,7; 1Chr 9,32; 23,29; 2Chr 13,11"] },
      { number: 9, text: "Und es soll Aaron und seinen Söhnen gehören, und sie sollen es an heiliger Stätte essen; denn als ein Hochheiliges* von den Feueropfern des HERRN soll es ihm gehören*: eine ewige Ordnung*.", footnotes: ["℘ Kap. 21,22", "℘ Kap. 6,9-11; 10,12.13; Mt 12,4", "o. ein ewiger Anspruch\n℘ 2Mo 27,21"] },
      { number: 10, text: "Und der Sohn einer israelitischen Frau — er war aber der Sohn eines ägyptischen Mannes* — ging unter die Söhne Israel aus. Und der Sohn der Israelitin und ein israelitischer Mann rauften sich im Lager.", heading: "Gesetz über Gotteslästerung, Totschlag und Körperverletzung", footnotes: ["℘ 2Mo 12,38"] },
      { number: 11, text: "Und der Sohn der israelitischen Frau lästerte den Namen <des HERRN> und verfluchte <ihn>*. Da brachten sie ihn zu Mose*. Der Name seiner Mutter aber war Schelomit, die Tochter des Dibri, vom Stamm Dan.", footnotes: ["℘ Jes 8,21", "℘ 2Mo 18,26"] },
      { number: 12, text: "Und sie legten ihn in Gewahrsam, damit ihnen nach dem Mund des HERRN Bescheid gegeben würde*.", footnotes: ["℘ 2Mo 18,15; 4Mo 27,5"] },
      { number: 13, text: "Und der HERR redete zu Mose:" },
      { number: 14, text: "Führe den Flucher nach draußen vor das Lager! Und alle, die es gehört haben, sollen ihre Hände auf seinen Kopf legen, und die ganze Gemeinde soll ihn steinigen*.", footnotes: ["℘ Kap. 20,2; 4Mo 15,35"] },
      { number: 15, text: "Und zu den Söhnen Israel sollst du reden: Wenn irgendjemand seinen Gott verflucht, dann soll er seine Sünde tragen*.", footnotes: ["℘ 2Mo 20,7; 4Mo 9,13"] },
      { number: 16, text: "Und wer den Namen des HERRN lästert, muss getötet werden, die ganze Gemeinde muss ihn steinigen; wie der Fremde, so der Einheimische: Wenn er den Namen lästert, soll er getötet werden*.", footnotes: ["℘ Kap. 20,2; 1Kö 21,10.13; Mt 26,65.66; Joh 10,33; 19,7"] },
      { number: 17, text: "Wenn jemand irgendeinen Menschen* totschlägt, muss er getötet werden*.", footnotes: ["w. irgendeine Seele (o. Person) der Menschen", "℘ 1Mo 9,5.6; Mt 5,21"] },
      { number: 18, text: "Wer ein <Stück> Vieh totschlägt, soll es erstatten*: Leben um Leben*.", footnotes: ["℘ 2Mo 21,33-36", "w. Wer die Seele eines Viehs totschlägt, soll es unversehrt (o. vollständig) machen, Seele um Seele"] },
      { number: 19, text: "Wenn jemand seinem Nächsten einen Schaden* zufügt; wie er getan hat, so soll ihm getan werden:", footnotes: ["w. einen Makel"] },
      { number: 20, text: "Bruch um Bruch, Auge um Auge, Zahn um Zahn; wie er einem Menschen einen Schaden* zufügt, so soll ihm zugefügt werden*.", footnotes: ["w. einen Makel", "℘ 2Mo 21,23-25; Ri 1,7"] },
      { number: 21, text: "Wer ein <Stück> Vieh totschlägt, soll es erstatten*; wer aber einen Menschen totschlägt, soll getötet werden*.", footnotes: ["w. unversehrt o. vollzählig machen", "℘ 1Mo 9,5.6; Mt 5,21"] },
      { number: 22, text: "Ein Recht sollt ihr haben: Wie der Fremde, so soll der Einheimische sein*; denn ich bin der HERR, euer Gott. —", footnotes: ["℘ 2Mo 12,49; 5Mo 1,16"] },
      { number: 23, text: "Und Mose redete zu den Söhnen Israel, und sie führten den Flucher vor das Lager hinaus und steinigten ihn; und die Söhne Israel taten, wie der HERR dem Mose befohlen hatte*.", footnotes: ["℘ Kap. 16,34; 2Mo 12,28.35.50"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Und der HERR redete auf dem Berg Sinai zu Mose:", heading: "Sabbat- und Jobeljahr" },
      { number: 2, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ihr in das Land kommt, das ich euch geben werde, dann soll das Land dem HERRN einen Sabbat feiern*.", footnotes: ["w. Sabbat ruhen\n℘ Kap. 26,34.35"] },
      { number: 3, text: "Sechs Jahre sollst du dein Feld besäen und sechs Jahre deinen Weinberg beschneiden und den Ertrag des Landes* einsammeln.", footnotes: ["w. seinen Ertrag"] },
      { number: 4, text: "Aber im siebten Jahr soll ein ganz feierlicher Sabbat* für das Land sein; ein Sabbat dem HERRN. Dein Feld sollst du nicht besäen und deinen Weinberg nicht beschneiden,", footnotes: ["w. ein Sabbat der Sabbatfeier"] },
      { number: 5, text: "den Nachwuchs deiner Ernte sollst du nicht einernten, und die Trauben deines unbeschnittenen Weinstocks sollst du nicht abschneiden. Ein Jahr der Sabbatfeier soll es für das Land sein." },
      { number: 6, text: "Und der Sabbat<ertrag> des Landes soll euch zur Speise dienen*, dir und deinem Knecht und deiner Magd und deinem Tagelöhner und deinem Beisassen*, die sich bei dir aufhalten.", footnotes: ["℘ 2Kö 19,29", "Das Wort bezeichnet einen Ansässigen ohne Bürgerrecht, das war ein sozialer Stand zwischen dem Sklaven und dem Vollbürger."] },
      { number: 7, text: "Auch deinem Vieh und den wilden Tieren, die in deinem Land sind, soll all sein Ertrag zur Speise dienen*.", footnotes: ["℘ 2Mo 23,10.11"] },
      { number: 8, text: "Und du sollst dir sieben Sabbatjahre zählen, siebenmal sieben Jahre, so dass die Tage von sieben Sabbatjahren dir 49 Jahre ausmachen." },
      { number: 9, text: "Und du sollst im siebten Monat, am Zehnten des Monats, ein Lärmhorn erschallen lassen; an dem Versöhnungstag* sollt ihr ein Horn durch euer ganzes Land erschallen lassen*.", footnotes: ["℘ Kap. 16,29.30", "℘ 4Mo 10,10; Ps 89,16"] },
      { number: 10, text: "Und ihr sollt das Jahr des fünfzigsten Jahres heiligen, und sollt im Land Freilassung für all seine Bewohner ausrufen*. Ein Jobel<jahr>* soll es euch sein, und ihr werdet jeder wieder zu seinem Eigentum kommen und jeder zu seiner Sippe zurückkehren*.", footnotes: ["℘ Jer 34,14-17; Hes 46,17; Lk 4,18", "Das hebr. Wort jobel bedeutet ursprünglich »Widder«, »Widderhorn«. Da man das Erlassjahr durch das Blasen des Jobel-Horns eröffnete, wurde das Erlassjahr auch Jobeljahr genannt.", "℘ 4Mo 36,4"] },
      { number: 11, text: "Ein Jobel<jahr>* soll dieses, das Jahr des fünfzigsten Jahres, für euch sein. Ihr dürft nicht säen und seinen Nachwuchs nicht ernten und seine unbeschnittenen Weinstöcke nicht abernten*;", footnotes: ["Das hebr. Wort jobel bedeutet ursprünglich »Widder«, »Widderhorn«. Da man das Erlassjahr durch das Blasen des Jobel-Horns eröffnete, wurde das Erlassjahr auch Jobeljahr genannt.", "w. abschneiden"] },
      { number: 12, text: "denn ein Jobel<jahr>* ist es: Es soll euch heilig sein. Vom Feld weg sollt ihr seinen Ertrag essen.", footnotes: ["Das hebr. Wort jobel bedeutet ursprünglich »Widder«, »Widderhorn«. Da man das Erlassjahr durch das Blasen des Jobel-Horns eröffnete, wurde das Erlassjahr auch Jobeljahr genannt."] },
      { number: 13, text: "In diesem Jahr des Jobels* sollt ihr jeder wieder zu seinem Eigentum kommen*.", footnotes: ["Das hebr. Wort jobel bedeutet ursprünglich »Widder«, »Widderhorn«. Da man das Erlassjahr durch das Blasen des Jobel-Horns eröffnete, wurde das Erlassjahr auch Jobeljahr genannt.", "℘ V. 28; Kap. 27,17-24; Jes 61,2; Hes 7,13"] },
      { number: 14, text: "Und wenn ihr etwas verkauft — <sei es> ein Verkauf an deinen Nächsten oder ein Kaufen aus der Hand deines Nächsten —, dann sollt ihr euch gegenseitig nicht übervorteilen*.", footnotes: ["℘ Kap. 19,13; Jes 3,14.15"] },
      { number: 15, text: "Nach der Zahl der Jahre seit dem Jobel<jahr>* sollst du von deinem Nächsten kaufen; nach der Zahl der Erntejahre soll er dir verkaufen.", footnotes: ["Das hebr. Wort jobel bedeutet ursprünglich »Widder«, »Widderhorn«. Da man das Erlassjahr durch das Blasen des Jobel-Horns eröffnete, wurde das Erlassjahr auch Jobeljahr genannt."] },
      { number: 16, text: "Nach dem Verhältnis der größeren Zahl von Jahren sollst du ihm den Kaufpreis vergrößern, und nach dem Verhältnis der geringeren Zahl von Jahren sollst du ihm den Kaufpreis verringern; denn eine Zahl von Ernten verkauft er dir*.", footnotes: ["℘ Kap. 27,18"] },
      { number: 17, text: "Und so soll keiner von euch seinen Nächsten übervorteilen*. Und du sollst dich fürchten vor deinem Gott; denn ich bin der HERR, euer Gott*.", footnotes: ["℘ Kap. 19,13; Jes 3,14.15", "℘ V. 36.43; Kap. 19,14; 1Mo 42,18; Spr 16,6"] },
      { number: 18, text: "So führt meine Ordnungen aus und haltet meine Rechtsbestimmungen* und tut sie*, dann werdet ihr in eurem Land sicher wohnen*!", footnotes: ["o. beachtet meine Rechtsentscheidungen", "℘ Kap. 19,19.37", "℘ Kap. 26,6; 5Mo 12,10; 1Kö 5,5; Spr 1,33"] },
      { number: 19, text: "Und das Land wird seine Frucht geben, und ihr werdet essen bis zur Sättigung* und sicher in ihm wohnen*.", footnotes: ["℘ Kap. 26,4.5; Jes 1,19; 30,23", "℘ Kap. 26,6; 5Mo 12,10; 1Kö 5,5; Spr 1,33"] },
      { number: 20, text: "Und wenn ihr sagt: Was sollen wir im siebten Jahr essen? — siehe, wir säen nicht, und unsern Ertrag sammeln wir nicht ein —:" },
      { number: 21, text: "Ich werde im sechsten Jahr meinen Segen für euch aufbieten, dass es den Ertrag für drei Jahre bringt*.", footnotes: ["℘ 2Mo 16,29"] },
      { number: 22, text: "Und wenn ihr im achten Jahr sät, werdet ihr <noch> altes <Getreide> vom Ertrag <des sechsten Jahres> essen. Bis ins neunte Jahr, bis sein Ertrag einkommt, werdet ihr altes <Getreide> essen.*", footnotes: ["℘ Kap. 26,10; 2Mo 16,5.22"] },
      { number: 23, text: "Und das Land soll nicht endgültig* verkauft werden, denn mir gehört das Land*; denn Fremde und Beisassen* seid ihr bei mir*.", footnotes: ["d. h. nicht ohne Einspruchsrecht (V. 23) bzw. nicht ohne Rückkaufsrecht (V. 30); vgl. V. 31", "℘ Hos 9,3", "s. Anm. zu V. 6", "℘ Ps 39,13"] },
      { number: 24, text: "Und im ganzen Land eures Eigentums sollt ihr für das Land Loskauf* gestatten.", footnotes: ["o. Recht (o. Pflicht) des Rückkaufs"] },
      { number: 25, text: "Wenn dein Bruder verarmt und <etwas> von seinem Eigentum* verkauft, dann soll als sein Löser sein nächster Verwandter kommen und das Verkaufte seines Bruders einlösen*.", footnotes: ["Nach V. 24 (Land des Eigentums) ist hier Landbesitz gemeint.", "o. zurückkaufen\n℘ V. 47-55; Rt 4,4.6; Jer 32,7-9"] },
      { number: 26, text: "Wenn aber jemand keinen Löser hat, und seine Hand bringt auf und findet, was zu seinem Loskauf ausreicht*,", footnotes: ["w. und seine Hand erreicht <das Nötige> und findet das <für> seine Einlösung Ausreichende"] },
      { number: 27, text: "dann soll er die Jahre seines Verkaufs berechnen und das, was darüber hinausgeht, dem Mann zurückzahlen, an den er verkauft hat, und so wieder zu seinem Eigentum kommen." },
      { number: 28, text: "Und wenn seine Hand das Ausreichende nicht gefunden hat, um ihm zurückzuzahlen, dann soll das von ihm Verkaufte in der Hand dessen, der es kauft, bleiben bis zum Jobeljahr*; und im Jobel<jahr> soll es frei ausgehen, und er soll wieder zu seinem Eigentum kommen*.", footnotes: ["s. Anm. zu V. 10", "℘ Kap. 27,24"] },
      { number: 29, text: "Und wenn jemand ein Wohnhaus in einer ummauerten Stadt verkauft, soll sein Lösungsrecht* bestehen bis zum Ende des Jahres seines Verkaufs; *eine bestimmte Zeit* soll sein Lösungsrecht bestehen.", footnotes: ["o. Recht (o. Pflicht) des Rückkaufs", "w. Tage", "w. Tage"] },
      { number: 30, text: "Wenn es aber nicht gelöst wird*, bis ihm ein ganzes Jahr voll ist, dann soll das Haus, das in der ummauerten Stadt ist, endgültig* dem, der es kaufte, verbleiben für seine Generationen; es soll im Jobel<jahr>* nicht frei ausgehen.", footnotes: ["o. zurückgekauft wird", "d. h. nicht ohne Einspruchsrecht (V. 23) bzw. nicht ohne Rückkaufsrecht (V. 30); vgl. V. 31", "s. Anm. zu V. 10"] },
      { number: 31, text: "Aber die Häuser der Dörfer, die keine Mauer ringsum haben, sollen zum Feld des Landes gerechnet werden. Es soll Lösungsrecht* für ein solches <Haus> bestehen, und im Jobel<jahr>* wird es frei ausgehen.", footnotes: ["o. Recht (o. Pflicht) des Rückkaufs", "s. Anm. zu V. 10"] },
      { number: 32, text: "Und was die Städte der Leviten, die Häuser der Städte ihres Eigentums betrifft, so soll es ein ewiges Lösungsrecht* für die Leviten geben*,", footnotes: ["o. Recht (o. Pflicht) des Rückkaufs", "℘ 4Mo 35,2-8"] },
      { number: 33, text: "und zwar so: <Einer> von den Leviten mag es einlösen*, oder das vom Haus und der Stadt seines Besitzers Verkaufte mag im Jobel<jahr>* frei ausgehen. Denn die Häuser der Levitenstädte sind ihr Eigentum unter den Söhnen Israel.", footnotes: ["o. zurückkaufen", "s. Anm. zu V. 10"] },
      { number: 34, text: "Aber das Feld des Weideplatzes ihrer Städte darf nicht verkauft werden, denn es gehört ihnen als ewiges Eigentum*.", footnotes: ["℘ 2Chr 31,19; Hes 48,13.14"] },
      { number: 35, text: "Und wenn dein Bruder verarmt und seine Hand* neben dir wankend wird, dann sollst du ihn unterstützen* <wie> den Fremden* und Beisassen*, damit er neben dir leben kann*.", footnotes: ["d. h. sein Besitz", "℘ 5Mo 15,7; Hi 31,16; Spr 14,31; Gal 2,10", "o. <auch> den Fremden", "s. Anm. zu V. 6", "℘ 5Mo 10,18; 15,7.8; 1Jo 3,17"] },
      { number: 36, text: "Du sollst nicht Zins von ihm nehmen* und sollst dich fürchten vor deinem Gott*, damit dein Bruder neben dir lebt.", footnotes: ["℘ 2Mo 22,24; Neh 5,3-11", "℘ V. 17"] },
      { number: 37, text: "Dein Geld sollst du ihm nicht gegen Zins geben, und deine Nahrungsmittel sollst du nicht gegen Aufschlag geben*.", footnotes: ["℘ Hes 22,12; Lk 6,35"] },
      { number: 38, text: "Ich bin der HERR, euer Gott, der ich euch aus dem Land Ägypten herausgeführt habe*, um euch das Land Kanaan zu geben, um euer Gott zu sein*.", footnotes: ["℘ 2Mo 20,2", "℘ Kap. 11,45"] },
      { number: 39, text: "Und wenn dein Bruder bei dir verarmt und sich dir verkauft, sollst du ihn nicht Sklavendienst tun lassen*.", footnotes: ["℘ 2Mo 21,2; 1Kö 9,22; 2Kö 4,1"] },
      { number: 40, text: "Wie ein Tagelöhner, wie ein Beisasse* soll er bei dir sein; bis zum Jobeljahr* soll er bei dir dienen*.", footnotes: ["Das Wort bezeichnet einen Ansässigen ohne Bürgerrecht, das war ein sozialer Stand zwischen dem Sklaven und dem Vollbürger.", "s. Anm. zu V. 10", "℘ 5Mo 15,12"] },
      { number: 41, text: "Dann soll er frei von dir ausgehen, er und seine Kinder mit ihm, und zu seiner Sippe zurückkehren und wieder zum Eigentum seiner Väter kommen." },
      { number: 42, text: "Denn sie sind meine Knechte, die ich aus dem Land Ägypten herausgeführt habe*. Sie sollen nicht verkauft werden, wie man Sklaven verkauft*.", footnotes: ["℘ 2Mo 20,2", "℘ Kap. 26,13"] },
      { number: 43, text: "Du sollst nicht mit Gewalt über ihn herrschen* und sollst dich fürchten vor deinem Gott*.", footnotes: ["℘ 2Chr 28,10; Hi 31,13-15; Kol 4,1", "℘ V. 17"] },
      { number: 44, text: "Was aber deinen Knecht und deine Magd* betrifft, die du haben wirst; von den Nationen, die rings um euch her <leben>, von ihnen mögt ihr Knecht und Magd kaufen*.", footnotes: ["o. deinen Sklaven und deine Sklavin", "℘ Jes 14,2"] },
      { number: 45, text: "Und auch von den Kindern der Beisassen*, die als Fremde bei euch wohnen, von ihnen mögt ihr kaufen und von ihrer Sippe, die bei euch ist, die sie in eurem Land gezeugt haben; und sie mögen euch zum Eigentum sein,", footnotes: ["Das Wort bezeichnet einen Ansässigen ohne Bürgerrecht, das war ein sozialer Stand zwischen dem Sklaven und dem Vollbürger."] },
      { number: 46, text: "und ihr mögt sie euren Söhnen nach euch vererben, um sie als Eigentum zu besitzen. Diese mögt ihr für ewig dienen lassen. Aber über eure Brüder, die Söhne Israel, sollt ihr nicht einer über den andern mit Gewalt* herrschen.", footnotes: ["w. du sollst nicht — einer über den andern — über ihn herrschen mit Gewalt"] },
      { number: 47, text: "Wenn aber die Hand eines Fremden oder eines Beisassen* neben dir etwas erreicht* und <wenn> dein Bruder neben ihm verarmt und sich dem Fremden verkauft, dem Beisassen neben dir oder einem Abkömmling aus der Sippe des Fremden,", footnotes: ["Das Wort bezeichnet einen Ansässigen ohne Bürgerrecht, das war ein sozialer Stand zwischen dem Sklaven und dem Vollbürger.", "d. h. wohlhabend wird"] },
      { number: 48, text: "dann soll, nachdem er sich verkauft hat, Lösungsrecht* für ihn bestehen. Einer von seinen Brüdern soll ihn einlösen*.", footnotes: ["o. das Rückkaufsrecht; o. die Rückkaufspflicht", "o. zurückkaufen\n℘ Neh 5,8"] },
      { number: 49, text: "Entweder sein Onkel oder der Sohn seines Onkels soll ihn einlösen*, oder einer von seinen nächsten Blutsverwandten aus seiner Sippe soll ihn einlösen; oder kann seine Hand <es wieder> aufbringen*, dann soll er sich selbst einlösen*.", footnotes: ["o. zurückkaufen", "w. erreichen", "℘ V. 26-28"] },
      { number: 50, text: "Und er soll mit seinem Käufer von dem Jahr an rechnen, in dem er sich ihm verkauft hat, bis zum Jobeljahr*. Und der Preis, um den er sich verkauft hat, soll der Zahl der Jahre entsprechen*; nach den Tagen eines Tagelöhners soll er bei ihm sein*.", footnotes: ["s. Anm. zu V. 10", "d. h. mit der Anzahl seiner Dienstjahre verrechnet werden", "d. h. seine Arbeitszeit soll ihm angerechnet werden entsprechend der Arbeitszeit eines Tagelöhners"] },
      { number: 51, text: "Wenn es noch viele Jahre sind, soll er nach ihrem Verhältnis seinen Loskauf von seinem Kaufgeld zurückzahlen." },
      { number: 52, text: "Und wenn wenig übrig ist an den Jahren bis zum Jobeljahr*, dann soll er es ihm berechnen: Nach dem Verhältnis seiner Jahre soll er seinen Loskauf zurückzahlen.", footnotes: ["s. Anm. zu V. 10"] },
      { number: 53, text: "Wie ein Tagelöhner soll er Jahr für Jahr bei ihm sein. Er darf vor deinen Augen nicht mit Gewalt über ihn herrschen." },
      { number: 54, text: "Und wenn er nicht in dieser Weise eingelöst* wird, dann soll er im Jobeljahr* frei ausgehen, er und seine Kinder mit ihm.", footnotes: ["o. zurückgekauft", "s. Anm. zu V. 10"] },
      { number: 55, text: "Denn mir gehören die Söhne Israel als Knechte. Meine Knechte sind sie, die ich aus dem Land Ägypten herausgeführt habe*. Ich bin der HERR, euer Gott.", footnotes: ["℘ 2Mo 20,2"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Ihr sollt euch keine Götzen machen, und ein Götterbild* und einen Gedenkstein* sollt ihr euch nicht aufrichten*, und keinen Stein mit Bildwerk sollt ihr in eurem Land hinstellen*, um euch davor anbetend niederzuwerfen*; denn ich bin der HERR, euer Gott.", heading: "Segen und Fluch", footnotes: ["d. i. ein aus Stein gehauenes o. aus Holz geschnitztes Bild", "hebr. mazzeba; das ist ein aufrecht hingestellter Stein, der kultisch verehrt wurde", "℘ Ri 18,30; 2Kö 17,8.10", "o. zulassen", "℘ Kap. 19,4; 2Mo 20,4.5"] },
      { number: 2, text: "Meine Sabbate sollt ihr halten, und mein Heiligtum sollt ihr fürchten*. Ich bin der HERR.", footnotes: ["℘ Kap. 19,30"] },
      { number: 3, text: "*Wenn ihr in meinen Ordnungen lebt* und meine Gebote haltet und sie tut*,", footnotes: ["℘ V. 3-13: 5Mo 28,1-14", "w. geht", "℘ Neh 1,9"] },
      { number: 4, text: "dann werde ich euch die Regen<güsse> geben zu ihrer Zeit*, und das Land wird seinen Ertrag geben, und die Bäume des Feldes werden ihre Frucht geben*.", footnotes: ["℘ 5Mo 11,13.14", "℘ Ps 65,10-14; 67,7; 85,13; Hes 34,27"] },
      { number: 5, text: "Und die Dreschzeit wird bei euch bis zur Weinlese reichen, und die Weinlese wird bis zur Saatzeit reichen*. Und ihr werdet euer Brot essen bis zur Sättigung* und werdet sicher in eurem Land wohnen*.", footnotes: ["℘ Am 9,13", "℘ 5Mo 11,15; Joe 2,22-24", "℘ Kap. 25,19; Jes 1,19; 30,23"] },
      { number: 6, text: "Und ich werde Frieden im Land geben, dass ihr euch niederlegt und es niemand gibt, der <euch> aufschreckt*. Und ich werde die bösen Tiere aus dem Land austilgen*, und das Schwert wird nicht durch euer Land gehen*.", footnotes: ["℘ Kap. 25,18; 2Chr 20,30; Ps 147,14", "℘ Jes 35,9; Hes 34,25", "℘ Ps 144,14; Hos 2,20; 14,10"] },
      { number: 7, text: "Und ihr werdet euren Feinden nachjagen*, und sie werden vor euch durchs Schwert fallen*.", footnotes: ["℘ Ri 7,23", "℘ Jos 23,10; Ri 15,15; 1Sam 14,13; Ps 81,15"] },
      { number: 8, text: "Fünf von euch werden hundert nachjagen, und hundert von euch werden zehntausend nachjagen, und eure Feinde werden vor euch durchs Schwert fallen." },
      { number: 9, text: "Und ich werde mich zu euch wenden und euch fruchtbar machen und euch mehren* und meinen Bund mit euch aufrechterhalten*.", footnotes: ["℘ 1Kö 3,8", "℘ Jer 23,4"] },
      { number: 10, text: "Und ihr werdet das alt gewordene alte <Getreide noch zu> essen <haben> und das alte vor dem neuen wegräumen müssen*.", footnotes: ["℘ Kap. 25,22"] },
      { number: 11, text: "Und ich werde meine Wohnung in eure Mitte setzen*, und meine Seele wird euch nicht verabscheuen.", footnotes: ["℘ 2Mo 29,45.46; Jos 22,31; Hes 37,26"] },
      { number: 12, text: "Und ich werde in eurer Mitte leben* und werde euer Gott sein, und ihr werdet mein Volk sein*.", footnotes: ["w. gehen", "℘ 5Mo 23,15; Jer 7,23; Joe 2,27; 2Kor 6,16"] },
      { number: 13, text: "Ich bin der HERR, euer Gott, der ich euch aus dem Land Ägypten herausgeführt habe*, damit ihr nicht ihre Knechte sein solltet*. Und ich habe die Stangen eures Joches zerbrochen* und euch aufrecht gehen lassen.", footnotes: ["℘ 2Mo 14,8; 20,2", "℘ Kap. 25,42", "℘ Jes 9,3; Jer 28,2; Hes 34,27; Nah 1,13"] },
      { number: 14, text: "*Wenn ihr mir aber nicht gehorcht* und nicht all diese Gebote tut", footnotes: ["℘ V. 14-39: 5Mo 28,15-68", "℘ Ps 81,12"] },
      { number: 15, text: "und wenn ihr meine Ordnungen verwerft und eure Seele meine Rechtsbestimmungen verabscheut*, so dass ihr nicht alle meine Gebote tut und dass ihr meinen Bund brecht*,", footnotes: ["℘ 2Chr 36,16; Ps 50,17", "℘ Jer 31,32"] },
      { number: 16, text: "dann werde ich meinerseits euch dieses tun: Ich werde Entsetzen* über euch verhängen, Schwindsucht und Fieberglut, die die Augen erlöschen und die Seele verschmachten lassen. Und ihr werdet vergeblich euren Samen säen, denn eure Feinde werden ihn verzehren*.", footnotes: ["o. plötzliches Unglück", "℘ Hi 31,8; Jer 5,17; 12,13; Mi 6,15"] },
      { number: 17, text: "Und ich werde mein Angesicht gegen euch richten*, dass ihr vor euren Feinden geschlagen werdet*. Und eure Hasser werden über euch herrschen*, und ihr werdet fliehen, obwohl niemand euch nachjagt*.", footnotes: ["℘ Kap. 17,10; 1Sam 12,15; Jes 63,10; Kla 2,4.5", "℘ 1Sam 4,10; 1Kö 8,33; 2Kö 13,3.7", "℘ Ri 2,14; 3,8; 6,2; Neh 9,27", "℘ Ps 53,6; Spr 28,1; Jes 30,17"] },
      { number: 18, text: "Und wenn ihr mir daraufhin nicht gehorcht, dann werde ich fortfahren, euch zu züchtigen, <und zwar> siebenmal wegen eurer Sünden*.", footnotes: ["℘ 2Mo 9,14; Jes 5,25"] },
      { number: 19, text: "Und ich werde euren starken Hochmut* brechen und werde euren Himmel wie Eisen machen* und eure Erde wie Bronze.", footnotes: ["w. den Hochmut eurer Stärke", "℘ 1Kö 8,35; Jer 14,4; Hes 33,28"] },
      { number: 20, text: "Und eure Kraft wird sich umsonst verbrauchen, und euer Land wird seinen Ertrag nicht geben, und die Bäume des Landes werden ihre Frucht nicht geben*.", footnotes: ["℘ 1Mo 4,12; 5Mo 11,17; 1Kö 18,2; Hos 2,11"] },
      { number: 21, text: "Wenn ihr euch aber mir entgegenstellt* und mir nicht gehorchen wollt, dann werde ich euch weiter schlagen, <und zwar> siebenfach nach euren Sünden*.", footnotes: ["w. in eine feindliche Begegnung mit mir begebt", "℘ 2Mo 9,14; Jes 5,25"] },
      { number: 22, text: "Und ich werde die Tiere des Feldes unter euch senden, dass sie euch kinderlos machen* und euer Vieh ausrotten und euch <an Zahl> verringern*, und eure Wege sollen öde werden*.", footnotes: ["℘ 2Kö 2,24", "℘ Hes 5,17", "℘ Ri 5,6; Jes 33,8; Kla 1,4"] },
      { number: 23, text: "Und wenn ihr euch dadurch nicht von mir zurechtweisen lasst und euch mir entgegenstellt*,", footnotes: ["w. in eine feindliche Begegnung mit mir begebt\n℘ Jer 5,3; Dan 9,13; Am 4,6-11"] },
      { number: 24, text: "dann werde ich meinerseits mich euch entgegenstellen*, und ich meinerseits werde euch schlagen, <und zwar> siebenfach wegen eurer Sünden*.", footnotes: ["w. mich in eine feindliche Begegnung mit euch bzw. ihnen begeben", "℘ 2Sam 22,27"] },
      { number: 25, text: "Und ich werde das Schwert über euch bringen*, das die Rache des Bundes vollzieht. Und zieht ihr euch in eure Städte zurück, dann werde ich die Pest in eure Mitte senden*, und ihr werdet in die Hand des Feindes gegeben werden*.", footnotes: ["℘ 5Mo 32,25; 2Kö 17,3; Jes 1,20; 65,12; Hes 6,3; Hos 11,6", "℘ Hab 3,5", "℘ 2Mo 5,3; 2Chr 24,24; Jer 19,7"] },
      { number: 26, text: "Wenn ich euch den Stab* des Brotes zerbreche*, werden zehn Frauen euer Brot in einem Ofen backen, und sie werden euch das Brot zurückgeben nach dem Gewicht*; und ihr werdet essen und nicht satt werden*.", footnotes: ["das sind die Stöcke, an denen die ringförmigen Brote aufgehängt sind", "℘ 2Kö 6,25; Ps 105,16; Jes 3,1; Hes 4,16", "d. h. genau abgemessen", "℘ Jes 9,19"] },
      { number: 27, text: "Und wenn ihr bei alldem mir nicht gehorcht und euch mir entgegenstellt*,", footnotes: ["w. in eine feindliche Begegnung mit mir begebt"] },
      { number: 28, text: "dann werde ich mich euch im Grimm entgegenstellen*, und ich meinerseits werde euch züchtigen wegen eurer Sünden, <und zwar> siebenfach.", footnotes: ["w. mich in eine grimmige feindliche Begegnung mit euch begeben\n℘ Jer 7,20; Kla 4,11"] },
      { number: 29, text: "Und ihr werdet das Fleisch eurer Söhne essen, und das Fleisch eurer Töchter werdet ihr essen*.", footnotes: ["℘ 2Kö 6,29; Jer 19,9; Hes 5,10"] },
      { number: 30, text: "Und ich werde eure Höhen* austilgen und eure Räucheraltäre ausrotten, und ich werde eure Leichen auf die Leichen eurer Götzen* werfen*, und meine Seele wird euch verabscheuen*.", footnotes: ["d. h. Höhenaltäre, o. Höhenheiligtümer", "w. Mistkugeln, o. Klötze; d. i. ein verächtlicher Ausdruck", "℘ 2Chr 34,4; Hes 6,3-6; 16,39", "℘ Ps 106,40; Jer 16,18; Hos 10,2"] },
      { number: 31, text: "Und ich werde eure Städte zur Trümmerstätte machen* und eure Heiligtümer öde machen*, und ich werde euren wohlgefälligen Geruch* nicht riechen*.", footnotes: ["℘ 2Kö 25,9; Neh 1,3; Jer 4,7; Kla 1,1; Hes 12,20", "℘ Ps 74,7; Kla 1,1; 2,6.7; Hes 6,6", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Jes 1,13"] },
      { number: 32, text: "Und ich werde das Land öde machen, dass eure Feinde, die darin wohnen, sich darüber entsetzen sollen*.", footnotes: ["℘ 5Mo 29,23.24; Jer 18,16; Hes 5,15"] },
      { number: 33, text: "Euch aber werde ich unter die Nationen zerstreuen*, und ich werde das Schwert hinter euch herziehen*. Euer Land wird eine Öde* und eure Städte werden eine Trümmerstätte sein*.", footnotes: ["℘ 2Kö 25,9; Neh 1,3; Jer 4,7; Kla 1,1; Hes 12,20", "℘ 5Mo 4,27; Ps 44,12", "℘ Jes 6,11; Jer 8,3; 15,4; Hos 9,6", "℘ Jes 6,11; Jer 8,3; 15,4; Hos 9,6"] },
      { number: 34, text: "Dann endlich wird das Land seine Sabbate ersetzt bekommen*,* all die Tage seiner Verödung, während ihr im Land eurer Feinde seid. Dann endlich wird das Land ruhen und seine Sabbate ersetzt bekommen.", footnotes: ["o. abtragen", "℘ 2Chr 36,21"] },
      { number: 35, text: "All die Tage seiner Verödung wird es ruhen, was es nicht an euren Sabbaten geruht hat, als ihr darin wohntet*.", footnotes: ["℘ Kap. 25,2"] },
      { number: 36, text: "Und die Übriggebliebenen von euch — in ihr Herz werde ich Verzagtheit bringen in den Ländern ihrer Feinde; und das Rauschen eines verwehten Blattes wird sie verfolgen, und sie werden fliehen, wie man vor dem Schwert flieht, und fallen, obwohl niemand sie verfolgt*.", footnotes: ["℘ V. 17"] },
      { number: 37, text: "Und sie werden einer über den andern hinstürzen* wie vor dem Schwert, obwohl niemand sie verfolgt*; und ihr werdet vor euren Feinden nicht standhalten können*.", footnotes: ["℘ Jer 46,16", "℘ V. 17", "℘ Ri 2,14; 1Sam 4,2"] },
      { number: 38, text: "Ihr werdet umkommen unter den Nationen, und das Land eurer Feinde wird euch fressen*.", footnotes: ["℘ Jer 22,12"] },
      { number: 39, text: "Und die Übriggebliebenen von euch werden in den Ländern eurer Feinde vergehen* in ihrer Schuld und auch in der Schuld ihrer Väter mit ihnen vergehen*.", footnotes: ["w. verfaulen", "o. durch ihre Schuld und durch die Schuld ihrer Väter verfaulen\n℘ 5Mo 8,20; 2Chr 34,24"] },
      { number: 40, text: "Und sie werden ihre Schuld bekennen* und die Schuld ihrer Väter, die in ihrer Untreue <liegt>, mit der sie an mir treulos gehandelt haben, und besonders darin, dass sie sich mir entgegengestellt haben*.", footnotes: ["℘ Kap. 5,5; 5Mo 30,2; Dan 9,4", "w. sich in eine feindliche Begegnung mit mir begeben haben\n℘ 1Kö 8,33.47; Esr 9,6.7; Neh 9,2.3; Jer 3,13; Kla 1,20"] },
      { number: 41, text: "Ich meinerseits werde mich ihnen entgegenstellen* und sie in das Land ihrer Feinde bringen; ob sich endlich ihr unbeschnittenes Herz* demütigt* und sie endlich ihre Schuld bezahlen*.", footnotes: ["w. mich in eine feindliche Begegnung mit euch bzw. ihnen begeben", "℘ Jer 9,25; Apg 7,51", "℘ 2Chr 12,6; Esr 9,15", "o. abtragen\n℘ Neh 9,33; Hes 14,23"] },
      { number: 42, text: "Dann werde ich an meinen Bund mit Jakob denken*. Und auch an meinen Bund mit Isaak und auch an meinen Bund mit Abraham werde ich denken, und an das Land werde ich denken.", footnotes: ["℘ 1Mo 15,18; 26,24; 28,15; 5Mo 4,31; 9,27; Lk 1,72.73; Röm 11,28"] },
      { number: 43, text: "Denn das Land muss von ihnen verlassen sein, damit es in seiner Verödung ohne sie seine Sabbate ersetzt bekommt*, und sie selbst werden ihre Schuld bezahlen*, darum, ja deshalb, weil sie meine Rechtsbestimmungen verworfen haben und ihre Seele meine Ordnungen verabscheut hat.", footnotes: ["o. abträgt\n℘ 2Chr 36,21", "o. abtragen"] },
      { number: 44, text: "Aber selbst auch dann, wenn sie in dem Land ihrer Feinde sind, werde ich sie nicht verwerfen und sie nicht verabscheuen, ein Ende mit ihnen zu machen*, meinen Bund mit ihnen ungültig zu machen*; denn ich bin der HERR, ihr Gott.", footnotes: ["℘ Neh 9,17.31; Ps 94,14; 103,13; Jer 24,5; 31,20", "℘ 1Mo 17,7; Röm 11,2.29"] },
      { number: 45, text: "Und ich werde <zum Guten> für sie an meinen Bund mit den Vorfahren denken*, die ich aus dem Land Ägypten vor den Augen der Nationen herausgeführt habe, um ihr Gott zu sein*. Ich bin der HERR.", footnotes: ["℘ 1Mo 15,18; 26,24; 28,15; 5Mo 4,31; 9,27; Lk 1,72.73; Röm 11,28", "℘ Kap. 11,45"] },
      { number: 46, text: "Das sind die Ordnungen und die Rechtsbestimmungen und die Gesetze*, die der HERR zwischen sich und den Söhnen Israel auf dem Berg Sinai durch Mose gegeben hat*.", footnotes: ["o. die Weisungen", "℘ Kap. 27,34; 5Mo 33,4; Joh 1,17"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Gesetz über Gelübde und Zehnten" },
      { number: 2, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn jemand ein <besonderes> Gelübde leistet*, dann sollen die Personen* für den HERRN* nach <folgender> Schätzung <berechnet werden>:", footnotes: ["Andere üs. mit geringfügiger Änderung: erfüllt\n℘ 4Mo 30,3; 5Mo 23,22; 1Sam 1,11; Pred 5,3.4", "o. Seelen", "o. Wenn jemand dem HERRN <durch ein besonderes> Gelübde Seelen weiht, sollen sie"] },
      { number: 3, text: "Wenn deine Schätzung einen Mann* von zwanzig Jahren bis zu sechzig Jahren betrifft, dann sei deine Schätzung fünfzig Schekel Silber, nach dem Schekel des Heiligtums*.", footnotes: ["w. eine männliche <Person>", "℘ V. 25; Kap. 5,15; 2Mo 30,13; 38,24"] },
      { number: 4, text: "Und wenn es eine Frau* ist, dann sei die Schätzung dreißig Schekel.", footnotes: ["w. eine weibliche <Person>"] },
      { number: 5, text: "Und wenn es von fünf Jahren bis zu zwanzig Jahren ist, dann sei deine Schätzung einer männlichen <Person> zwanzig Schekel* und einer weiblichen zehn Schekel.", footnotes: ["℘ 1Mo 37,28"] },
      { number: 6, text: "Und wenn es von einem Monat bis zu fünf Jahren ist, dann sei die Schätzung einer männlichen <Person> fünf Schekel Silber und die Schätzung einer weiblichen drei Schekel Silber." },
      { number: 7, text: "Und wenn es von sechzig Jahren und darüber ist, dann sei die Schätzung, wenn es eine männliche <Person> ist, fünfzehn Schekel und für eine weibliche zehn Schekel." },
      { number: 8, text: "Und *wenn der, der das Gelübde getan hat*, zu arm ist* für die Schätzung, dann soll man ihn* vor den Priester stellen, und der Priester soll ihn schätzen; nach dem Verhältnis dessen, was die Hand des Gelobenden aufbringen kann, soll der Priester ihn schätzen.", footnotes: ["w. wenn er", "w. wenn er", "℘ Kap. 5,7", "d. i. die zu weihende Person"] },
      { number: 9, text: "Und wenn es Vieh ist, von dem man dem HERRN eine Opfergabe darbringt*, dann soll alles, was man dem HERRN davon gibt, heilig sein.", footnotes: ["d. h. Vieh, das zum Opfer tauglich ist"] },
      { number: 10, text: "Man soll es nicht auswechseln und nicht vertauschen, ein gutes gegen ein schlechtes oder ein schlechtes gegen ein gutes. Und wenn man dennoch Vieh gegen Vieh vertauscht, dann soll es selbst <heilig> bleiben, das eingetauschte aber wird heilig werden*.", footnotes: ["℘ V. 33"] },
      { number: 11, text: "Wenn es aber irgendein unreines Vieh ist, von dem man dem HERRN keine Opfergabe darbringt, dann soll man das Vieh vor den Priester stellen," },
      { number: 12, text: "und der Priester soll es schätzen, ob es gut oder schlecht ist; nach der Schätzung des Priesters, so soll es sein." },
      { number: 13, text: "Wenn man es aber unbedingt <wieder> einlösen will, dann soll man zu der Schätzung ein Fünftel hinzufügen*.", footnotes: ["℘ V. 27.31; Kap. 5,16"] },
      { number: 14, text: "Und wenn jemand sein Haus als etwas Heiliges für den HERRN heiligt, dann soll es der Priester schätzen, ob es gut oder schlecht ist. Wie der Priester es schätzt, so soll es feststehen." },
      { number: 15, text: "Und wenn der Heiligende sein Haus einlösen will, dann soll er das Fünftel des Geldes der Schätzung darüber hinaus hinzufügen*, und es soll ihm gehören.", footnotes: ["℘ V. 27.31; Kap. 5,16"] },
      { number: 16, text: "Und wenn jemand vom Feld seines Eigentums dem HERRN <etwas> heiligt, dann soll die Schätzung nach dem Verhältnis seiner Aussaat sein: ein Homer Gerste Aussaat für fünfzig Schekel Silber." },
      { number: 17, text: "Wenn er vom Jobeljahr* an sein Feld heiligt, soll es gemäß der Schätzung feststehen.", footnotes: ["vgl. Kap. 25,10\n℘ Kap. 25,10"] },
      { number: 18, text: "Wenn er aber nach dem Jobel<jahr>* sein Feld heiligt, dann soll der Priester ihm das Geld berechnen nach dem Verhältnis der Jahre, die bis zum Jobeljahr* übrig sind; das soll <dann> von der Schätzung abgezogen werden*.", footnotes: ["vgl. Kap. 25,10", "vgl. Kap. 25,10", "℘ Kap. 25,15.16"] },
      { number: 19, text: "Wenn aber der Heiligende das Feld unbedingt <wieder> einlösen will, dann soll er das Fünftel des Geldes deiner Schätzung darüber hinaus hinzufügen, und es soll ihm verbleiben." },
      { number: 20, text: "Wenn er aber das Feld <bis zum Jobeljahr*> nicht einlöst oder wenn er das Feld an einen andern Mann verkauft, kann es nicht wieder eingelöst werden.", footnotes: ["vgl. Kap. 25,10"] },
      { number: 21, text: "Und das Feld soll, wenn es im Jobel<jahr>* frei ausgeht, für den HERRN heilig sein wie ein gebanntes* Feld. Es soll dem Priester als Eigentum gehören*.", footnotes: ["vgl. Kap. 25,10", "d. h. geweihtes", "℘ 4Mo 18,14; Jos 6,17-19; Hes 44,29"] },
      { number: 22, text: "Und wenn er ein von ihm gekauftes Feld, das nicht zum Feld seines Eigentums gehört, dem HERRN heiligt," },
      { number: 23, text: "dann soll ihm der Priester den Betrag der Schätzung berechnen bis zum Jobeljahr*. Er soll die Schätzung am gleichen Tag als etwas für den HERRN Heiliges entrichten.", footnotes: ["vgl. Kap. 25,10"] },
      { number: 24, text: "Im Jobeljahr* soll das Feld wieder an den kommen, von dem er es gekauft hatte, an den, dem das Land als sein Eigentum gehörte*.", footnotes: ["vgl. Kap. 25,10", "℘ Kap. 25,28"] },
      { number: 25, text: "Und alle Schätzung soll nach dem Schekel des Heiligtums geschehen; zwanzig Gera soll der Schekel sein." },
      { number: 26, text: "Nur das Erstgeborene unter dem Vieh, das als Erstgeburt dem HERRN gehört*, das soll kein Mensch heiligen; sei es ein Rind oder ein Schaf*, es gehört dem HERRN*.", footnotes: ["w. das dem HERRN erstgeboren wird", "o. Ziege; o. Lamm", "℘ 2Mo 13,2.12"] },
      { number: 27, text: "Wenn es aber vom unreinen Vieh ist, dann soll man es auslösen nach der Schätzung und sein Fünftel darüber hinzufügen*. Und wenn es nicht ausgelöst wird, dann soll es verkauft werden nach der Schätzung. —", footnotes: ["℘ V. 27.31; Kap. 5,16"] },
      { number: 28, text: "Jedoch alles Gebannte, das jemand für den HERRN mit dem Bann belegt*, von allem, was ihm gehört, von Mensch oder Vieh oder vom Feld seines Eigentums, <das> darf nicht verkauft und nicht eingelöst werden*. Alles Gebannte ist dem HERRN hochheilig*.", footnotes: ["d. i. die absolute Form, etwas für Gott zu weihen", "℘ 4Mo 18,14; Jos 6,17-19; Hes 44,29", "℘ Kap. 21,22"] },
      { number: 29, text: "Alles Gebannte, das an Menschen mit dem Bann belegt wird, darf nicht ausgelöst werden: es muss getötet werden*.", footnotes: ["℘ 4Mo 21,2.3; 1Sam 15,3; 1Kö 20,42"] },
      { number: 30, text: "Und der ganze Zehnte des Landes, vom Samen des Landes, von der Frucht der Bäume, gehört dem HERRN; es ist dem HERRN heilig*.", footnotes: ["℘ 1Mo 47,24.26; 2Chr 31,6.12; Neh 10,38; Mt 23,23"] },
      { number: 31, text: "Wenn aber jemand von seinem Zehnten <irgendetwas> einlösen will, dann soll er sein Fünftel hinzufügen*.", footnotes: ["℘ V. 27.31; Kap. 5,16"] },
      { number: 32, text: "Und der ganze Zehnte von Rindern und Schafen, von allem, was unter dem Stab* vorüberzieht*, das Zehnte soll für den HERRN heilig sein*.", footnotes: ["d. h. des Hirten", "℘ Jer 33,13", "℘ 1Mo 28,22; 4Mo 18,21.24"] },
      { number: 33, text: "Man soll nicht untersuchen, ob es gut oder schlecht ist, und darf es nicht vertauschen. Wenn man es dennoch irgend vertauscht, wird es selbst <heilig> bleiben, das Eingetauschte aber wird heilig werden; es darf nicht eingelöst werden*.", footnotes: ["℘ V. 10"] },
      { number: 34, text: "Das sind die Gebote, die der HERR dem Mose auf dem Berg Sinai an die Söhne Israel aufgetragen hat.*", footnotes: ["℘ Kap. 26,46; 4Mo 3,1; 28,6; 36,13; 5Mo 1,3.5"] },
    ]},
  ]
};
